    char          tempbuffer[128] = {0};
    QUEC_FAT_ERR_NUM err = QUEC_FAT_SUCCESS;
    int index = -1;

	*xid_p = MAKE_AT_HANDLE(*(TelAtParserID *)arg_p);
    index = *(TelAtParserID *)arg_p;

    /* save current config to nv */
    err = quectel_nv_fat_write(__QUEC_AT_CONFIG_TABLE, &g_quec_config_desc_current, sizeof(g_quec_config_desc_current));
    if (QUEC_FAT_SUCCESS != err)
    {
         atcmd_general_log("quectel_nv_fat_write failed");
         ret=ATRESP(*xid_p, ATCI_RESULT_CODE_ERROR, 0, NULL);
         return HANDLE_RETURN_VALUE(ret);
    }
    atcmd_general_log("%s write success ", __QUEC_AT_CONFIG_TABLE);

