/*===========================================================================

FUNCTION QUEC_BASIC_ATC_CMD

DESCRIPTION
  This function takes the result from the command line parser
  and executes it. It executes C command.


DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.

SIDE EFFECTS
  None
===========================================================================*/
RETURNCODE_T  quec_basic_atc_cmd
(
    const utlAtParameterOp_T       op,                /* AT cmd type          */
	const char                    *command_name_p,	  /* AT cmd name          */
    const utlAtParameterValue_P2c  parameter_values_p,/* AT cmd value         */
    const size_t                   num_parameters,    /* AT cmd number        */
    const char                    *info_text_p,		  /* AT cmd usage string  */
    unsigned int                  *xid_p,	          /* AT cmd handle        */
    void                          *arg_p              /* AT cmd parser number */
)
{
    UNUSEDPARAM(command_name_p)
	UNUSEDPARAM(info_text_p)
    RETURNCODE_T       rc = INITIAL_RETURN_CODE;
     _AtciResultCode status = ATCI_RESULT_CODE_ERROR;
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
	UINT32        atHandle  = MAKE_AT_HANDLE(sAtpIndex);
	RETURNCODE_T  ret       = utlSUCCESS;
    UINT32  err = 0;
    int cdvalue;
    atcmd_general_log("chaim sAtpIndex=%d, atc cmd ,op=%d",sAtpIndex,op);

    if(op==TEL_EXT_EXEC_CMD)
    {
         if ((getExtValue(parameter_values_p,
                             0,
                             &cdvalue,
                             QUEC_AT_C_CMD_VAL_MIN,
                             QUEC_AT_C_CMD_VAL_MAX,
                             QUEC_AT_C_CMD_VAL_DEFAULT) == TRUE))
            {
                switch(cdvalue)
                {
                    case QUEC_AT_C_CMD_VAL_MIN:
                    case QUEC_AT_C_CMD_VAL_MAX:
                        atcmd_general_log("cdvalue value=%d",cdvalue);
                        status=ATCI_RESULT_CODE_OK;
                    break;

                    default:
                         atcmd_general_log("cdvalue value=%d error",cdvalue);
                         status=ATCI_RESULT_CODE_ERROR;
                   break;
                }
             }
    }
   if(status!=ATCI_RESULT_CODE_OK)
   {
        ret=ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
        return HANDLE_RETURN_VALUE(ret);
   }
    quec_siolib_set_dcd_func_mode(cdvalue);

    quec_msg_io_conf_value_s dcd_func={sAtpIndex,cdvalue};

    err=quec_send_dcd_func_msg(&dcd_func);

    atcmd_general_log("chaim sAtpIndex=%d, atc cmd ,value=%d",sAtpIndex,cdvalue);

	*xid_p = atHandle;
    if(err)
    {
        /*return the result code and response to the terminal */
	    ret=ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
    }
    else
    {
	    ret=ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);

    }
    rc = HANDLE_RETURN_VALUE(ret);
	return rc;
}

