RETURNCODE_T  quectel_exec_qdbgcfg_iptrace_cmd
(
         const utlAtParameterOp_T        op,                 /* AT cmd type          */
         const char                     *command_name_p,     /* AT cmd name          */
         const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
         const size_t                    num_parameters,     /* AT cmd number        */
         const char                     *info_text_p,        /* AT cmd usage string  */
         unsigned int                   *xid_p,              /* AT cmd handle        */
         void                           *arg_p
)
{
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32 atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    
	 *xid_p = atHandle;
	RETURNCODE_T rc = INITIAL_RETURN_CODE;
	CiReturnCode ret = CIRC_FAIL;
	uint8 num_param = quec_get_at_param_num(parameter_values_p, num_parameters);

    char res_buf[100] = {0};
    UINT8 resp_len = 0;

    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len = 0;
	int trace_len = 0;
	int current_len;
	int position_param = 0;
	int position = 0;
	
    atcmd_general_log("command type=%d,param_num=%d", op, num_param);
	
	switch(op)
	{
		case TEL_EXT_SET_CMD:
		{
	        if (num_param == 1)
	        {	          
	            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QDBGCFG: \"iptrace\",0,%d\r\n+QDBGCFG: \"iptrace\",1,%d", 
					gIpTrace_IPV4CopyLen>>3, gIpTrace_IPV6CopyLen>>3);
	            //ret = quec_siolib_transmit_to_atp(sAtpIndex, res_buf, resp_len, NULL);
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
	            break;
	        }
	        else if ((num_param == 2) || (num_param == 3))
	        {
                position_param =parameter_values_p[1].value.decimal;
                atcmd_general_log("position_param=%d", position_param);
				if (position_param == 0)
				{
					position = 1;
					current_len = gIpTrace_IPV4CopyLen>>3;
				}
				else if (position_param == 1)
				{
					position = 3;
					current_len = gIpTrace_IPV6CopyLen>>3;
				}
				else
				{
	                 ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
					 break;
				}

				if (num_param == 2)
				{
//#ifdef QUECTEL_PROJECT_CUST //Chaim 20200526 1601 use medcr origin declare
						//ret = DEV_GetMEDCR(atHandle, 1,position);
					//#else
						ret = DEV_GetMEDCR(atHandle, position);
					//#endif
		            break;
				}
                else
                {
                    trace_len =parameter_values_p[2].value.decimal;
                    atcmd_general_log("trace_len=%d", trace_len);
                    if ((trace_len < 0) || (trace_len > 255))
					{
                 		ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
					}
					else if (current_len != trace_len)
					{
//#ifdef QUECTEL_PROJECT_CUST //Chaim 20200526 1601 use medcr origin declare
						//ret = DEV_SetMEDCR(atHandle,0, position, trace_len);
					//#else
						ret = DEV_SetMEDCR(atHandle, position, trace_len);						
				//	#endif
					}
					else
					{
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
					} 
                }

	        }
	        else
	        {
	             ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
	        }
	        break;
    	}
		case TEL_EXT_GET_CMD:
		case TEL_EXT_TEST_CMD:
        {
            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QDBGCFG: \"iptrace\",(0,1),(0-255)\r\n");
            ret = quec_siolib_transmit_to_atp(sAtpIndex, res_buf, resp_len, NULL);
            break;
        }
		default:
        {
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
            break;
        }
	}
	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return rc;

}


//jensen.fang 20180109: added dump config interface
extern int eeConfiguration_SilentResetFLAG(UINT32 resetflag);
RETURNCODE_T  quectel_exec_qdbgcfg_dumpcfg_cmd(const utlAtParameterOp_T 	 op,
												const char					 *command_name_p,
												const utlAtParameterValue_P2c parameter_values_p,
												const size_t				  num_parameters,
												const char					 *info_text_p,
												unsigned int				 *xid_p,
												void						 *arg_p)
{
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
	UINT32 atHandle = MAKE_AT_HANDLE( sAtpIndex );
	RETURNCODE_T ret = utlSUCCESS;

	int dump_opt;
	int dump_opt_value;
	uint8 num_param = quec_get_at_param_num(parameter_values_p, num_parameters);
	char rsp_str[64] = {0};


	*xid_p = atHandle;
	atcmd_general_log("command type=%d,param_num=%d", op, num_param);

	switch (op)
	{
		case TEL_EXT_SET_CMD:
		{
            if(1 == num_param)
            {
                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
                break;
            }
			else if (2 == num_param)
			{
				dump_opt = parameter_values_p[1].value.decimal;
                
                atcmd_general_log("dump_opt=%d", dump_opt);
				switch (dump_opt)
				{
					case 0://silent reset  
						if ((0 == eeConfiguration.dumpResetFlag))
						{
							sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",0,1");
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						}
						else if ((1 == eeConfiguration.dumpResetFlag))
						{
							sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",0,0");
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						}
						/*if ((0 == eeConfiguration.dumpResetFlag) && (WATCHDOG_INTERRUPT_MODE == eeConfiguration.watchdog_mode))
						{
							sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",0,1");
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						}
						else if ((1 == eeConfiguration.dumpResetFlag) && (WATCHDOG_INTERRUPT_MODE == eeConfiguration.watchdog_mode))
						{
							sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",0,0");
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						}*/
/*						if ((EE_RESET_COMM_SILENT == eeConfiguration.finalAction) && (WATCHDOG_INTERRUPT_MODE == eeConfiguration.watchdog_mode))
						{
							sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",0,1");
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						}
						else if ((EE_EXTERNAL == eeConfiguration.finalAction) && (WATCHDOG_INTERRUPT_MODE == eeConfiguration.watchdog_mode))
						{
							sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",0,0");
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						}*/
						else
						{
							atcmd_general_log("dump_flag=%d", eeConfiguration.dumpResetFlag);
							ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_UNEXPECTED_DATA_VALUE, NULL);
						}
						break;
					case 1://reset after dump
						sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",1,%d", is_reset_after_dump);
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						break;
					case 2://Ymodem enable/disable
						sprintf(rsp_str, "+QDBGCFG: \"dumpcfg\",2,%d", YmodemDumpCfg.config);
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, rsp_str);
						break;
					default:
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_UNEXPECTED_DATA_VALUE, NULL);
						break;
				}
				break;
			}
			else if (3 == num_param)
			{
				dump_opt = parameter_values_p[1].value.decimal;
				dump_opt_value = parameter_values_p[2].value.decimal;
                
                atcmd_general_log("dump_opt=%d,dump_opt_value=%d", dump_opt,dump_opt_value);
			}
			else
			{
				atcmd_general_log("op=%d, op_num error: %d", op, num_param);
				ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
				break;
			}

			atcmd_general_log("dump_opt %d_%d", dump_opt, dump_opt_value);

			switch (dump_opt)
			{
				case 0://silent reset
					dump_opt_value = !dump_opt_value;//0 is to disable silent reset

#if 0
					eeConfigureSilentReset((BOOL)((dump_opt_value>>4) & 0x0F), (BOOL)(dump_opt_value & 0x0F));
#else

/*					if ((newFinalAction == eeConfiguration.finalAction) && (newwatchdogmode == eeConfiguration.watchdog_mode))
					{
						atcmd_general_log("same eeConfiguration, ignore");
						break;
					}
*/
					/*dump_opt_value = ((dump_opt_value)==(0) ? (1) : (0)) ;
					if ((dump_opt_value == eeConfiguration.dumpResetFlag) && (newwatchdogmode == eeConfiguration.watchdog_mode))
					{
						atcmd_general_log("same eeConfiguration, ignore");
						break;
					}*/
					if ((dump_opt_value == eeConfiguration.dumpResetFlag))
					{
						atcmd_general_log("same eeConfiguration, ignore");
						break;
					}

//					eeConfiguration.finalAction = newFinalAction;
					//eeConfiguration.watchdog_mode = newwatchdogmode;
					eeConfiguration.dumpResetFlag = dump_opt_value;
					ret = eeConfiguration_SilentResetFLAG(dump_opt_value);
					atcmd_general_log("write nvm ret =%d value=%d",ret,dump_opt_value);
//					eeSaveConfiguration();
#endif
					break;
				case 1://reset after dump
					if (dump_opt_value != 0)//0 is to disable reset after dump
					{
						dump_opt_value = 1;//default enable reset after dump
					}
					eeConfiguration.finalAction=(dump_opt_value)==(0) ? (EE_EXTERNAL):(EE_RESET);
					is_reset_after_dump = dump_opt_value;
					break;
				case 2://Ymodem enable/disable
					if (dump_opt_value != YMODEM_DISABLE)
					{
						dump_opt_value = YMODEM_ENABLE;
					}
					
					YmodemDumpCfg.config = dump_opt_value;
					break;
				default:
					ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_UNEXPECTED_DATA_VALUE, NULL);
					return ret;
			}

			ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
			break;
		}
	/*	case TEL_EXT_GET_CMD:
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
			break;*/
		case TEL_EXT_TEST_CMD:
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, "+QDBGCFG: \"dumpcfg\",(0-2),(0,1)");
			break;
		default:
            atcmd_general_log("command type error: %d", op);
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_ILLEGAL_OPERATION, NULL);
			break;
	}

	return ret;
}

                                                
