//Chaim 2019.03.09
RETURNCODE_T  quectel_exec_qdbgcfg_memory_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus quec_status = QUEC_SUCCESS;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num = 0;

    uint8 oper = 0;
	uint8 operitem = 0;

    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:
        {
            if(param_num == 3)
            {
                oper = parameter_values_p[1].value.decimal; 
                operitem = parameter_values_p[2].value.decimal; 
            }
            else
            {   
                atcmd_general_log("param_num=%d is invalid", param_num);
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
                break;
            }

			if (0 == oper)
			{
                quec_status = quec_memory_status_query(index, operitem);
                if(quec_status != QUEC_SUCCESS)
                {
                    atcmd_general_log("memorystatus %d query fail", operitem);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                }
                else
                {
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL); 
                }
			}
			else
			{
           		ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			}
                
        	break;
        }
        default:
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
            break;
        }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}


//Chaim 2019.03.09
RETURNCODE_T  quectel_exec_qdbgcfg_sleep_debug_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
     char res_buf[50]={0};
    UINT8 resp_len=0;

    quec_sleep_log_type_e sleep_log_debug = QUEC_SLEEP_INFO_TO_USB;

    
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QDBGCFG="mempool/status",..  */
            {
                if(param_num == 1)
                {
                    resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"sleep/debug\",%d\r\n",quec_get_sleepinfo_uart_log());
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    break;
                    
                }
                else if(param_num == 2)
                {
                    sleep_log_debug = parameter_values_p[1].value.decimal; 
                }
                else
                {   
                    atcmd_general_log("param_num=%d is invalid", param_num);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
                    break;
                }

                quec_status = quec_set_sleepinfo_uart_log(sleep_log_debug);
                if(quec_status != QUEC_SUCCESS)
                {
                    
                    atcmd_general_log("set sleep log debug fail");
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                }
                else
                {
                    atcmd_general_log("set sleep log debug OK");
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL); 
                }
                    
             break;
            }
        
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

//Egan 2020.07.16

extern void quec_set_urc_lfs_flag(int data);

extern void quec_get_urc_lfs_flag(int *data);

RETURNCODE_T  quectel_exec_qdbgcfg_flash_check_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
     char res_buf[50]={0};
    UINT8 resp_len=0;
	int log_debug=0;

    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QDBGCFG="mempool/status",..  */
            {
                if(param_num == 1)
                {
                	quec_get_urc_lfs_flag(&log_debug);
                    resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"flash/check\",%d\r\n",log_debug);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    break;
                    
                }
                else if(param_num == 2)
                {
                    log_debug = parameter_values_p[1].value.decimal; 
					atcmd_general_log("num1=%d,num2=%d",log_debug,param_num);
					quec_set_urc_lfs_flag(log_debug);
					ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    break;
                }
                else
                {   
                    atcmd_general_log("param_num=%d is invalid", param_num);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
                    break;
                }                    
             break;
            }
        
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

