//Larson 2019.04.01
RETURNCODE_T  quectel_exec_qdbgcfg_tcpip_rate_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    
    char res_buf[128]={0};
    UINT8 resp_len=0;
    int transmission_rate = 0;
    UINT32 rate=0;
    unsigned char flag = 0;
    int mode = 0;
    int file_fd = 0;
    
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QDBGCFG="mempool/status",..  */
            {
                if (param_num == 1)
                {
                    resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"tcpip/rate\",(1-2),(0-1000000)\r\n");
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    break;
                }
                else if(param_num == 2)
                {
                    mode = parameter_values_p[1].value.decimal;
                    if (mode == 1)
                    {
                        //resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"tcpip/rate\",lwip_rate=%d\r\n",get_DLMaxRate());
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    }
                    else if (mode == 2)
                    {
//                        get_ppp_ul_rate_ctrl(&flag, &rate);
                        resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"tcpip/rate\",ppp_rate=%d\r\n",rate);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    }
                    else
                    {
                        #if 0
                        resp_len=snprintf(res_buf,sizeof(res_buf)-1,"eg:at+qdbgcfg=\"tcpip/rate\",1\r\n");
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, res_buf);
                        #else
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                        #endif
                        break; 
                    }
                    break;
                }
                else if(param_num == 3)
                {
                    mode = parameter_values_p[1].value.decimal;
                    transmission_rate = parameter_values_p[2].value.decimal; 
                    atcmd_general_log("mode=%d,transmission_rate=%d",mode,transmission_rate);
                    if (mode == 1)
                    {
                        if (transmission_rate <= 0)
                        {
                            //set_dl_rate_control_flag(0);
                            //set_DLMaxRate(0);
                        }
                        else
                        {
                            if(transmission_rate>1000000)
                                transmission_rate = 1000000;
                            atcmd_general_log("maxlwipRate = %u Bps", transmission_rate);
                            //set_dl_rate_control_flag(1);
                            //set_DLMaxRate(transmission_rate);
                        }
                        file_fd = FDI_fopen("lwip_rate.cfg", "wb");
                        sprintf(res_buf,"lwip_rate=%d",transmission_rate);
                        FDI_fwrite((void *)res_buf, 1, strlen(res_buf), file_fd);
                        FDI_fclose(file_fd);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);  
                    }
                    else if(mode == 2)
                    {
                        if (transmission_rate <= 0)
                        {
//                            set_ppp_ul_rate_ctrl(0);
                        }
                        else
                        {
                            atcmd_general_log("maxPPPRate = %u Bps", transmission_rate);
                            if (transmission_rate>750000)
                                transmission_rate = 750000;
//                            set_ppp_ul_rate_ctrl(transmission_rate);
                        }
                        file_fd = FDI_fopen("ppp_rate.cfg", "wb");
                        sprintf(res_buf,"ppp_rate=%d",transmission_rate);
                        FDI_fwrite((void *)res_buf, 1, strlen(res_buf), file_fd);
                        FDI_fclose(file_fd);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL); 
                    }
                    else
                    {
                        resp_len=snprintf(res_buf,sizeof(res_buf)-1,"eg:at+qdbgcfg=\"tcpip/rate\",1,750000\r\n");
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, res_buf);
                        break; 
                    }
                    break;
                }
                else
                {   
                    atcmd_general_log("param_num=%d is invalid", param_num);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
                    break;
                }
             break;
            }
        
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

RETURNCODE_T  quectel_exec_qdbgcfg_port_data_show_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    
    char res_buf[50]={0};
    UINT8 resp_len=0;
    TelAtParserID set_atp = NUM_OF_TEL_ATP;
    uint8 hisr_data_flag =0;
	uint8 data_send_print_flag=0;
   // bool get_hisr_data_flag=0;
   // bool get_data_send_print_flag=0;

	quec_debug_port_data_show_s *pget_port_data_show = NULL;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QDBGCFG="port/datashow",..  */
            {
                if(param_num == 2)
                {
                     set_atp = parameter_values_p[1].value.decimal; 
                     
                     quec_status = quec_sio_get_port_data_show_flag(set_atp,&pget_port_data_show);
                     
                     if((quec_status != QUEC_SUCCESS)||(NULL == pget_port_data_show))
                     {
                        atcmd_general_log("set_atp=%d get data show flag fail,quec_status=%d,pget_port_data_show=%p", 
                            set_atp,quec_status,pget_port_data_show);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);      
                     }
                     else
                     {
                        resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"port/datashow\",%d,%d,%d\r\n",set_atp, (*pget_port_data_show).tx_data_flag,(*pget_port_data_show).rx_data_flag);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                     }
                     
                     break;
                }
                else if(param_num == 4)
                {
                    set_atp = parameter_values_p[1].value.decimal; 
                    hisr_data_flag = parameter_values_p[2].value.decimal; 
					data_send_print_flag = parameter_values_p[3].value.decimal; 
                }
                else
                {   
                    atcmd_general_log("param_num=%d is invalid", param_num);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
                    break;
                }

                quec_status = quec_sio_set_port_data_show_flag(set_atp,hisr_data_flag,data_send_print_flag);
                if(quec_status != QUEC_SUCCESS)
                {
                    
                    atcmd_general_log("set_atp=%d data show flag fail",set_atp);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                }
                else
                {
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL); 
                }
                    
             break;
            }
        
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}


