QuecOSStatus quec_read_rtilog_mode(void)
{
    QuecOSStatus ret = kGeneralErr;
	UINT32 current_mode = rti_mode_none;
    ret = quectel_nv_fat_read(QUEC_RTILOG_MODE_NVM, &current_mode, sizeof(current_mode));
    if(ret != QUEC_FAT_SUCCESS)
    {
        atcmd_general_log("rtilog_mode nvm read failed"); 
        return ret;
    }

	quec_rtilog_mode = current_mode;
//	rti_set_mode(current_mode);
    return QUEC_SUCCESS;
}

QuecOSStatus quec_write_rtilog_mode(UINT32 log_mode)
{
    QuecOSStatus ret = kGeneralErr;
    if (log_mode <= rti_mode_max)
    {
    	if (log_mode == quec_rtilog_mode)
		{
	        atcmd_general_log("rtilog_mode=%d, no change",log_mode);
	        return QUEC_SUCCESS;
		}
    }
	else
	{
        atcmd_general_log("rtilog_mode=%d is invalid", log_mode);
        return kValueErr;
	}
	
    ret = quectel_nv_fat_write(QUEC_RTILOG_MODE_NVM, &log_mode, sizeof(log_mode));
    if(ret != QUEC_FAT_SUCCESS)
    {
        atcmd_general_log("rtilog_mode=%d nvm write failed", log_mode); 
        return ret;
    }
	
	quec_rtilog_mode = log_mode;
//	rti_set_mode(log_mode);
    return QUEC_SUCCESS ;
}

RETURNCODE_T quectel_exec_qdbgcfg_rtilog_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
	RETURNCODE_T	 rc 	  = INITIAL_RETURN_CODE;
	CiReturnCode	 ret	  = CIRC_FAIL;
	QuecOSStatus status=QUEC_SUCCESS;
	QuecOSStatus quec_status=QUEC_SUCCESS;

	UINT32	atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
	*xid_p = atHandle;
	UINT32 index  = *(TelAtParserID *)arg_p;
	UINT8 param_num=0;
	
	char res_buf[50]={0};
	UINT8 resp_len=0;
	UINT32 rtilog_mode = rti_mode_none;
	
	/*
	 **  Check the format of the request.
	 */
	param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

	atcmd_general_log("command type=%d,param_num=%d",op,param_num);
	switch (op)
	{
		case TEL_EXT_SET_CMD:
		{
			if(param_num == 1)
			{
				resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"rtilog\",%d\r\n", quec_rtilog_mode);
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
				break;
			}
			else if(param_num == 2)
			{
				rtilog_mode = parameter_values_p[1].value.decimal; 
				atcmd_general_log("rtilog_mode = %d",rtilog_mode);
				quec_status = quec_write_rtilog_mode(rtilog_mode);
				if(quec_status != QUEC_SUCCESS)
				{
					atcmd_general_log("set rtilog_mode fail");
					ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
				}
				else
				{
					ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL); 
				}
			}
			else
			{	
				atcmd_general_log("param_num=%d is invalid", param_num);
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
				break;
			}

			break;
		}
		
		default:
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			break;
		}

	}

	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return(rc);
}


