RETURNCODE_T quectel_exec_qdbgcfg_simcfg_cmd
(
	 const utlAtParameterOp_T		 op,					/* AT cmd type					*/
	 const char 					*command_name_p,		/* AT cmd name					*/
	 const utlAtParameterValue_P2c	 parameter_values_p,	/* AT cmd value 				*/
	 const size_t					 num_parameters,		/* AT cmd number				*/
	 const char 					*info_text_p,			/* AT cmd usage string			*/
	 unsigned int					*xid_p, 				/* AT cmd handle				*/
	 void							*arg_p				/* AT cmd parser number 		*/
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    
    char res_buf[128] = {0};
    UINT8 resp_len = 0;
    uint8 sim_option = 0;
    uint8 sim_op = 0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    switch (op)
    {
        case TEL_EXT_SET_CMD:
        {
            if(param_num > 1)
            {
                sim_op = parameter_values_p[1].value.decimal; 
                if (sim_op > 1)//currently, only support op 0 and 1
                {
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                    break;
                }
                
                quec_sim_write_opt_s sim_write_opt_cfg = {0};
                memcpy(&sim_write_opt_cfg, &quec_sim_write_optimize_cfg, sizeof(quec_sim_write_opt_s));

                if (param_num == 2)
                {
                    if (0 == sim_op)
                    {
                        resp_len = snprintf(res_buf, sizeof(res_buf)-1,"+QDBGCFG: \"simcfg\",0,%d,%d\r\n", quec_sim_write_optimize_cfg.opt_enable, quec_sim_write_optimize_cfg.opt_bit_cfg);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                        break;
                    }
                    else if (1 == sim_op)
                    {
                        resp_len = snprintf(res_buf, sizeof(res_buf)-1,"+QDBGCFG: \"simcfg\",1,%d\r\n", quec_sim_write_optimize_cfg.opt_epsnsc_cfg);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                        break;
                    }
                    else
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                        break;
                    }
                }
                else if (param_num == 3)
                {
                    sim_option = parameter_values_p[2].value.decimal; 
                    if (0 == sim_op)
                    {
                        if (sim_option != 0)
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                            break;
                        }

                        if (sim_option == quec_sim_write_optimize_cfg.opt_enable)
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                            break;
                        }

                        sim_write_opt_cfg.opt_enable = sim_option;
                        sim_write_opt_cfg.opt_bit_cfg = 0;
                        if (quectel_nv_fat_write(QUEC_SIM_WRITE_OPTIMIZE_CFG_NV, &sim_write_opt_cfg, sizeof(quec_sim_write_opt_s)) == QUEC_FAT_SUCCESS)
                        {
                            quec_sim_write_optimize_cfg.opt_enable = sim_option;
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                            break;
                        }
                        else
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                            break;
                        }
                    }
                    else if (1 == sim_op)
                    {
                        if (sim_option > 1)
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                            break;
                        }
                        
                        if (sim_option == quec_sim_write_optimize_cfg.opt_epsnsc_cfg)
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                            break;
                        }

                        sim_write_opt_cfg.opt_epsnsc_cfg = sim_option;
                        if (quectel_nv_fat_write(QUEC_SIM_WRITE_OPTIMIZE_CFG_NV, &sim_write_opt_cfg, sizeof(quec_sim_write_opt_s)) == QUEC_FAT_SUCCESS)
                        {
                            quec_sim_write_optimize_cfg.opt_epsnsc_cfg = sim_option;
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                            break;
                        }
                        else
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                            break;
                        }
                    }
                    else
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                        break;
                    }
                }
                else if (param_num == 4)
                {
                    sim_option = parameter_values_p[2].value.decimal;
                    if (0 == sim_op)
                    {
                        if (sim_option != 1)
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                            break;
                        }
                        
                        sim_option = parameter_values_p[3].value.decimal;
                        //if (sim_option == 0)
                        //{
                        //  ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                        //    break;
                        //}
                        sim_write_opt_cfg.opt_enable = 1;
                        sim_write_opt_cfg.opt_bit_cfg = sim_option;
                        if (memcmp(&sim_write_opt_cfg, &quec_sim_write_optimize_cfg, sizeof(quec_sim_write_opt_s)) == 0)
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                            break;
                        }

                        if (quectel_nv_fat_write(QUEC_SIM_WRITE_OPTIMIZE_CFG_NV, &sim_write_opt_cfg, sizeof(quec_sim_write_opt_s)) == QUEC_FAT_SUCCESS)
                        {
                            memcpy(&quec_sim_write_optimize_cfg, &sim_write_opt_cfg, sizeof(quec_sim_write_opt_s));
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                            break;
                        }
                        else
                        {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                            break;
                        }
                    }
                    else
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                        break;
                    }
                }
                else
                {
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL); 
                    break;
                }
                break;
            }
            else
            {   
                atcmd_general_log("param_num=%d is invalid", param_num);
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
                break;
            }

            break;
        }
        default:
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
            break;
        }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

#endif

