 /*===========================================================================

 FUNCTION QUEC_EXEC_QCFG_BAND_CMD

 DESCRIPTION
   This function takes the result from the command line parser
   and executes it.
   This command set the phone to set network support band.

 DEPENDENCIES
   None

 RETURN VALUE
   returns an enum that describes the result of the command execution.
   possible values:
     utlSUCCESS : if it is a success.
     utlFAILED :if there was any problem in executing the command.

 SIDE EFFECTS
   None
 ===========================================================================*/

RETURNCODE_T  quectel_exec_qcfg_band_cmd
(
     const utlAtParameterOp_T        op,                 /* AT cmd type          */
     const char                     *command_name_p,     /* AT cmd name          */
     const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
     const size_t                    num_parameters,     /* AT cmd number        */
     const char                     *info_text_p,        /* AT cmd usage string  */
     unsigned int                   *xid_p,              /* AT cmd handle        */
     void                           *arg_p
)
{

    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;

    UINT32 atHandle  =*xid_p ;

    UINT64 gsm_band=0x0;
	UINT64 wcdma_band=0x0;
	UINT64 lte_band=0x0;
	UINT64 lte_band_ext = 0x0;
    UINT8 param_num=0;
    UINT8 i=0;
    UINT32 index  = *(TelAtParserID *)arg_p;
    char res_buf[100]={0};
	UINT64 qcfg_band_param[3]={0};
    char  cfg_cmd_param_str[36] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    /*
    **  Check the format of the request.
    */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d %d", op, param_num, num_parameters);
    switch (op)
    {
        case TEL_EXT_SET_CMD:
            {

                if(param_num==1)
                {
                    BIT_SET(qcfg_cmd_type_bitmask,QCFG_BAND_GET) ;
                    ret = DEV_GetBandModeReq(atHandle);
                }
                else if ((param_num ==3)|| (param_num ==2))
                {
                    qcfg_band_param[0]=0;
                    memset(cfg_cmd_param_str,0,sizeof(cfg_cmd_param_str));
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 16, &cfg_cmd_param_str_len, NULL) == FALSE))
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         rc = HANDLE_RETURN_VALUE(ret);
                         return(rc);
                    }
                    else if(hexstr2int64(cfg_cmd_param_str,16,&qcfg_band_param[0])==FALSE)
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         rc = HANDLE_RETURN_VALUE(ret);
                         return(rc);
                    }
                    
                    if (param_num ==3)
                    {
                        qcfg_band_param[1] = 0;
                        qcfg_band_param[2] = 0;
                        memset(cfg_cmd_param_str, 0 ,sizeof(cfg_cmd_param_str));
                        if ((getExtString(parameter_values_p, 2, cfg_cmd_param_str, 32, &cfg_cmd_param_str_len, NULL) == FALSE))
                        {
                             ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                             rc = HANDLE_RETURN_VALUE(ret);
                             return(rc);
                        }
                        else
                        {
                             if (cfg_cmd_param_str_len > 16)
                             {
                                 if (hexstr2int64(cfg_cmd_param_str+cfg_cmd_param_str_len-16, 16, &qcfg_band_param[1])==FALSE)
                                 {
                                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                                     rc = HANDLE_RETURN_VALUE(ret);
                                     return(rc);
                                 }
                                 if (hexstr2int64(cfg_cmd_param_str, cfg_cmd_param_str_len-16, &qcfg_band_param[2])==FALSE)
                                 {
                                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                                     rc = HANDLE_RETURN_VALUE(ret);
                                     return(rc);
                                 }
                             }
                             else
                             {
                                 if (hexstr2int64(cfg_cmd_param_str, 16, &qcfg_band_param[1])==FALSE)
                                 {
                                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                                     rc = HANDLE_RETURN_VALUE(ret);
                                     return(rc);
                                 }
                                 qcfg_band_param[2] = 0;
                             }
                        }
                    }
					atcmd_general_log("qcfg_band_param=0x%llx 0x%llx 0x%llx", qcfg_band_param[0], qcfg_band_param[1], qcfg_band_param[2]);

					memcpy(qcfg_band, qcfg_band_param, sizeof(qcfg_band));
					gsm_band = quec_get_gsm_band();
					wcdma_band = quec_get_wcdma_band();
					lte_band = quec_get_lte_band();
                    lte_band_ext = quec_get_lte_band_ext();

                    // connor.wu 2018/12/10 if customer set 0 we set to  the factory value
 				    if((qcfg_band[0] & 0x0000000f)==0)  //set gsm band to the factory value
 				    {
 				        qcfg_band[0] |= gsm_band;
 				    }

 					if((qcfg_band[0] & 0x0000fff0)==0)  //set wcdma band to the factory value
 				    {
 				        qcfg_band[0] |= wcdma_band;
 				    }

 				    if(qcfg_band[1]==0) //set LTE band to the factory value
 				    {
     				    if(qcfg_band[2]==0)
     				    {
 				            qcfg_band[1]= lte_band;
     				        qcfg_band[2]= lte_band_ext;
     				    }
 				    }

					// connor.wu 2018/12/10 prevent to set a value that we did not support for a specific project
					qcfg_band[0] &= (gsm_band | wcdma_band);
					qcfg_band[1] &= lte_band;
					qcfg_band[2] &= lte_band_ext;

					if((qcfg_band[0]==0 && (gsm_band != 0 || wcdma_band != 0))
						|| (qcfg_band[1] ==0 && qcfg_band[2] ==0 && (lte_band != 0 || lte_band_ext!=0) ))
					{
					    ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						break;
					}
					atcmd_general_log(" qcfg_band[0]=0x%llx,qcfg_band[1]=0x%llx,qcfg_band[2]=0x%llx",qcfg_band[0],qcfg_band[1],qcfg_band[2]);
                    BIT_SET(qcfg_cmd_type_bitmask,QCFG_BAND_SET) ;
                    ret = DEV_GetBandModeReq(atHandle);
                }
                else
                {
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {
#if !QUEC_LTE_SUPPORT
                strcpy(res_buf, "+QCFG: \"band\",(0-200)\r\n");
#else
                strcpy(res_buf, "+QCFG: \"band\",(0-200),(0-7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF)\r\n");
#endif
                ret=quec_siolib_transmit_to_atp(index,res_buf,strlen(res_buf), NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

   /* handle the return value */
   rc = HANDLE_RETURN_VALUE(ret);
   return(rc);
}


//Chaim@qian add 2018.11.14
RETURNCODE_T  quectel_exec_qcfg_usbauto_cmd
(
 const utlAtParameterOp_T		 op,					/* AT cmd type					*/
 const char 					*command_name_p,		/* AT cmd name					*/
 const utlAtParameterValue_P2c	 parameter_values_p,	/* AT cmd value 				*/
 const size_t					 num_parameters,		/* AT cmd number				*/
 const char 					*info_text_p,			/* AT cmd usage string			*/
 unsigned int					*xid_p, 				/* AT cmd handle				*/
 void							*arg_p				/* AT cmd parser number 		*/
)
{
RETURNCODE_T	 rc 	  = INITIAL_RETURN_CODE;
CiReturnCode	 ret	  = CIRC_FAIL;
QuecOSStatus status=QUEC_SUCCESS;
int 			 type;
UINT32	index;
//UINT32		   atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);

UINT32 atHandle =	   *xid_p;
index  = *(TelAtParserID *)arg_p;
UINT8 param_num=0;
char res_buf[100]={0};
// UINT8 len=0;
char  cfg_cmd_param_str[20] = {0};
UINT8 cfg_cmd_param_str_len=0;
quec_usb_net_type_e get_net_type=0;
UINT32	os_detect=0;
UINT8 resp_len=0;
/*
 **  Check the format of the request.
 */
param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

atcmd_general_log("command type=%d,param_num=%d",op,param_num);

#ifdef QUEC_USB_AUTO_SUPPORT
switch (op)
{
	case TEL_EXT_SET_CMD:	 /* AT+QCFG="usbauto",..  */
		{

			if(param_num==1)
			{
				 resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbauto\",%d\r\n",usbDrvCfg.os_detect);
				 ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);

			}
			else if(param_num==2)
			{
				os_detect=0;
				if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE))
				{
					 if(str2int32(cfg_cmd_param_str,2,&os_detect))  //check if the num is large than 10
					 {
						 atcmd_general_log(" os_detect=%d",os_detect);
						
						 status=quec_save_usb_auto_fat(os_detect);
						 if(status!=QUEC_SUCCESS)
						 {
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						 }
						 else
						 {
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, 0);
						 }
						 atcmd_general_log(" quec_save_usb_net_type_fat status=%d",status);
						

					 }
					 else
					 {
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
					 }
				}
				else
				{
					 ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
				}
			}
			else
			{
				 ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
			}
			break;
		}

	case TEL_EXT_TEST_CMD:	  /* AT+QCFG=? */
		{

			 resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbauto\",(%d,%d)\r\n",\
				USB_OS_DETECT_DISABLE,USB_OS_DETECT_ENABLE);
			ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
			break;
		}
	default:
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			break;
		}

}
#endif
/* handle the return value */
rc = HANDLE_RETURN_VALUE(ret);
return(rc);
}

