#ifdef QUEC_ASR_ATCMD_USB_NET_MAC_SUPPORT
BOOL quec_usbnet_mac_is_changed(void)
{
	QuecOSStatus ret = QUEC_SUCCESS;
	/* reload params */
	#if QUEC_PRODUCTION_CFG_SUPPORT
	ST_quecCfgUsbNetParams ST_UsbNetParams = {0};
	ret= Quec_SysItemPara_Item_get(QUEC_USBNET_PARAMS_CFG, &ST_UsbNetParams, sizeof(ST_quecCfgUsbNetParams));
	if(ret == QUEC_SUCCESS)
	{   
		// UsbNetMacAddress[0] is changed by at, default is 0xAC maybe is defferent in other code baseline;
		if(ST_UsbNetParams.macAddr.addr[0] != 0xAC){
			return TRUE;
		}
	}
	#else
	mvUsbMacAddr getUsbNetMac;
	memset((void *)&getUsbNetMac,0,sizeof(mvUsbMacAddr));
    ret = quectel_nv_fat_read(QUEC_USBNET_MAC_FAT, &getUsbNetMac,sizeof(getUsbNetMac));
    if(ret == QUEC_SUCCESS)
    {
       if(getUsbNetMac.addr[0] != 0xAC)
       {
          return TRUE;
       }
    }
	#endif
	return FALSE;
}

QuecOSStatus quec_set_usb_net_mac(mvUsbMacAddr *pmac)
{
    QuecOSStatus ret = QUEC_SUCCESS;
    mvUsbMacAddr getUsbNetMac, setUsbNetMac;
    UINT8 i = 0;
    UINT8 flag = 0;

    memset(&getUsbNetMac, 0, sizeof(getUsbNetMac));    
    memset(&setUsbNetMac, 0, sizeof(setUsbNetMac));
    if(pmac == NULL)
    {
        atcmd_general_log("pmac is a null pointer");
        return kGeneralErr;
    }
#if QUEC_PRODUCTION_CFG_SUPPORT
   /* reload params */
	ST_quecCfgUsbNetParams ST_UsbNetParams = {0};
	ret= Quec_SysItemPara_Item_get(QUEC_USBNET_PARAMS_CFG, &ST_UsbNetParams, sizeof(ST_quecCfgUsbNetParams));
	if(ret == QUEC_SUCCESS)
	{
		memcpy((void* )&getUsbNetMac,&ST_UsbNetParams.macAddr , sizeof(mvUsbMacAddr));
	}
#else	
    ret = quectel_nv_fat_read(QUEC_USBNET_MAC_FAT, &getUsbNetMac,sizeof(getUsbNetMac));
#endif
	if(QUEC_SUCCESS == ret)
    {
        for(i = 0; i < USBNET_MAC_LEN; i++)
        {
            if(pmac->addr[i] != getUsbNetMac.addr[i])
            {
                flag = 1;
                break;
            }
        }   
        if(0 == flag)
        {
            atcmd_general_log("quec_set_usb_net_mac checked flag, not need set");
            return QUEC_SUCCESS;    
        }
    }    
    else
    {
        atcmd_general_log("quec_set_usb_net_mac read mac failed");
    }
    for(i = 0; i < USBNET_MAC_LEN; i++)
    {
        setUsbNetMac.addr[i] = pmac->addr[i];
    }    
    CPUartLogPrintf("quec_set_usb_net_mac %02x:%02x:%02x:%02x:%02x:%02x", setUsbNetMac.addr[0], setUsbNetMac.addr[1], setUsbNetMac.addr[2],\
                             setUsbNetMac.addr[3], setUsbNetMac.addr[4], setUsbNetMac.addr[5]);  
#if QUEC_PRODUCTION_CFG_SUPPORT	
	memcpy((void *)&ST_UsbNetParams.macAddr,&setUsbNetMac, sizeof(setUsbNetMac));
	ret= Quec_SysItemPara_Item_set(QUEC_USBNET_PARAMS_CFG, &ST_UsbNetParams, sizeof(ST_quecCfgUsbNetParams));
#else	
    ret = quectel_nv_fat_write(QUEC_USBNET_MAC_FAT, &setUsbNetMac,sizeof(setUsbNetMac));
#endif
    if(QUEC_FAT_SUCCESS != ret)
    {
        atcmd_general_log("quec_set_usb_net_mac write fail");
        ret = kGeneralErr;
    }        

    return ret;
}


QuecOSStatus quec_get_usb_net_mac(mvUsbMacAddr *pmac)
{

    QuecOSStatus ret = QUEC_SUCCESS;
    mvUsbMacAddr usbNetMac;
    UINT8 i = 0;

    memset(&usbNetMac, 0, sizeof(usbNetMac));
    if(pmac == NULL)
    {
        atcmd_general_log("pmac is a null pointer");
        return kGeneralErr;
    }
#if QUEC_PRODUCTION_CFG_SUPPORT	
	ST_quecCfgUsbNetParams ST_UsbNetParams = {0};
	ret= Quec_SysItemPara_Item_get(QUEC_USBNET_PARAMS_CFG, &ST_UsbNetParams, sizeof(ST_quecCfgUsbNetParams));
	if(ret == QUEC_SUCCESS)
	{
		memcpy((void* )&usbNetMac,&ST_UsbNetParams.macAddr , sizeof(mvUsbMacAddr));
	}
#else
    ret = quectel_nv_fat_read(QUEC_USBNET_MAC_FAT, &usbNetMac,sizeof(usbNetMac));
#endif

	if(QUEC_SUCCESS == ret)
    {
        for(i = 0; i < USBNET_MAC_LEN; i++)
        {
            pmac->addr[i] = usbNetMac.addr[i];
        }
    }
    else
    {
        for(i = 0; i < USBNET_MAC_LEN; i++)
        {
            pmac->addr[i] = UsbNetMacAddress[i];
        }    
        atcmd_general_log("quec_get_usb_net_mac read fail,use default mac");
    }
    
    return ret;
}


QuecOSStatus quec_str2mac(const CHAR* str, mvUsbMacAddr *mac)
{
    CHAR  hexStr[3] = {0};
    UINT8 token = 0;
    UINT32 i;
    
    if ((NULL == mac) || (NULL == str))
    {
        return kGeneralErr;
    }
    if ((USBNET_MAC_LEN *3) -1 == strlen(str))
    {
        token = 3;
    }
    else
    {
        return kGeneralErr;
    }

    for (i = 0; i < USBNET_MAC_LEN ; i++)
    {
        hexStr[0]    = str[i * token];
        hexStr[1]    = str[i * token + 1];
        hexStr[2]    = '\0';
        mac->addr[i] = (UCHAR)strtol(hexStr, NULL, 16);
    }

    return QUEC_SUCCESS;
}

#endif

RETURNCODE_T  quectel_exec_qcfg_usbnetmac_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
#ifdef QUEC_ASR_ATCMD_USB_NET_MAC_SUPPORT
    int              type;
    UINT32  index;
    //UINT32           atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);

    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    char res_buf[100]={0};
    char  cfg_cmd_param_str[20] = {0};
    UINT8 resp_len=0;
    uint8 i = 0;
    mvUsbMacAddr usbNetMac;
    CHAR usbNetMacAddress[20] = {0};
    /*
     **  Check the format of the request.
     */
    memset(&usbNetMac, 0, sizeof(usbNetMac));
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QCFG="usbnetmac",..  */
            {
                if(param_num == 1)
                {
                    ret =quec_get_usb_net_mac(&usbNetMac);
                    if((CIRC_FAIL == ret) && (QUEC_FAT_FILE_NOT_EXIST != ret))
                    {
                        atcmd_general_log("get usb net mac failed");
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                    else
                    {
                         //char resp[]="AT+QCFG=\"usbnetmac\",";
                        sprintf(usbNetMacAddress, "%02x:%02x:%02x:%02x:%02x:%02x", usbNetMac.addr[0], usbNetMac.addr[1], usbNetMac.addr[2],\
                             usbNetMac.addr[3], usbNetMac.addr[4], usbNetMac.addr[5]);
                        for(i = 0; i < ((USBNET_MAC_LEN *3) -1); i++)
                        {
                            if((usbNetMacAddress[i] >= 'a') && (usbNetMacAddress[i] <= 'z'))
                            {
                                usbNetMacAddress[i] = usbNetMacAddress[i] - 32;
                            }                             
                        }
                        resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbnetmac\",%s\r\n",usbNetMacAddress);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    }

                }
                else if(param_num == 2)
                {
                    ret = quec_str2mac(parameter_values_p[1].value.string_p,&usbNetMac);
                    if (QUEC_SUCCESS == ret)
                    {
                        if (((usbNetMac.addr[5] == 0xFF) && (usbNetMac.addr[4] == 0xFF) && (usbNetMac.addr[3] == 0xFF)) \
                            || (((usbNetMac.addr[0]) % 2) != 0))
                        {
                            atcmd_general_log("quectel_exec_qcfg_usbnetmac_cmd  invalid mac address");
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                            rc = HANDLE_RETURN_VALUE(ret);
                            return(rc);

                        }
                        ret = quec_set_usb_net_mac(&usbNetMac);
                        if(ret != QUEC_SUCCESS)
                        {
                           ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                        }
                        else
                        {
                           ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
                        }
                        atcmd_general_log(" quec_set_usb_net_mac ret = %d",ret);                        
                    }
                    else
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {

                resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbnetmac\",<macaddress>\r\n");          
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len, NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }
#endif
    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}
