/*===========================================================================

FUNCTION QUECTEL QCFG CMD PROCESS OF URC_DELAY

DESCRIPTION
  This function takes the result from the command line parser
  and executes it. It executes C command.


DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.

SIDE EFFECTS
  None
===========================================================================*/

RETURNCODE_T  quectel_exec_qcfg_urc_delay_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_SUCCESS;
    QuecOSStatus     err      = kNoErr;
    int              type;
    UINT8            param_num = 0;
    CHAR             spec_cmd_str[64] = {0};
    UINT16           spec_cmd_len = 0;
	CHAR			 spec_cmd_parm1_str[4] = {0};
	UINT16			 spec_cmd_parm1_len = 0;
	UINT32           urc_delay_time = 0;
    CHAR             resp_buffer[256] = {0};
    UINT16           resp_len = 0;
    UINT8            i = 0;
    UINT32 			 atHandle = *xid_p;

    require_action_string(op == TEL_EXT_SET_CMD || op == TEL_EXT_TEST_CMD, exit,
                          ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL),
                          "at cmd operation error");

    switch(op)
    {
        case TEL_EXT_SET_CMD:
            param_num = quec_get_at_param_num(parameter_values_p, num_parameters);
            require_action_string(param_num == 1 || param_num == 2, exit,
                                  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                  "quec_get_at_param_num error");

            /* we just save parameters into the corresponding variable in SWITCH structure */
            for(i = 0; i<param_num; i++)
            {
				switch(i)
                {
                    case 0:     // parm0: "urcdelay"
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_str, sizeof(spec_cmd_str)-1, &spec_cmd_len, NULL),
                        					 exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");
                        break;

                    case 1:     // parm1: <enable>
						require_action_string(getExtString(parameter_values_p, i, spec_cmd_parm1_str, sizeof(spec_cmd_parm1_str)-1, &spec_cmd_parm1_len, NULL),
											 exit,
											  ret = ATRESP(atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "getExtString error");

						require_action_string(str2int32(spec_cmd_parm1_str, strlen(spec_cmd_parm1_str), &urc_delay_time),
											  exit,
											  ret = ATRESP(atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "str2int32 error");

						require_action_string(urc_delay_time >= URC_CONFIG_DELAY_TIME_MIN_VALUE && urc_delay_time <= URC_CONFIG_DELAY_TIME_MAX_VALUE,
											  exit,
											  ret = ATRESP(atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "parm is out of range");
                        break;
                }
            }

            /* do the cmd exection */
            if(param_num == 1)
            {
				err = at_urc_config_get_opt(URC_CFG_OPT_DELAY, &urc_delay_time);
                require_noerr_action_string(err, exit,
                                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL),
                                            "at_urc_config_get_opt error");

                resp_len += snprintf(resp_buffer + resp_len, sizeof(resp_buffer)-1, "\r\n%s: \"%s\",%d\r\n",
									 str2upper(command_name_p, strlen(command_name_p)),
									 spec_cmd_str,
									 urc_delay_time);

                err = quec_siolib_transmit_to_atp(*(TelAtParserID *)arg_p, resp_buffer, resp_len, NULL);
                require_noerr_action_string(err, exit, ret = CIRC_FAIL, "quec_siolib_transmit_to_atp error");

                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            }
            else if(param_num == 2)
            {
				err = at_urc_config_set_opt(URC_CFG_OPT_DELAY, &urc_delay_time);
                require_noerr_action_string(err, exit,
                                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL),
                                            "at_urc_config_set_opt error");

                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            }

            break;

        case TEL_EXT_TEST_CMD:
            resp_len += snprintf(resp_buffer + resp_len, sizeof(resp_buffer)-1, "%s: \"%s\",(%d-%d)\r\n",
								 str2upper(command_name_p, strlen(command_name_p)),
								 quectel_cfg_cmd_tbl[QCFG_CMD_URCDELAY].name,
								 URC_CONFIG_DELAY_TIME_MIN_VALUE,
								 URC_CONFIG_DELAY_TIME_MAX_VALUE);

            err = quec_siolib_transmit_to_atp(*(TelAtParserID *)arg_p, resp_buffer, resp_len, NULL);
            require_noerr_action_string(err, exit, ret = CIRC_FAIL, "quec_siolib_transmit_to_atp error");

            break;
    }

exit:
    rc = HANDLE_RETURN_VALUE(ret);
    return rc;
}


