#ifndef QUEC_4MFLASH_SUPPORT_IMS

/*===========================================================================

FUNCTION quectel_exec_qcfg_risignaltype_cmd

DESCRIPTION
  This function takes the result from the command line parser
  and executes it. It executes C command.


DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.

SIDE EFFECTS
  None
===========================================================================*/
RETURNCODE_T  quectel_exec_qcfg_risignaltype_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p                  /* AT cmd parser number         */

)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_SUCCESS;
    QuecOSStatus     err      = kNoErr;
    int              type;
    UINT8            param_num = 0;
    CHAR             spec_cmd_str[32] = {0};
    UINT16           spec_cmd_len = 0;
    CHAR             spec_cmd_parm1_str[16] = {0};
    UINT16           spec_cmd_parm1_len = 0;
    ri_signal_type_e ri_signal_type = RI_SIGNAL_TYPE_MAX;
    CHAR             resp_buffer[256] = {0};
    UINT16           resp_len = 0;
    UINT8            i = 0;
    UINT32 			 atHandle = *xid_p;
    
    switch(op)
    {    
        case TEL_EXT_SET_CMD:   /* AT+QCFG="risignaltype",..  */
            param_num = quec_get_at_param_num(parameter_values_p, num_parameters);
            require_action_string(param_num == 1 || param_num == 2, exit,
                                  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                  "quec_get_at_param_num error");

            err = at_urc_config_get_opt(URC_CFG_OPT_RI_SIG_TYPE, &ri_signal_type);
            require_noerr_action_string(err, exit,
                                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL),
                                        "at_urc_config_get_opt error");

            for(i = 0; i<param_num; i++)
            {
                switch(i)
                {
                    case 0: /* parm0: "risignaltype" */
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_str, sizeof(spec_cmd_str), &spec_cmd_len, NULL),
                                              exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");
                    break;

                    case 1: /* parm1: "respective" or "physical" */
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_parm1_str, sizeof(spec_cmd_parm1_str), &spec_cmd_parm1_len, NULL),
                                              exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");

                        ri_signal_type = at_urc_get_ri_signal_enum(spec_cmd_parm1_str);    
                        
                        require_action_string(ri_signal_type >= RI_SIGNAL_TYPE_RESPECTIVE && ri_signal_type < RI_SIGNAL_TYPE_MAX, exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "invalid ri signal type");
                    break;
                }
            }

            /* do the cmd exection */
            if(param_num == 1)
            {            
                resp_len += snprintf(resp_buffer + resp_len, sizeof(resp_buffer), "\r\n%s: \"%s\",\"%s\"\r\n",
                                     str2upper(command_name_p, strlen(command_name_p)),
                                     spec_cmd_str,
                                     at_urc_get_ri_signal_type_str(ri_signal_type));
                                     

                err = quec_siolib_transmit_to_atp(*(TelAtParserID *)arg_p, resp_buffer, resp_len, NULL);
                require_noerr_action_string(err, exit, ret = CIRC_FAIL, "quec_siolib_transmit_to_atp error");

                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            }
            else if(param_num == 2)
            {
                err = at_urc_config_set_opt(URC_CFG_OPT_RI_SIG_TYPE, &ri_signal_type);
                require_noerr_action_string(err, exit,
                                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL),
                                            "at_urc_config_set_opt error");

                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            }
        break;

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */           
            resp_len += snprintf(resp_buffer + resp_len, sizeof(resp_buffer), "%s: \"%s\",(\"%s\",\"%s\")\r\n",
                                 str2upper(command_name_p, strlen(command_name_p)),
                                 quectel_cfg_cmd_tbl[QCFG_CMD_RISIGNALTYPE].name,
                                 at_urc_get_ri_signal_type_str(RI_SIGNAL_TYPE_RESPECTIVE), //"respective"
                                 at_urc_get_ri_signal_type_str(RI_SIGNAL_TYPE_PHYSICAL));  //"physical"
                                 

            err = quec_siolib_transmit_to_atp(*(TelAtParserID *)arg_p, resp_buffer, resp_len, NULL);
            require_noerr_action_string(err, exit, ret = CIRC_FAIL, "quec_siolib_transmit_to_atp error");
        break;
        
        default:       
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
        break;
    }

exit:
    rc = HANDLE_RETURN_VALUE(ret);
    return rc;
}
#endif

/*===========================================================================

FUNCTION QUECTEL QCFG CMD PROCESS OF URC_RI_OTHER

DESCRIPTION
  This function takes the result from the command line parser
  and executes it. It executes C command.


DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.

SIDE EFFECTS
  None
===========================================================================*/

RETURNCODE_T  quectel_exec_qcfg_urc_ri_other_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p                  /* AT cmd parser number         */

)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_SUCCESS;
    QuecOSStatus     err      = kNoErr;
    int              type;
    UINT8            param_num = 0;
    CHAR             spec_cmd_str[64] = {0};
    UINT16           spec_cmd_len = 0;
	CHAR             spec_cmd_parm1_str[10] = {0};
	UINT16           spec_cmd_parm1_len = 0;
	CHAR             spec_cmd_parm2_str[10] = {0};
	UINT16           spec_cmd_parm2_len = 0;
	CHAR             spec_cmd_parm3_str[10] = {0};
	UINT16           spec_cmd_parm3_len = 0;
    ri_pulse_t       ri_pulse = {RI_OUT_TYPE_NONE};
    CHAR             resp_buffer[256] = {0};
    UINT16           resp_len = 0;
    UINT8            i = 0;
    UINT32 			 atHandle = *xid_p;

    require_action_string(op == TEL_EXT_SET_CMD || op == TEL_EXT_TEST_CMD, exit,
                          ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL),
                          "at cmd operation error");

    switch(op)
    {
        case TEL_EXT_SET_CMD:
            param_num = quec_get_at_param_num(parameter_values_p, num_parameters);
            require_action_string(param_num == 1 || param_num == 2 || param_num == 3 || param_num == 4, exit,
                                  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                  "quec_get_at_param_num error");

            // we get the configuration firstly here to assign the value to local variable [ri_pulse]
            // so that [ri_pulse] can save the current configuration
            // therefore, when there are parm ellipsis, we can just verify the changed parms in [ri_pulse]
            err = at_urc_config_get_opt(URC_CFG_OPT_RI_OTHERS, &ri_pulse);
            require_noerr_action_string(err, exit,
                                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL),
                                        "at_urc_config_get_opt error");


            /* we just save parameters into the corresponding variable in SWITCH structure */
            for(i = 0; i<param_num; i++)
            {
                switch(i)
                {
                    case 0:     // parm0: "urc/ri/other"
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_str, sizeof(spec_cmd_str)-1, &spec_cmd_len, NULL),
                        					  exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");
                        break;

                    case 1:     // parm1: <typeri>
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_parm1_str, sizeof(spec_cmd_parm1_str)-1, &spec_cmd_parm1_len, NULL),
                        					  exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");

                        ri_pulse.out_type = at_urc_ri_get_outtype_enum(spec_cmd_parm1_str);
                        require_action_string(ri_pulse.out_type > RI_OUT_TYPE_NONE && ri_pulse.out_type < RI_OUT_TYPE_ALWAYS, exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "invalid ri out type");
                        break;

                    case 2:     // parm2: <pulseduration>
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_parm2_str, sizeof(spec_cmd_parm2_str)-1, &spec_cmd_parm1_len, NULL),
                        					  exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");

						require_action_string(str2int32(spec_cmd_parm2_str, strlen(spec_cmd_parm2_str), &ri_pulse.duration),
											  exit,
											  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "str2int32 error");

						require_action_string(ri_pulse.duration >= URC_CONFIG_RI_PULSE_OTHERS_DURATION_MIN_VALUE && ri_pulse.duration <= URC_CONFIG_RI_PULSE_OTHERS_DURATION_MAX_VALUE,
											  exit,
											  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "parm is out of range");
                        break;

                    case 3:     // parm3: <pulsecount>
                        require_action_string(getExtString(parameter_values_p, i, spec_cmd_parm3_str, sizeof(spec_cmd_parm3_str)-1, &spec_cmd_parm1_len, NULL),
                        					  exit,
                                              ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
                                              "getExtString error");

						require_action_string(str2int32(spec_cmd_parm3_str, strlen(spec_cmd_parm3_str), &ri_pulse.counter),
											  exit,
											  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "str2int32 error");

						require_action_string(ri_pulse.counter >= URC_CONFIG_RI_PULSE_OTHERS_COUNTER_MIN_VALUE && ri_pulse.counter <= URC_CONFIG_RI_PULSE_OTHERS_COUNTER_MAX_VALUE,
											  exit,
											  ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL),
											  "parm is out of range");
                        break;
                }
            }

            /* do the cmd exection */
            if(param_num == 1)
            {
                resp_len += snprintf(resp_buffer + resp_len, sizeof(resp_buffer)-1, "\r\n%s: \"%s\",\"%s\",%d,%d\r\n",
                                     str2upper(command_name_p, strlen(command_name_p)),
                                     spec_cmd_str,
                                     at_urc_ri_get_outtype_str(ri_pulse.out_type),
                                     ri_pulse.duration,
                                     ri_pulse.counter);

                err = quec_siolib_transmit_to_atp(*(TelAtParserID *)arg_p, resp_buffer, resp_len, NULL);
                require_noerr_action_string(err, exit, ret = CIRC_FAIL, "quec_siolib_transmit_to_atp error");

                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            }
            else if(param_num == 2 || param_num == 3 || param_num == 4)
            {
                err = at_urc_config_set_opt(URC_CFG_OPT_RI_OTHERS, &ri_pulse);
                require_noerr_action_string(err, exit,
                                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL),
                                            "at_urc_config_set_opt error");

                ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            }

            break;

        case TEL_EXT_TEST_CMD:
            resp_len += snprintf(resp_buffer + resp_len, sizeof(resp_buffer)-1, "%s: \"%s\",(\"%s\",\"%s\"),(%d-%d),(%d-%d)\r\n",
                                 str2upper(command_name_p, strlen(command_name_p)),
                                 quectel_cfg_cmd_tbl[QCFG_CMD_URC_RI_OTHER].name,
                                 at_urc_ri_get_outtype_str(RI_OUT_TYPE_OFF),
                                 at_urc_ri_get_outtype_str(RI_OUT_TYPE_PULSE),
                                 URC_CONFIG_RI_PULSE_OTHERS_DURATION_MIN_VALUE,
                                 URC_CONFIG_RI_PULSE_OTHERS_DURATION_MAX_VALUE,
                                 URC_CONFIG_RI_PULSE_OTHERS_COUNTER_MIN_VALUE,
                                 URC_CONFIG_RI_PULSE_OTHERS_COUNTER_MAX_VALUE);

            err = quec_siolib_transmit_to_atp(*(TelAtParserID *)arg_p, resp_buffer, resp_len, NULL);
            require_noerr_action_string(err, exit, ret = CIRC_FAIL, "quec_siolib_transmit_to_atp error");
            break;
    }

exit:
    rc = HANDLE_RETURN_VALUE(ret);
    return rc;
}



//Chaim@qian add 2018.11.14
RETURNCODE_T  quectel_exec_qcfg_usbnet_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    int              type;
    UINT32  index;
    //UINT32           atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);

    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    char res_buf[100]={0};
   // UINT8 len=0;
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    quec_usb_net_type_e get_net_type=0;
    UINT32  set_net_type=0;
    UINT8 resp_len=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QCFG="usbnet",..  */
            {

                if(param_num==1)
                {
					#ifndef MV_USB2_NO_USBNET
                    status =quec_get_usb_net_type(&get_net_type);
					#endif
                    atcmd_general_log("ret=%d,get_net_type=%d",ret,get_net_type);
                    if(status!=QUEC_SUCCESS)
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                    else
                    {
                         //char resp[]="AT+QCFG=\"usbnet\",";
                         resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbnet\",%d\r\n",get_net_type);
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    }

                }
                else if(param_num==2)
                {
                    set_net_type=1;
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE))
                    {
                         if(str2int32(cfg_cmd_param_str,2,&set_net_type))  //check if the num is large than 10
                         {
                             atcmd_general_log(" qcfg_usb_net type=%d",set_net_type);
                             //Chaim 201908007,usb connect linux environment,change usb net fomr uart,will dump
                            /* status=quec_change_usb_net_type(set_net_type);
                             if(status!=QUEC_SUCCESS)
                             {
                                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                             }
                             else
                             {*/
                                 status=quec_save_usb_net_type_fat(set_net_type);
                                 if(status!=QUEC_SUCCESS)
                                 {
                                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                                 }
                                 else
                                 {
                                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, 0);
                                 }
                                 atcmd_general_log(" quec_save_usb_net_type_fat status=%d",status);
                            // }

                         }
                         else
                         {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         }
                    }
                    else
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {

                 resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbnet\",(%d,%d)\r\n",\
                    QUEC_QCFG_USBNET_VAL_1,QUEC_QCFG_USBNET_VAL_2);
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

extern void USB_PHY_INC_300ppm(void);
extern void USB_PHY_DEC_300ppm(void);
extern void USB_PHY_INC_400ppm(void);
extern void USB_PHY_default(void);
UINT8 quec_usb_phy = 0;
RETURNCODE_T  quectel_exec_qcfg_usbphy_cmd
(
	 const utlAtParameterOp_T		 op,					/* AT cmd type					*/
	 const char 					*command_name_p,		/* AT cmd name					*/
	 const utlAtParameterValue_P2c	 parameter_values_p,	/* AT cmd value 				*/
	 const size_t					 num_parameters,		/* AT cmd number				*/
	 const char 					*info_text_p,			/* AT cmd usage string			*/
	 unsigned int					*xid_p, 				/* AT cmd handle				*/
	 void							*arg_p				    /* AT cmd parser number 		*/
)
{
	RETURNCODE_T	 rc 	  = INITIAL_RETURN_CODE;
	CiReturnCode	 ret	  = CIRC_FAIL;
	QuecOSStatus 	 status   = QUEC_SUCCESS;
	UINT32	         index    = 0  ;
	UINT32           atHandle = *xid_p;
	UINT8            param_num= 0;
	
	index  = *(TelAtParserID *)arg_p;
	char  res_buf[100] = {0};
	char  cfg_cmd_param_str[30+1] = {0};
	UINT8 cfg_cmd_param_str_len=0;
	UINT8 resp_len = 0;
    UINT32 usbphy = quec_usb_phy;
	param_num = quec_get_at_param_num(parameter_values_p,num_parameters);
	atcmd_general_log("command type=%d,param_num=%d",op,param_num);
	switch (op)
	{
		case TEL_EXT_SET_CMD:	 /* AT+QCFG="usbversion",.. */
			{
				if(param_num==1) {
					 //read nvm 
					 //usb_version = quec_read_usb_version_is20()?1:0;
					 resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbphy\",%d\r\n",usbphy);
					 ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
				} else if(param_num==2) {
					//get parm type USBDevice_USBVersionE
					if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 2, &cfg_cmd_param_str_len, NULL) == TRUE)) {
						if(str2int32(cfg_cmd_param_str,2,&usbphy)){
							// save to nvm
							atcmd_general_log("usbphy=%d",usbphy);

							switch(usbphy)
							{
								case 0:
									USB_PHY_default();
									break;
								case 1:
									USB_PHY_DEC_300ppm();
									break;
								case 2:
									USB_PHY_INC_300ppm();;
									break;
								case 3:
									USB_PHY_INC_400ppm();
									break;
								default:
									USB_PHY_default();
							}	
							quec_usb_phy = usbphy;
							atcmd_general_log("usbphy=%d",quec_usb_phy);
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, 0);
						} else {
							//atcmd_general_log("param:%d usb_version=%d" , parameter_values_p[1].value.decimal, usb_version);
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						}	
					} else {
						//atcmd_general_log("param:%d usb_version=%d" , parameter_values_p[1].value.decimal, usb_version);
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
					}
				} else {
				 	 ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
				}
				break;
			}
		case TEL_EXT_TEST_CMD:	  /* AT+QCFG=? */
			{
				resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"usbphy\",(0-3)\r\n");
				ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
				break;
			}
		default:
			{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
				break;
			}
	}
		
	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return(rc);
}

//Chaim@qian add 2018.12.12
RETURNCODE_T  quectel_exec_qcfg_uart2ipr_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;
    int              type;
    UINT32  index;
    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    
    UINT8 param_num=0;
    char res_buf[100]={0};
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    UINT8  set_net_type=0;
    UINT8 resp_len=0;
    //uint16 vid_pid[2]={0};//vid_pid[0]--vid,vid_pid[1]--pid
    UART_BaudRates baudrate = UART_MAX_NUM_BAUD;
    UART_BaudRates currentbaudrate = UART_MAX_NUM_BAUD;
    uint8 i=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    
            {

                if(param_num==1)
                {
                    quec_status = quec_uart_get_current_baudrate(TEL_AT_CMD_ATP_UART2,&baudrate);
                    if(quec_status != QUEC_SUCCESS)
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, 0, res_buf);
                        atcmd_general_log("quec_uart_get_current_baudrate fail");
                    }
                    else
                    {
                         //char resp[]="AT+QCFG=\"usbid\",";
                         resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"uart2ipr\",%d\r\n",baudrate);
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    }
                }
                else if(param_num==2)
                {

                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == FALSE))
                    {

                        atcmd_general_log("uart2 ipr set param fail");
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                        rc = HANDLE_RETURN_VALUE(ret);
                        return(rc);
                    }
                    else
                    {
                        if(str2int32(cfg_cmd_param_str, 8, &baudrate)==FALSE)  //check if the num is large than UART_BAUD_921600
                        {
                            atcmd_general_log("uart2 ipr get_baudrate from cmd fail");
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                            rc = HANDLE_RETURN_VALUE(ret);
                            return(rc);
                        }
                    }

                    quec_status=quec_uart_check_baudrate(baudrate);
                    if(quec_status == QUEC_SUCCESS)
                    {
                        quec_status = quec_uart_get_current_baudrate(TEL_AT_CMD_ATP_UART2,&currentbaudrate);
                        if(quec_status != QUEC_SUCCESS)
                        {
                            atcmd_general_log("index=%d uart2 ipr get current baudrate=%d fail", index);
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                            rc = HANDLE_RETURN_VALUE(ret);
                            return(rc);
                        }
                    }
                    else
                    {
                        
                        atcmd_general_log("index=%d uart2 ipr check baudrate=%d fail", index, baudrate);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                        rc = HANDLE_RETURN_VALUE(ret);
                        return(rc);
                    }

                    //chaim@qian 2018.11.15 need response first
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
                    atcmd_general_log("uart2ipr set ipr=%d",baudrate);
                    
                    if(currentbaudrate != baudrate)
                    {
                        atcmd_general_log(",index=%d get_currentbaud=%d,set_baudrate=%d ", index,currentbaudrate, baudrate);
                        quec_uart_ipr_set_baudrate(TEL_AT_CMD_ATP_UART2, baudrate);
                        quec_uart_ipr_timer_start(TEL_AT_CMD_ATP_UART2);
                    }
   

                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {
                resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"uart2ipr\",(4800,9600,19200,38400,57600,115200,230400,460800,921600)\r\n");
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len, NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

//Chaim@qian add 2019.1.16 add ppp/termframe cmd
RETURNCODE_T  quectel_exec_qcfg_termframe_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
#ifdef QUEC_PPP_ENABLE
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;
    int              type;
    UINT32  index;
    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    
    UINT8 param_num=0;
    char res_buf[100]={0};
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    UINT8 resp_len=0;

    uint8 i=0;

    uint32 termframe_flag=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:   
            {

                if(param_num==1)
                {
                    termframe_flag = quec_ppp_get_terminateframe_flag();
                    resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"ppp/termframe\",%d\r\n",termframe_flag);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    
                }
                else if(param_num==2)
                {

                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == FALSE))
                    {

                        atcmd_general_log("ppp/termframe set param fail");
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                        rc = HANDLE_RETURN_VALUE(ret);
                        return(rc);
                    }
                    else
                    {
                        if(str2int32(cfg_cmd_param_str, 2, &termframe_flag)==FALSE)  //check if the num is large than 10
                        {
                            atcmd_general_log("ppp/termframe get flag from cmd fail");
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                            rc = HANDLE_RETURN_VALUE(ret);
                            return(rc);
                        }
                    }

                    quec_status=quec_ppp_set_terminateframe_flag(termframe_flag);
                    if(quec_status == QUEC_SUCCESS)
                    {
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
                        atcmd_general_log("ppp/termframe set flag=%d ok", termframe_flag);
                    }
                    else
                    {
                        
                        atcmd_general_log("index=%d ppp/termframe set termframe_flag=%d fail", index, termframe_flag);
                        ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                        rc = HANDLE_RETURN_VALUE(ret);
                        return(rc);
                    }

                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {
                resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"ppp/termframe\",(0,1)\r\n");
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len, NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
#endif
    return(rc);
}

