/*===========================================================================

FUNCTION QUEC_EXEC_QCFG_IPRECOVERY_CMD

DESCRIPTION
  This function takes the result from the command line parser
  and executes it.
  This command enable/disable the IP recovery of ASR.

DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.
    utlFAILED :if there was any problem in executing the command.

SIDE EFFECTS
  None
===========================================================================*/


RETURNCODE_T  quectel_exec_qcfg_iprecovery_cmd
(
         const utlAtParameterOp_T        op,                 /* AT cmd type          */
         const char                     *command_name_p,     /* AT cmd name          */
         const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
         const size_t                    num_parameters,     /* AT cmd number        */
         const char                     *info_text_p,        /* AT cmd usage string  */
         unsigned int                   *xid_p,              /* AT cmd handle        */
         void                           *arg_p
)
{

    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    int              type;
    //UINT32           atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);

    UINT32 atHandle =      *xid_p;

    UINT32 enable=0;

    UINT8 param_num=0;
    UINT32 index  = *(TelAtParserID *)arg_p;
    char res_buf[100]={0};
    UINT8 len=0;
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QCFG="IPRECOVERY",..  */
            {

                if(param_num==1)
                {
                    sprintf( res_buf,"+QCFG: \"iprecovery\",%d\r\n",qcfg_iprecovery);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    break;
                }
                else if(param_num==2)
                {
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE))
                    {
                         if(str2int32(cfg_cmd_param_str,1,&enable))
                         {
                             atcmd_general_log(":enable=%d",enable);
                             if(qcfg_iprecovery != enable)
                             {
                             	qcfg_iprecovery=enable;
                             	if(quectel_nv_fat_write(QUEC_AT_IPRECOVERY, &qcfg_iprecovery, sizeof(qcfg_iprecovery))==QUEC_FAT_SUCCESS)
								{						
									ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
								}
								else
								{
									atcmd_general_log("save_to_nv ERROR");
									ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
								}
                             }
                         }
                         else
                         {
                         	ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         }

                    }
                    else
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {
                len=strlen((char *)"+QCFG: \"iprecovery\",(0,1)\r\n");
                memcpy(res_buf,(char *)"+QCFG: \"iprecovery\",(0,1)\r\n",len);
                ret=quec_siolib_transmit_to_atp(index,res_buf,len, NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}


//Chaim@qian add 2018.11.14
RETURNCODE_T  quectel_exec_qcfg_cmux_channel_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    int              type;
    UINT32  index;

    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    char res_buf[100]={0};
   // UINT8 len=0;
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    uint8  get_channel=0;
    uint8  set_channel=0;
    UINT8 resp_len=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
#ifndef __CMUX_DISABLE
		#ifdef QUEC_CMUX_ENABLE

        case TEL_EXT_SET_CMD:    /* AT+QCFG="cmux/channel",..  */
            {

                if(param_num==1)
                {
                    /* 
                        "get_channel" is a boundary value for checking the max channel,MAX:5
                        Command cmux/channel returns the actual channel.So it returns the "get_channel - 1" but need the zero check;
                    */
                    get_channel = quec_cmux_get_channel_num();
                    atcmd_general_log("get_channel=%d",get_channel);
                    resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"cmux/channel\",%d\r\n",(0 == get_channel)? 0 : (get_channel - 1));
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);

                }
                else if(param_num==2)
                {
                    set_channel=1;
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE))
                    {
                         if(str2int32(cfg_cmd_param_str,2,&set_channel))  //check if the num is large than 10
                         {
                             atcmd_general_log(" cmux set_channel =%d",set_channel);
                             status = quec_cmux_set_channel_num(set_channel);
                             if(status != QUEC_SUCCESS)
                             {
                                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                                atcmd_general_log(" quec set cmux channel status=%d fail",status);
                             }
                             else
                             {
                               ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
                             }

                         }
                         else
                         {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         }
                    }
                    else
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {

                 resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"cmux/channel\",(%d-%d)\r\n",\
                    QUEC_CMUX_CHANNEL_MIN,QUEC_CMUX_CHANNEL_MAX);
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }
		#endif /*QUEC_CMUX_ENABLE*/

		#else
		 ret = kNoErr;//Sharon.li@20220419 不支持的CMUX的版本,此AT也返回OK
		#endif
    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

