QuecOSStatus quec_creg_report_read(void)
{
    QuecOSStatus ret = kGeneralErr;
    UINT8 report_enable = 0;
    
	ret = quectel_nv_fat_read(QUEC_CREG_REPORT_EMERGENCY_NVM, &report_enable, sizeof(UINT8));

    if(ret != QUEC_SUCCESS)
    {
        atcmd_general_log("creg_report_emergency read fail");
    }
	else
	{
		quec_creg_report_emergency = report_enable;
	}

    return ret;
}

QuecOSStatus quec_creg_report_write(UINT8 report_enable)
{
    QuecOSStatus ret = kGeneralErr;

    if (report_enable > 1)
    {
        return ret;
    }

    if (quec_creg_report_emergency == report_enable)
    {
        return QUEC_SUCCESS;
    }
    
	ret = quectel_nv_fat_write(QUEC_CREG_REPORT_EMERGENCY_NVM, &report_enable, sizeof(UINT8));

    if(ret == QUEC_SUCCESS)
    {
        quec_creg_report_emergency = report_enable;
    }
    else
    {
        atcmd_general_log("creg_report_emergency write fail");
    }
    return ret;

}

RETURNCODE_T  quectel_exec_qcfg_creg_emergency_cmd
(
	 const utlAtParameterOp_T		 op,					/* AT cmd type					*/
	 const char 					*command_name_p,		/* AT cmd name					*/
	 const utlAtParameterValue_P2c	 parameter_values_p,	/* AT cmd value 				*/
	 const size_t					 num_parameters,		/* AT cmd number				*/
	 const char 					*info_text_p,			/* AT cmd usage string			*/
	 unsigned int					*xid_p, 				/* AT cmd handle				*/
	 void							*arg_p				/* AT cmd parser number 		*/
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    int              type;
    UINT32  index;

    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    char res_buf[100]={0};
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    UINT8 creg_report = 0;
    UINT8 resp_len=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QCFG="creg/emergency",..  */
            {

                if(param_num==1)
                {
                     resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"creg/emergency\",%d\r\n", quec_creg_report_emergency);
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                }
                else if(param_num==2)
                {
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 1, &cfg_cmd_param_str_len, NULL) == TRUE))
                    {
                         if(str2int32(cfg_cmd_param_str, 1, &creg_report))
                         {
                             atcmd_general_log("set creg_report=%d", creg_report);
                             status = quec_creg_report_write(creg_report);
                             if(status != QUEC_SUCCESS)
                             {
                                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                             }
                             else
                             {
                                ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, 0);
                             }
                         }
                         else
                         {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         }
                    }
                    else
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {
                 resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"creg/emergency\",(0,1)\r\n");
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

