QuecOSStatus quec_transmission_rate_config(void)
{
    int file_fd = 0;
    int transmission_rate = 0;
    char read_buf[128];
    file_fd = FDI_fopen("lwip_rate.cfg", "rb");
    if (file_fd > 0)
    {
        FDI_fread((void *)read_buf, 1, sizeof(read_buf), file_fd);
        sscanf(read_buf,"lwip_rate=%d",&transmission_rate);
        FDI_fclose(file_fd);
        
        if (transmission_rate <= 0)
        {
            //set_dl_rate_control_flag(0);
            //set_DLMaxRate(0);
        }
        else
        {
            if(transmission_rate>1000000)
                transmission_rate = 1000000;
            //set_dl_rate_control_flag(1);
            //set_DLMaxRate(transmission_rate);
        }
    }
    transmission_rate = 0;
    memset(read_buf,0,sizeof(read_buf));

    file_fd = FDI_fopen("ppp_rate.cfg", "rb");
    if(file_fd > 0)
    {
        FDI_fread((void *)read_buf, 1, sizeof(read_buf), file_fd);
        sscanf(read_buf,"ppp_rate=%d",&transmission_rate);
        FDI_fclose(file_fd);

        if (transmission_rate <= 0)
        {
//            set_ppp_ul_rate_ctrl(0);
        }
        else
        {
            if (transmission_rate>750000)
                transmission_rate = 750000;
//            set_ppp_ul_rate_ctrl(transmission_rate);
        }
    }

    return 0;
}


//Fitz.xu 20200414: add AT^DSCI support
#ifdef QUEC_CALL_DSCI_SUPPORT
/*===========================================================================

FUNCTION quec_exec_call_dsci_cmd

DESCRIPTION
  This function is used to enable/disable ^DSCI.

DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.
    utlFAILED :if there was any problem in executing the command.

SIDE EFFECTS
  None

===========================================================================*/
RETURNCODE_T quec_exec_call_dsci_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */
    void                           *arg_p               /* AT cmd parser number */
)
{
    TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32 atHandle = MAKE_AT_HANDLE( sAtpIndex );
    RETURNCODE_T ret = utlSUCCESS;      
    *xid_p = atHandle;
    uint8 param_num = 0;
    char resp_buf[64] = {0};
    uint8 at_dsci = 0;
    
    switch (op)
    {
        case TEL_EXT_SET_CMD:
        case TEL_EXT_ACTION_CMD: /* AT^DSCI=<n> */
        {
            if (TRUE != getExtValue(parameter_values_p, 0, &at_dsci, 0, 1, 0))
            {
                ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
                break;
            }

            quec_dsci_flag_set(at_dsci);
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
        }
        break;
        
        case TEL_EXT_GET_CMD: /* AT^DSCI? */
        {
            sprintf(resp_buf, "^DSCI: %d", quec_dsci_flag_get());
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, resp_buf);
        }    
        break;    
        
        case TEL_EXT_TEST_CMD: /* AT^DSCI=? */
        {
            sprintf(resp_buf, "%s", "^DSCI: (0,1)");
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, resp_buf);
        }     
        break;
        
        default:
        {
            atcmd_general_log("command type error: %d", op);
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_ILLEGAL_OPERATION, NULL);
        }   
        break;
    }

    return ret;
}
#endif

#if QUEC_CUSD_OPTIMIZE
RETURNCODE_T quec_exec_qcusdcvt_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */
    void                           *arg_p               /* AT cmd parser number */
)
{
	RETURNCODE_T	rc = INITIAL_RETURN_CODE;
	CiReturnCode	ret	= CIRC_FAIL;
	char res_buf[128] = {0};
	UINT8 resp_len = 0;
	UINT8 param_num = 0;
	UINT32 atHandle = MAKE_AT_HANDLE(*(TelAtParserID*)arg_p);				
	*xid_p = atHandle;
    uint8 at_cusdcvt = 0;
    
	param_num = quec_get_at_param_num(parameter_values_p,num_parameters);
    
	switch (op)
	{
		case TEL_EXT_SET_CMD:	 
		{
		    if (TRUE != getExtValue(parameter_values_p, 0, &at_cusdcvt, 0, 1, 0))
            {
                ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
                break;
            }

            if (at_cusdcvt != quec_nv_cusdcvt_flag_get())
            {
                quectel_nv_fat_write(QUEC_CUSDCVT_CFG, &at_cusdcvt, sizeof(at_cusdcvt)); 
            }
        
            quec_nv_cusdcvt_flag_set(at_cusdcvt);
            
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
			break;
		}
        
		case TEL_EXT_GET_CMD:
		{
			sprintf(res_buf, "+QCUSDCVT: %d", quec_nv_cusdcvt_flag_get());
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
			break;
		}

		default:
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			break;
		}
	}

	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return(rc);
}

void quec_nv_cusdcvt_flag_set(uint8 cusdcvt)
{
    quec_cusdcvt_flag = cusdcvt;  
}

char quec_nv_cusdcvt_flag_get(void)
{
    return quec_cusdcvt_flag;  
}

void quec_nv_cusdcvt_flag_init(void)
{
    int fat_ret = QUEC_FAT_FAILED;
    
    fat_ret = quectel_nv_fat_read(QUEC_CUSDCVT_CFG, &quec_cusdcvt_flag, sizeof(quec_cusdcvt_flag));
    if (fat_ret != QUEC_FAT_SUCCESS)
    {
        quec_cusdcvt_flag = 0;
    }
}
#endif

