#if QUEC_SIM_PIN_CTRL_FUNC      //20200717 kevin.wang add dual sim control function 
#include "quec_rtos.h"
quec_task_t p_quec_sim_gpioctl_task = NULL;

quec_pin_ctrl_t  quec_pin_ctrl={1,0};    //default value
quec_queue_t  g_quec_sim_gpioctl_handle_queue = NULL;

extern int GetCfunValue(void);
extern void USIM_DetectFoundByHW(BOOL inserted);
extern void quec_sim_set_cfun(int cfun_value);

void sim_gpio_ctl(UINT8 value)              //kevin.wang 20200709 add for sim switch ,119 pin
{	
	quec_pin_config_s sim_gpio_init_struc;
	QuecOSStatus err;
	sim_gpio_init_struc.config.pinNumber = ASR_SIMCTL_PIN;
	sim_gpio_init_struc.config.direction = GPIO_OUT_PIN;
	sim_gpio_init_struc.config.initialValue = value;	
	switch (value)
	{
		case 0:
			sim_gpio_init_struc.config.pullUpDown = GPIO_PULL_DOWN_ENABLE;
			sim_gpio_init_struc.mfprReg_data = QUEC_AF0_C |QUEC_PULL_DN_C |QUEC_DRV_FAST_C |QUEC_RESERVED_C;
		break;
		case 1:
			sim_gpio_init_struc.config.pullUpDown = GPIO_PULL_DOWN_ENABLE;
			sim_gpio_init_struc.mfprReg_data = QUEC_AF0_C |QUEC_PULL_UP_C |QUEC_DRV_FAST_C |QUEC_RESERVED_C;	
		break;		
		default:
			atcmd_general_log("error value");
		break;
	}
	quec_gpio_init(&sim_gpio_init_struc);
	quec_set_gpio_level(ASR_SIMCTL_PIN,value);
}

static void quec_sim_gpioctl_handle_task(void * argv)
{
	QuecOSStatus ret = QUEC_SUCCESS;
	UINT8 sim_gpioctl_value = 2;
	while(1)
	{
	//	CPUartLogPrint("enter the quec_sim_gpioctl_handle_task");
		ret = quec_rtos_queue_wait(g_quec_sim_gpioctl_handle_queue, &sim_gpioctl_value, sizeof(UINT8), QUEC_WAIT_FOREVER);        
        if(OS_SUCCESS != ret||(sim_gpioctl_value!=1 && sim_gpioctl_value!=0))
        {
            atcmd_general_log("failed to get sim_gpioctl value");
            continue;
        }
		quec_sim_change();
		sim_gpioctl_task_delete();
	}
}

QuecOSStatus sim_gpioctl_task_init(void)
{
	QuecOSStatus err = kNoErr;
	if(g_quec_sim_gpioctl_handle_queue == NULL)
	{
		err = quec_rtos_queue_create(&g_quec_sim_gpioctl_handle_queue, sizeof(UINT8) , QUEC_SIM_GPIOCTL_HANDLE_MAX);
    	if(err != kNoErr )
    	{
        	atcmd_general_log("sim_gpioctl queue create fail");
        	return err;
    	}
		atcmd_general_log("sim_gpioctl queue create done");
	}
	else
		return kGeneralErr;

	err = quec_rtos_task_create(&p_quec_sim_gpioctl_task, QUEC_SIM_GPIOCTL_TASK_STACK_SIZE, QUEC_SIM_GPIOCTL_TASK_PRIORITY,"c_quec_sim_gpioctl_handle_task", quec_sim_gpioctl_handle_task, NULL);
    if (kNoErr != err)
   	{
       	atcmd_general_log("sim_gpioctl_task init failed");
       	return err;
   	}
    CPUartLogPrint("sim_gpioctl_task init done",false);
    return err;
}

QuecOSStatus sim_gpioctl_task_delete(void)
{	
	if(quec_rtos_queue_delete(g_quec_sim_gpioctl_handle_queue))
	{
		atcmd_general_log("delete queue failed");
		return kGeneralErr;
	}
	else
		atcmd_general_log("delete queue sucessful");
	g_quec_sim_gpioctl_handle_queue = NULL;
	if(quec_rtos_task_delete_ex(NULL))
	{
		atcmd_general_log("delete task failed");
		return kGeneralErr;
	}
	return kNoErr;
}


int32 sim_gpio_sim_write_flash(quec_pin_ctrl_t *sim_pin_ctrl_value)
{
	quec_pin_ctrl_t default_value;
	if(quectel_nv_fat_read(QUEC_PIN_CTRL_FILE,&default_value,sizeof(default_value)))
	{
		atcmd_general_log("file %s not exit",QUEC_PIN_CTRL_FILE);
		if(quectel_nv_fat_write(QUEC_PIN_CTRL_FILE,sim_pin_ctrl_value,sizeof(quec_pin_ctrl_t)))
		{
			atcmd_general_log("write failed");
			return 1;
		} else {
			return QUEC_FAT_SUCCESS;
		}
	}
	if(sim_pin_ctrl_value->sim_119_pin_value == default_value.sim_119_pin_value)      //the data will be write is same as it in file, don't wrtie  
	{
		return QUEC_FAT_SUCCESS;
	}
	else
	{
		if(quectel_nv_fat_write(QUEC_PIN_CTRL_FILE,sim_pin_ctrl_value,sizeof(quec_pin_ctrl_t)))
		{
			atcmd_general_log("write failed");
			return 1;
		}
		else
			return QUEC_FAT_SUCCESS;
	}
}

void sim_gpio_read_flash(void)
{
	if(quectel_nv_fat_read(QUEC_PIN_CTRL_FILE,&quec_pin_ctrl,sizeof(quec_pin_ctrl_t)))
	{
		atcmd_general_log("read failed");
		return 1;
	}
	if(quec_pin_ctrl.sim_119_pin_func_enable)
		sim_gpio_ctl(quec_pin_ctrl.sim_119_pin_value);
}

void quec_sim_change(void)
{
#ifdef QUECTEL_PROJECT_CUST 		

	if(GetCfunValue() != 0) 
	{
		USIM_DetectFoundByHW(0);
		OSATaskSleep(100);
		USIM_DetectFoundByHW(1);
	}
	else
	{
		atcmd_general_log("cfun0 not allow handle sim card"); 		
	}
#else
		quec_sim_set_cfun(0);
	    quec_sim_set_cfun(1);
#endif	
}

RETURNCODE_T  quec_exec_qdsim_cmd
(
    const utlAtParameterOp_T    op,
    const char                   *command_name_p,
    const utlAtParameterValue_P2c parameter_values_p,
    const size_t                  num_parameters,
    const char                   *info_text_p,
    unsigned int                 *xid_p,
    void                         *arg_p
)
{
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32 atHandle = MAKE_AT_HANDLE( sAtpIndex );
    RETURNCODE_T ret = utlSUCCESS;      
    *xid_p = atHandle;
	uint8 para_num, pin_num,simctl_value, SIM_GPIOCTL_FLAG = 1;
	char ret_back[20];
	para_num=quec_get_at_param_num(parameter_values_p,num_parameters);
	pin_num = parameter_values_p[0].value.decimal;
	switch(op)
	{
		case TEL_EXT_SET_CMD:
			if(para_num == 1)
			{			
				if (getExtValue(parameter_values_p, 0, &simctl_value, 0, 1, NULL) == FALSE)
				{
					atcmd_general_log("get the value failed");
					ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
				}
				else
				{
					quec_pin_ctrl.sim_119_pin_value = simctl_value;
					quec_pin_ctrl.sim_119_pin_func_enable = 1;
					if(sim_gpio_sim_write_flash(&quec_pin_ctrl))
					{
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
					}					
					sim_gpio_ctl(quec_pin_ctrl.sim_119_pin_value);
					if(sim_gpioctl_task_init())
					{
						CPUartLogPrint("sim_gpioctl task creat failed",false);
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_UNKNOWN, NULL);
					}
					if(OSAMsgQSend(g_quec_sim_gpioctl_handle_queue, sizeof(UINT8), (UINT8*)&SIM_GPIOCTL_FLAG, OSA_NO_SUSPEND))
   					{
      					atcmd_general_log("sim_gpioctl send to queue failed");
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_UNKNOWN, NULL);
  					}
					ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				}
			}		
			else
			{
				ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
			}
		break;

		case TEL_EXT_TEST_CMD: /* AT+QDSIM=? */
        {
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, "+QDSIM: (0,1)");
        }     
        break;

		case TEL_EXT_GET_CMD: /* AT+QDSIM? */
        {
        	sprintf(ret_back,"+QDSIM: %d",quec_pin_ctrl.sim_119_pin_value);
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, ret_back);
        }    
        break;
			
		default:
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
		break;
	}
	return ret;
}
#endif

//isaac 20200602: add at+qcfg="csqtype",<val> to calculate csq by rssi(val is 0) or rsrp(val is 1)
#ifdef QUECTEL_CSQ_TYPE
UINT32 g_quec_csqtype = 0; //0: rssi 1: rsrp
#define QUEC_EFS_CSQ_TYPE   "csq_type"

void quec_set_csq_type(UINT32 csqtype)
{
    g_quec_csqtype = csqtype;
}
UINT32 quec_get_csq_type(void)
{
    return g_quec_csqtype;
}

QuecOSStatus quec_read_csq_type_from_nv(void)
{
	QuecOSStatus ret = kGeneralErr;
	UINT32 csqtype = 0;
	
	
    ret = quectel_nv_fat_read(QUEC_EFS_CSQ_TYPE, &csqtype, sizeof(UINT32));
    if(ret != QUEC_FAT_SUCCESS)
    {
        atcmd_general_log("[quec csq]nv init: CSQ TYPE value %d read failed",csqtype); 
        return ret;
    }
	else
	{
		/*loading user cfg to RAM*/
        if ((0 == csqtype) || (1 == csqtype))
        {
            quec_set_csq_type(csqtype);
        }
        else 
        {
            quec_set_csq_type(0);
        }
	}

    return QUEC_SUCCESS;
}


QuecOSStatus quec_save_csq_type_to_nv(UINT32 csqtype)
{
    QuecOSStatus ret = kGeneralErr;
	UINT32 old_val = 0;
    
    /*êy?YóDD§D?ò??é?¤1y*/
	if (QUEC_FAT_SUCCESS != quectel_nv_fat_read(QUEC_EFS_CSQ_TYPE,&old_val,sizeof(UINT32)))
	{
		atcmd_general_log("[quec csq] csq type read nv failed,use default value");
	}
	if (csqtype != old_val)
	{
        ret = quectel_nv_fat_write(QUEC_EFS_CSQ_TYPE, &csqtype, sizeof(UINT32));
    	if (ret != QUEC_FAT_SUCCESS)
    	{
        	atcmd_general_log("[quec csq] csq type value %d write failed",csqtype);
       	 	return ret;
    	}
	}
    else 
    {
		atcmd_general_log("[quec csq]csq type value %d no change",csqtype);
	}
    return QUEC_SUCCESS;
}

RETURNCODE_T  quectel_exec_qcfg_csqtype_cmd
(
    const utlAtParameterOp_T      op,
    const char                   *command_name_p,
    const utlAtParameterValue_P2c parameter_values_p,
    const size_t                  num_parameters,
    const char                   *info_text_p,
    unsigned int                 *xid_p,
    void                         *arg_p
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    
    UINT32           index;
    UINT8 param_num=0,csqtype = 0,resp_len=0,cfg_cmd_param_str_len=0;
    char  cfg_cmd_param_str[20] = {0},res_buf[64]={0};
    
    UINT32 atHandle = *xid_p;
    index  = *(TelAtParserID *)arg_p;
    
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QCFG="csqtype",..  */
            {

                if(param_num==1)
                {
                     resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"csqtype\",%d\r\n", quec_get_csq_type());
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                }
                else if(param_num==2)
                {
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 1, &cfg_cmd_param_str_len, NULL) == TRUE))
                    {
                         if(str2int32(cfg_cmd_param_str, 1, &csqtype))
                         {  
                             if ((csqtype == 0) || (csqtype == 1))
                             {
                                quec_set_csq_type(csqtype);
                                /*±￡′?μ?nv*/
                                quec_save_csq_type_to_nv(csqtype);
                                ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                             }
                             else 
                             {
                                atcmd_general_log("[quec csq]set csqtype=%d", csqtype);
                                quec_set_csq_type(0);
                                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                             }
                         }
                         else
                         {
                            atcmd_general_log("[quec csq] csqtype str2int32 error");
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         }
                    }
                    else
                    {
                         atcmd_general_log("[quec csq] get qcfg csqtype string error");
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     atcmd_general_log("[quec csq] param_num %d too much",param_num);
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {
                resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"csqtype\",(0,1)\r\n");
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);

}
#endif

