/*===========================================================================

FUNCTION quec_exec_cell_select_cfg_cmd

DESCRIPTION
  This function is used to config cell select rsrp,rssi offset.

DEPENDENCIES
  None

RETURN VALUE
  returns an enum that describes the result of the command execution.
  possible values:
    utlSUCCESS : if it is a success.
    utlFAILED :if there was any problem in executing the command.

SIDE EFFECTS
  None

===========================================================================*/

RETURNCODE_T  quec_exec_cell_select_cfg_cmd
(
    const utlAtParameterOp_T      op,
    const char                   *command_name_p,
    const utlAtParameterValue_P2c parameter_values_p,
    const size_t                  num_parameters,
    const char                   *info_text_p,
    unsigned int                 *xid_p,
    void                         *arg_p
)
{
	UINT8 	param_num = 0,cmd_index = 0,resp_len = 0;
	char 	cell_select_cfg_cmd_str[32] = {0};
	char 	res_buf[512] = {0};
	INT16 	cell_select_cfg_len = 0;
	int32 	tmp_val = 0;
	UINT32  reqHandle = 0;
	CiDevPrimSetCellSelectCfgReq pSetCellSelectCfgReq = {0}; 

	RETURNCODE_T ret = utlSUCCESS; 
	
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32 atHandle = MAKE_AT_HANDLE( sAtpIndex );
	*xid_p = atHandle;
	
	param_num = quec_get_at_param_num(parameter_values_p,num_parameters);
	atcmd_general_log("[quec cell select cfg] param_num=%d,command type=%d,atHandle=%d",param_num,op,atHandle);

	switch (op)
	{
		case TEL_EXT_SET_CMD:
		{
			if (2 != param_num)
			{
				atcmd_general_log("[quec cell select cfg] param number mismatch,param_num=%d",param_num);
				ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_ILLEGAL_OPERATION, NULL);
			}
			else 
			{
				if (FALSE == getExtString(parameter_values_p, 0, cell_select_cfg_cmd_str, 32, &cell_select_cfg_len, NULL))
				{
					atcmd_general_log("[quec cell select cfg] param error,jdcfg_cmd_str=%s",cell_select_cfg_cmd_str);
					ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
				}
				else 
				{
					for (cmd_index = SCELL_OFFSET; cmd_index < CELL_SELECT_ENUM_MAX; cmd_index++)
					{
						if (0 == strcasecmp(cell_select_cfg_cmd_str,cell_select_cfg[cmd_index].cmd_str))
						{
							memset(cell_select_cfg_cmd_str,0,sizeof(cell_select_cfg_cmd_str));
							if ( FALSE == getExtString(parameter_values_p, 1, cell_select_cfg_cmd_str,32, &cell_select_cfg_len, NULL) )
							{
								atcmd_general_log("[quec cell select cfg] param error,cell_select_cfg_cmd_str=%s",cell_select_cfg_cmd_str);
								ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
								ret = HANDLE_RETURN_VALUE(ret);
								return(ret);
							}
							else 
							{
								atcmd_general_log("[quec cell select cfg] cell_select_cfg_cmd_str=%s",cell_select_cfg_cmd_str);
								if(FALSE == str2int32(cell_select_cfg_cmd_str, 3, &tmp_val))
								{
									atcmd_general_log("[quec cell select cfg] cmd_index=%d,tmp_val=%d",cmd_index,tmp_val);
									ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
									ret = HANDLE_RETURN_VALUE(ret);
									return(ret);
								}
								if (FALSE == quec_vaild_cell_select_cfg_val(cmd_index,tmp_val))
								{
									atcmd_general_log("[quec cell select cfg] cmd_index=%d,tmp_val=%d",cmd_index,tmp_val);
									ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
									ret = HANDLE_RETURN_VALUE(ret);
									return(ret);
								}
								cell_select_cfg[cmd_index].val = tmp_val;
								memset(&pSetCellSelectCfgReq,0,sizeof(CiDevPrimSetCellSelectCfgReq));
								pSetCellSelectCfgReq.offset_scell 		    = 	cell_select_cfg[SCELL_OFFSET].val;
								pSetCellSelectCfgReq.offset_scell_qual 	 	= 	cell_select_cfg[SCELL_QUAL_OFFSET].val;
								pSetCellSelectCfgReq.offset_ncell_lte 		= 	cell_select_cfg[NCELL_LTE_OFFSET].val;
								pSetCellSelectCfgReq.offset_ncell_lte_qual  = 	cell_select_cfg[NCELL_LTE_QUAL_OFFSET].val;
								pSetCellSelectCfgReq.offset_ncell_umts 	 	= 	cell_select_cfg[NCELL_UMTS_OFFSET].val;
								pSetCellSelectCfgReq.offset_ncell_umts_qual = 	cell_select_cfg[NCELL_UMTS_QUAL_OFFSET].val;
								pSetCellSelectCfgReq.offset_ncell_gsm 	    = 	cell_select_cfg[NCELL_GSM_OFFSET].val;
								ret = DEV_SetCellSelectOffset(atHandle,&pSetCellSelectCfgReq);
							}
							break;
						}
					}
					if (cmd_index >= CELL_SELECT_ENUM_MAX)
					{
						atcmd_general_log("[quec cell select cfg]index(%d) >= CELL_SELECT_ENUM_MAX(%d)",cmd_index,CELL_SELECT_ENUM_MAX);
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						ret = HANDLE_RETURN_VALUE(ret);
						return(ret);
					}
				}
			}
			break;
		}
		
		case TEL_EXT_GET_CMD:
		{
			ret = DEV_CellSelectOffset_req(atHandle);
		}
		break;

		case TEL_EXT_TEST_CMD:
		{
			quec_siolib_transmit_to_atp(*(TelAtParserID*)arg_p, "\r\n", 2, NULL);
			for (cmd_index = SCELL_OFFSET; cmd_index < CELL_SELECT_ENUM_MAX; cmd_index++)
			{
				resp_len = 0;
				memset(res_buf,0,sizeof(res_buf));
				resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QCELLSELECTCFG: \"%s\",(%d~%d)\r\n",
                					cell_select_cfg[cmd_index].cmd_str,
                					cell_select_cfg[cmd_index].minval,
                					cell_select_cfg[cmd_index].maxval);
				ret = quec_siolib_transmit_to_atp(sAtpIndex, (uint8*)res_buf, resp_len, NULL);
			}
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            atcmd_general_log("[quec cell select cfg] ret = %d",ret);
		}
		break;

		default:
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			break;
		}
	}
	/* handle the return value */
	ret = HANDLE_RETURN_VALUE(ret);
	return(ret);
}
#endif

