int32 g_qcellex = 0;  /* 启用/禁用 缓存机制 */
char quec_cellex_info_buf[QUEC_CELLEX_INFO_MAX_LEN+1] = {0};

void quec_set_qcellex(int32 val)
{
    g_qcellex = val;
    return;
}

int32 quec_get_qcellex(void)
{
    return g_qcellex;
}

QuecOSStatus quec_update_cellex_info(void)
{
    QuecOSStatus err = kNoErr;
    int ret = 0;

    if (1 == quec_get_qcellex())
    {
        ret = SendATCMDWaitResp(TEL_AT_CMD_ATP_QUEC_INTERNAL, "AT+QCELL?\r\n", 1, NULL, 1, NULL, NULL, 0);
    }
    else if (1 == quec_get_qcellinfo())
    {
        ret = SendATCMDWaitResp(TEL_AT_CMD_ATP_QUEC_INTERNAL, "AT+QCELLINFOEX?\r\n", 1, NULL, 1, NULL, NULL, 0);
    }
    else 
    {
        atcmd_general_log("qcellex: update cellinfo disable!!!");
    }
    
    if (ret != 0)
    {
        atcmd_general_log("qcellex: send at+qcell? error!!!");
        err = kGeneralErr;
    }
    return err;
}

void quec_qeng_cellex_info_max_limited(char *qeng_buff , UINT32 buff_len)
{
	UINT8 couter = 0;
	char *qeng_p = NULL;
	char *qeng_next_p = NULL;
	UINT8 offset = 0;
    
	atcmd_general_log("qcellex: enter len:%d", buff_len);
	if((NULL == qeng_buff)||(0 == buff_len))
	{
		return;
	}
    offset = strlen("MCC:");
	qeng_next_p = qeng_buff;
    do
	{
		qeng_p = strstr(qeng_next_p,"MCC:");
		if(NULL == qeng_p) 
        {
            break;
        }
        qeng_next_p = strstr(qeng_p+offset,"MCC:");
        if(NULL == qeng_next_p) 
        {
            break;
        }
		couter++;
    }while(couter < (QUEC_CELLEX_INFO_MAX_NUM + 1));

    if(couter == (QUEC_CELLEX_INFO_MAX_NUM + 1))
	{
		 atcmd_general_log("qcellex: clear cellinfo, need len:%d buffer_p=[%p] qeng_p=[%p]", qeng_p-qeng_buff, qeng_buff, qeng_p);
		 memset(qeng_p,0,buff_len - (qeng_p-qeng_buff));
	}
    return;
}


RETURNCODE_T  quec_cellex_cmd
(
        const utlAtParameterOp_T      op,
        const char                   *command_name_p,
        const utlAtParameterValue_P2c parameter_values_p,
        const size_t                  num_parameters,
        const char                   *info_text_p,
        unsigned int                 *xid_p,
        void                         *arg_p
)
{
    RETURNCODE_T ret = utlSUCCESS;
	int     atpIndex = 0;
    char    res_buf[32] = {0};
	UINT32  atHandle = MAKE_AT_HANDLE(*(TelAtParserID*)arg_p);
    UINT8   param_num = 0;
    int32   qcellex_tmp = 0;
    
	*xid_p = atHandle;
    atpIndex = GET_ATP_INDEX(atHandle);
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);
    memset(res_buf,0,sizeof(res_buf));
    
    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
	switch (op)
    {
        case TEL_EXT_TEST_CMD:
        	{
    			ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0,"+QCELLEX: (0,1)\r\n");
        	}
    		break;
    	case TEL_EXT_GET_CMD:
    		{  
                sprintf(res_buf, "+QCELLEX: %d", g_qcellex);
    		    ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
    		}
    		break;
        case TEL_EXT_SET_CMD:
            {
                if (1 == param_num)
                {
                    if (TRUE != getExtValue(parameter_values_p, 0, &qcellex_tmp, 0, 1, 0))
                    {
                        ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
                        atcmd_general_log("qcellex: get qcellex cfg %d failed",qcellex_tmp);
                        break;
                    }
                    atcmd_general_log("qcellex: qcellex  %d",qcellex_tmp);
                    if ((qcellex_tmp < 0) || (qcellex_tmp > 1))
                    {
                        ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
                        break;
                    }
#ifdef QUEC_QCELLINFO_SUPPORT
                    if ((1 == qcellex_tmp) && (1 == quec_get_qcellinfo()))
                    {
                        quec_set_qcellinfo(0);
                    }
#endif
                    quec_set_qcellex(qcellex_tmp);
                    ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, quec_cellex_info_buf);
                }
                else 
                {
                    ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
                }
            }
            break;
    	default:
    		{
    			ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
            }
    		break;	
	}
	
	return ret;
}

#endif

// amos 2020.10.16 add for IS0001514 disable or enable flash erase count
#ifdef QUEC_AT_FLASH_ERASE_COUNT_CMD
RETURNCODE_T quectel_exec_qerasecount_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */
    void                           *arg_p               /* AT cmd parser number */
)
{
	RETURNCODE_T	 rc 	  = INITIAL_RETURN_CODE;
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
	UINT32 atHandle = MAKE_AT_HANDLE( sAtpIndex );
	RETURNCODE_T ret = CIRC_SUCCESS;
	char  res_buf[32] = {0};
	UINT32 set_count_flag;
	UINT8 tmp_flag = 0;

	*xid_p = atHandle;

	switch (op)
	{
		case TEL_EXT_SET_CMD:
		{
			if ((getExtValue(parameter_values_p,
				0,
				&set_count_flag,
				0,
				1,
				0) == TRUE))
            {
            	if (QUEC_FAT_SUCCESS != quectel_nv_fat_read(QUEC_FLASH_ERASE_COUNT_FLAG, &tmp_flag, sizeof(tmp_flag)))
				{
					atcmd_general_log("quectel_nv_fat_read qcfg_eraseflashcount failed\n");
				}
				if(tmp_flag == set_count_flag){
					ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				} else {
					if(set_count_flag == 1){
						tmp_flag = 1;
						if(quectel_nv_fat_write(QUEC_FLASH_ERASE_COUNT_FLAG, &tmp_flag, sizeof(tmp_flag))==QUEC_FAT_SUCCESS)
						{
							if(g_FlashBlkEraseCnt == NULL) {
								g_FlashBlkEraseCnt = (UINT16 *)malloc(nvm_bin_size/CHIP_SECTOR_SIZE * 2);
								if(g_FlashBlkEraseCnt == NULL) {
									qcfg_eraseflashcount = 0;
									atcmd_general_log("g_FlashBlkEraseCnt malloc failed\n");
									ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
									break;
								}else {
									atcmd_general_log("malloc size %d\n",nvm_bin_size/CHIP_SECTOR_SIZE * 2);
									memset(g_FlashBlkEraseCnt, 0, nvm_bin_size/CHIP_SECTOR_SIZE * 2);
									qcfg_eraseflashcount = 1;
								}
							}
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);

						} else {
							atcmd_general_log("save_to_nv ERROR");
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						}

					} else if(set_count_flag == 0) {
						tmp_flag = 0;
						if(quectel_nv_fat_write(QUEC_FLASH_ERASE_COUNT_FLAG, &tmp_flag, sizeof(tmp_flag))==QUEC_FAT_SUCCESS)
						{
							if(g_FlashBlkEraseCnt != NULL) {
								free(g_FlashBlkEraseCnt);
								g_FlashBlkEraseCnt = NULL;
								qcfg_eraseflashcount = 0;
								extern UINT16 g_FlashBlkEraseTotal;
								g_FlashBlkEraseTotal = 0;
							}
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
						} else {
							atcmd_general_log("save_to_nv ERROR");
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						}
					} else {
						ret = ATRESP( atHandle,ATCI_RESULT_CODE_CME_ERROR,CME_INVALID_PARAM,NULL);
					}
				}
			}

            break;

		}
		case TEL_EXT_TEST_CMD:
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, "+QERASECOUNT: (0,1)\r\n");
			break;
		case TEL_EXT_GET_CMD:
			if (QUEC_FAT_SUCCESS != quectel_nv_fat_read(QUEC_FLASH_ERASE_COUNT_FLAG, &tmp_flag, sizeof(tmp_flag)))
			{
				atcmd_general_log("quectel_nv_fat_read qcfg_eraseflashcount failed\n");
			}
			sprintf(res_buf, "+QERASECOUNT: %d", tmp_flag);
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
			break;
		default:
            atcmd_general_log("command type error: %d", op);
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, NULL, NULL);
			break;
	}

	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return(rc);

}

#endif

#if QUEC_CEER_ESM_REJECT_CAUSE_SUPPORT
UINT8 quec_err_cause_mode = QUEC_ERR_CAUSE_MODE_DEFAULT;
char quec_err_cause[QUEC_ERR_CAUSE_LEN] = {0};

RETURNCODE_T  quec_exec_qceer_report
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
	UNUSEDPARAM(command_name_p)
	UNUSEDPARAM(info_text_p)
	
	RETURNCODE_T rc = INITIAL_RETURN_CODE;
	CiReturnCode ret = CIRC_FAIL;
	UINT32 atHandle = MAKE_AT_HANDLE(*(TelAtParserID*)arg_p);
    *xid_p = atHandle;

    char tmpBuf[256] = {0};
	char *pErrCauseBuf = quec_err_cause;
	UINT8   param_num = quec_get_at_param_num(parameter_values_p,num_parameters);
	int   mode = 0;

	switch(op)
	{
		case TEL_EXT_SET_CMD:       /* AT+QCEER= */
            if(param_num == 0)
            {
                memset(tmpBuf,0,sizeof(tmpBuf));
                if(strlen(pErrCauseBuf) == 0){
                    strcpy(pErrCauseBuf, "No report available");
                }
				sprintf(tmpBuf, "+QCEER: %s\r\n", pErrCauseBuf);

				//cause cache clear.
				if(quec_err_cause_mode & (1 << 1)){
					quec_set_clear_err_cause();
				}
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, tmpBuf);
				break;
            }

			if(param_num > 1){
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL );
				break;
			}
			if((getExtValue(parameter_values_p, 0, &mode, QUEC_ERR_CAUSE_MODE_DEFAULT, QUEC_ERR_CAUSE_CONFIG_MAX-1, QUEC_ERR_CAUSE_MODE_DEFAULT) == TRUE)){
				quec_err_cause_mode = mode;
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
			}else{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_UNKNOWN, NULL );
			}
			break;
		case TEL_EXT_GET_CMD:       /* AT+QCEER?  */
			{
				char tmpBuf[300] = {0};
				memset(tmpBuf,0,sizeof(tmpBuf));
				sprintf(tmpBuf, "+QCEER: %d\r\n", quec_err_cause_mode);
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, tmpBuf);
				break;
			}
		default:
			{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL );
				break;
			}
	}

	rc = HANDLE_RETURN_VALUE(ret);
	return(rc);

}

BOOL quec_get_err_cause_urc_en(void)
{
	return (quec_err_cause_mode & (1 << 0));
}

void quec_set_clear_err_cause(void)
{
	char *p_cause = quec_err_cause;
	memset(p_cause, 0, sizeof(QUEC_ERR_CAUSE_LEN));
	sprintf(p_cause,"No report available");
}
#endif /*QUEC_CEER_ESM_REJECT_CAUSE_SUPPORT*/

uint8 is_qcfg_addehplmn=0;
void quec_set_is_qcfg_addehplmn_value(uint8 value)
{
	is_qcfg_addehplmn=value;
}
uint8 quec_get_is_qcfg_addehplmn_value(void)
{
	return is_qcfg_addehplmn;
}

RETURNCODE_T quectel_exec_qcfg_addehplmn_cmd
(
	const utlAtParameterOp_T		 op,				 /* AT cmd type 		 */
	const char 					*command_name_p,	 /* AT cmd name 		 */
	const utlAtParameterValue_P2c	 parameter_values_p, /* AT cmd value		 */  
	const size_t					 num_parameters,	 /* AT cmd number		 */
	const char 					*info_text_p,		 /* AT cmd usage string  */
	unsigned int					*xid_p, 			 /* AT cmd handle		 */   
	void							*arg_p				 /* AT cmd parser number */
)
{
	RETURNCODE_T	 rc 	  = INITIAL_RETURN_CODE;
	CiReturnCode	 ret	  = CIRC_FAIL;
	UINT32 atHandle  =*xid_p ;	
	int cmd = 0;//0-set 1-delete	
	char  qcfg_cmd_str[20] = {0};
	INT16 qcfg_cmd_str_len=0;
	CHAR qcfg_data_str[500 + ATCI_NULL_TERMINATOR_LENGTH];
	INT16 qcfg_data_str_len=0;
	UINT8 param_num=0;
	UINT8 i=0;
	UINT32 index  = *(TelAtParserID *)arg_p;
	char res_buf[100]={0};
	
	param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

	switch (op)
	{
		case TEL_EXT_SET_CMD://at+qcfg="addehplmn",<mode>,<string>
		{	
			if(param_num==1) //at+qcfg="addehplmn" query all	
			{
				quec_set_is_qcfg_addehplmn_value(1);
				ret = Dev_GetComFeature(atHandle, (UINT16)CI_DEV_FT_EHPLMN, 65535);
				break;
			}
			else if(param_num > 1 && param_num <= 3)  //at+qcfg="addehplmn",<mode> mode 1-delete
			{
				if ((getExtString(parameter_values_p, 1, qcfg_cmd_str, sizeof(qcfg_cmd_str), &qcfg_cmd_str_len, NULL) == FALSE))
				{
					atcmd_general_log("qcfg addehplmn cmd param error");
					ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
					rc = HANDLE_RETURN_VALUE(ret);
					return(rc);
				}
				else
				{
					if(str2int32(qcfg_cmd_str, 2, &cmd)==FALSE) //check if the num is large than 10
					{
						atcmd_general_log("qcfg addehplmn cmd string to int32 fail");
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						rc = HANDLE_RETURN_VALUE(ret);
						return(rc);
					}
				}				
				if(param_num == 3)	//at+qcfg="addehplmn",<mode>,<string> mode:0-set 1-delete
				{						
					if ((getExtString(parameter_values_p, 2, qcfg_data_str, sizeof(qcfg_data_str), &qcfg_data_str_len, NULL) == FALSE))
					{
						atcmd_general_log("qcfg addehplmn data error");
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						rc = HANDLE_RETURN_VALUE(ret);
						return(rc);
					}
				}
				ret = Dev_SetComFeature(atHandle, (UINT8)cmd, (UINT16)CI_DEV_FT_EHPLMN, qcfg_data_str);
				break;
			}
			else
			{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
				break;
			}
		}
		case TEL_EXT_TEST_CMD:	  /* AT+QCFG=? */
		{
			strcpy(res_buf, "+QCFG: \"addehplmn\",<mode>,<string>\r\n");
			ret=quec_siolib_transmit_to_atp((TelAtParserID)index,(uint8 *)res_buf,strlen(res_buf), NULL);
			break;
		}
		default:
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			break;
		}

	}
   /* handle the return value */
   rc = HANDLE_RETURN_VALUE(ret);
   return(rc);
}

