#ifdef QUEC_CDMA_IMSI_SUPPORT

RETURNCODE_T quec_exec_qcdma_imsi_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                      *command_name_p,    /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                      *info_text_p,       /* AT cmd usage string  */
    unsigned int                    *xid_p,             /* AT cmd handle        */
    void                            *arg_p              /* AT cmd parser number */
)
{
    UNUSEDPARAM(command_name_p);
    UNUSEDPARAM(num_parameters);
    UNUSEDPARAM(info_text_p);
    /*
     **  Set the result code to INITIAL_RETURN_CODE.  This allows
     **  the indications to display the correct return code after the
     **  AT Command is issued.
     */
    RETURNCODE_T       rc = INITIAL_RETURN_CODE;
    CiReturnCode       ret = CIRC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;
    _AtciResultCode status;
    //Put parser index into the variable
    TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32        atHandle  = MAKE_AT_HANDLE(sAtpIndex);
    int ipr_value;
    *xid_p = atHandle;

    char resp[20]={0};
    char resp_len=0;
    uint8 cdma_imsi = 0;
    switch (op)
    {
        case TEL_EXT_TEST_CMD:  /* AT+IPR=? */
        {
            atcmd_general_log("CDMA_IMSI not support");    
            break;
        }
        case TEL_EXT_SET_CMD:     /* AT+IPR= X */
        {
            if ((getExtValue(parameter_values_p,
                             0,
                             &cdma_imsi,
                             0,
                             1,
                             0) == TRUE))
            {
                if((TRUE != cdma_imsi)&&(FALSE != cdma_imsi))
                {
                       status=ATCI_RESULT_CODE_ERROR;
                       atcmd_general_log("CDMA_IMSI value not invalid",cdma_imsi);    
                }
                else
                {
                       atcmd_general_log("CDMA_IMSI set %d", cdma_imsi);
                       status = ATCI_RESULT_CODE_OK;
                       quec_cdma_imsi.flag = cdma_imsi;
                       if(TRUE == cdma_imsi)
                       {
                         quec_send_msg_to_handle_task(QUEC_CDMA_IMSI_MSG, NULL, QUEC_MSG_LEN_NONE);
                       }
                }
            }
           else
           {
		   	 atcmd_general_log("CDMA_IMSI fail=%d", cdma_imsi);
             status=ATCI_RESULT_CODE_ERROR;
           }
            ret = ATRESP( atHandle, status, 0, NULL );
            break;
        }
        case TEL_EXT_GET_CMD:

            resp_len=snprintf(resp,sizeof(resp)-1,"+QCDMAIMSI: %d\r\n",quec_cdma_imsi.flag);
            atcmd_general_log("qsclk cmd ,resp_len=%d",resp_len);
            if(resp_len!=0)
            {
               ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, resp);
            }
            else
            {
               ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
            }
        
        break;
        default:                /* default handle */
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
            break;
        }
    }
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

#endif

#ifdef QUEC_ASR_ATCMD_PAGING_UPDATE_SUPPORT
extern quec_pg_keepalive_cfg pg_cfg;
extern int  quec_set_nc_kalive(qeuc_tcpip_nc_kalive_opt    		*opt_val);
RETURNCODE_T  quec_exec_qpagupdate_cmd
(
	const utlAtParameterOp_T	   op,				  /* AT cmd type		  */
	const char					  *command_name_p,	  /* AT cmd name		  */
	const utlAtParameterValue_P2c  parameter_values_p,/* AT cmd value		  */	
	const size_t				   num_parameters,	  /* AT cmd number		  */
	const char					  *info_text_p, 	  /* AT cmd usage string  */
	unsigned int				  *xid_p,			  /* AT cmd handle		  */	
	void						  *arg_p			  /* AT cmd parser number */
)
{
	RETURNCODE_T ret = utlSUCCESS;
    char buf[64] = {0};
    INT16 buf_len =0;
	UINT8 validCmd = TRUE;	
    static BOOL binitFlag = FALSE;
	UINT32 atHandle = MAKE_AT_HANDLE(*(TelAtParserID*)arg_p);
    qeuc_tcpip_nc_kalive_opt    nc_kalive_val       = {0};

	*xid_p = atHandle;


	switch (op)
    {
    	case TEL_EXT_TEST_CMD:    /* AT+QPAGUPDATE=? */
    	{
    		buf_len =0;
            
		    buf_len += snprintf(buf, 64, "+QPAGUPDATE: (0-1),(0-1),(0-1),<TIME>\r\n");
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, buf);
    	}
		break;
	
		case TEL_EXT_GET_CMD:	/* AT+QPAGUPDATE? */
		{
			buf_len =0;
			buf_len += snprintf(buf, 64, "+QPAGUPDATE: %d,%d,%d,%d,%llu\r\n",
            pg_cfg.paging_update_enable, pg_cfg.keep_type, pg_cfg.keep_pkt_type, pg_cfg.keep_time,pg_cfg.pkt_send_times);
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, buf);
		}
		break;
	
    	case TEL_EXT_SET_CMD:    /* AT+QPAGUPDATE=...  */
       	{
		   UINT8   arg_cnt=0;
		   UINT8   arg_index = 0;

		   arg_cnt = quec_get_at_param_num(parameter_values_p,num_parameters);

		   while((arg_index < arg_cnt)&&validCmd)
		   {
		   		switch(arg_index)
		   		{
					case 0: // enable/disable
						{
							int paging_update_enable = 0;
							if( getExtValue( parameter_values_p, 0, &paging_update_enable, 0, 1, 1) == FALSE )
                            {
                                validCmd = FALSE;
                            } 
                            else 
                            {
                                pg_cfg.paging_update_enable = paging_update_enable;
                            }
                            
						}
						break;

					case 1: //keep_type
						{
							int keep_type = 0;
							if( getExtValue( parameter_values_p, 1, &keep_type, PAGING_KEEP_CELL_RESELECT_SEND, PAGING_KEEP_NORMAL_SEND, 0) == FALSE ){
								validCmd = FALSE;
							}
							else
                            {
								pg_cfg.keep_type = keep_type;
							}
						}
						break;
					
					case 2: //keep_pkt_type
						{
							int keep_pkt_type = 0;
							if( getExtValue( parameter_values_p, 2, &keep_pkt_type, PAGING_KEEP_SEND_UDP_PKT, PAGING_KEEP_SEND_PING_PKT, 0) == FALSE ){
								validCmd = FALSE;
							}
							else{
								pg_cfg.keep_pkt_type = keep_pkt_type;
							}
						}
						break;
					
					case 3: //keep_time
						{
							int keep_time = 0;
							if( getExtValue( parameter_values_p, 3, &keep_time, 1, 65535, 0) == FALSE ){
								validCmd = FALSE;
							}
							else
                            {
                                //quec_pg_reg_ind_debounce_timer_stop();
								pg_cfg.keep_time = keep_time;
							}
						}
						break;
					default:
						validCmd = FALSE;
						break;
		   		}
				arg_index++;
		   }
           if(validCmd)
           {
               if(TRUE == pg_cfg.paging_update_enable)
               {
                   if(FALSE == binitFlag)
                   {
                       quec_paging_keepalive_init();
                       binitFlag = TRUE;
                   }
                   if(PAGING_KEEP_NORMAL_SEND == pg_cfg.keep_type)
                   {
                       //pg_cfg.pkt_send_times = 0;
                       quec_get_nc_kalive(&nc_kalive_val);
                       nc_kalive_val.pdp_cid          = 1;
                       nc_kalive_val.idle_time = pg_cfg.keep_time;
                       nc_kalive_val.keepalive_enable = 1;
                       quec_set_nc_kalive(&nc_kalive_val);
                   }
               }
               else 
               {
                   pg_cfg.pkt_send_times = 0;
                   if(PAGING_KEEP_NORMAL_SEND == pg_cfg.keep_type)
                   {
                       quec_get_nc_kalive(&nc_kalive_val);
                       nc_kalive_val.keepalive_enable = 0;
                       quec_set_nc_kalive(&nc_kalive_val);
                   }                   
               }
               ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
           }
           else 
           {
               ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
           }
    	}
		break;  
	
    	default:
        {	
			ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
        }
		break;
    }

	return ret;
}
#endif

