#ifdef QUECTEL_AT_QCFG_SUPPORT
bool gqcfg_mifi_link_flag = FALSE;

void quec_set_qcfg_mifi_link_flag(bool set_value)
{
    gqcfg_mifi_link_flag = set_value;
}

void quec_get_qcfg_mifi_link_flag(bool *get_value)
{
    *get_value = gqcfg_mifi_link_flag;
}

RETURNCODE_T  quectel_exec_qcfg_mifilink_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    int              type;
    UINT32  index;
    //UINT32           atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);

    UINT32 atHandle =      *xid_p;
    index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    char res_buf[100]={0};
    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len=0;
    bool get_value = FALSE;
    INT set_value = 0;
    UINT8 resp_len=0;
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QCFG="mifilink",..  */
            {

                if(param_num==1)
                {
                    quec_get_qcfg_mifi_link_flag(&get_value);
                    atcmd_general_log("get mifi link value=%d",get_value);
                    resp_len = snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"mifilink\",%d\r\n",get_value);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                }
                else if(param_num==2)
                {
                    if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE))
                    {
                         if(str2int32(cfg_cmd_param_str,1,&set_value))  //check if the num is large than 10
                         {
                             atcmd_general_log(" qcfg mifi link value=%d",set_value);
                             if(QUEC_QCFG_MIFI_LINK_DOWN == set_value)
                             {
                                 quec_set_qcfg_mifi_link_flag(FALSE);
                                 ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, 0);
                             }
                             else if(QUEC_QCFG_MIFI_LINK_UP == set_value)
                             {
                                 quec_set_qcfg_mifi_link_flag(TRUE);
                                 ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, 0);
                             }
                             else 
                             {
                                 ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                             }
                         }
                         else
                         {
                            ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                         }
                    }
                    else
                    {
                         ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                    }
                }
                else
                {
                     ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
                }
                break;
            }

        case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
            {

                resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"mifilink\",(%d,%d)\r\n",\
                    QUEC_QCFG_MIFI_LINK_DOWN,QUEC_QCFG_MIFI_LINK_UP);
                ret=quec_siolib_transmit_to_atp(index,res_buf,resp_len,NULL);
                break;
            }
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

typedef struct 
{
	int arp_tmr;    // arp request period        (ARP_TMR_INTERVAL * arp_tmr = 20*x)s in mifi mode
	int nat_tmr;    // nat record ttl            (2min * nat_tmr)  MAX:30 = 1h;
	int bridge_tmr; // netif bridge record ttl   (2min * nat_tmr)  MAX:30 = 1h;
	
}quec_mifi_tmr_ctrl_s;

typedef enum
{
	QUEC_MIFI_TMR_ARP_TYPE = 0,
	QUEC_MIFI_TMR_NAT_TYPE,
	QUEC_MIFI_TMR_BRIDGE_TYPE,
	
	QUEC_MIFI_TMR_TYPE_MAX,
}quec_mifi_tmr_type;

#define QUEC_MIFI_TMR_INVALID_CNT     (-1)
#define QUEC_MIFI_TMR_ARP_MAX_CNT     (30)    //10min MAX
#define QUEC_MIFI_TMR_NAT_MAX_CNT     (30)
#define QUEC_MIFI_TMR_BRIDGE_MAX_CNT  (30)


static quec_mifi_tmr_ctrl_s g_mifi_tmr_cfg =
{
	.arp_tmr = 1,
	.nat_tmr = 1,
	.bridge_tmr = 1
};

int quec_set_qcfg_mifi_tmr_cnt(int        type, int set_value)
{
	int ret = kNoErr;
	int valid_value = 0;
	quec_mifi_tmr_ctrl_s *p_tmr_cfg = &g_mifi_tmr_cfg;

	switch (type)
	{
		case QUEC_MIFI_TMR_ARP_TYPE:
		{
			valid_value = (set_value > 0 && set_value <= QUEC_MIFI_TMR_ARP_MAX_CNT)?(set_value):(QUEC_MIFI_TMR_INVALID_CNT);
			if(valid_value == QUEC_MIFI_TMR_INVALID_CNT){
				ret = kGeneralErr;
				//p_tmr_cfg->arp_tmr = 1;
			}else{
				p_tmr_cfg->arp_tmr = valid_value;
			}
			break;
		}
		case QUEC_MIFI_TMR_NAT_TYPE:
		{
			valid_value = (set_value > 0 && set_value <= QUEC_MIFI_TMR_NAT_MAX_CNT)?(set_value):(QUEC_MIFI_TMR_INVALID_CNT);
			if(valid_value == QUEC_MIFI_TMR_INVALID_CNT){
				ret = kGeneralErr;
			}else{
				p_tmr_cfg->nat_tmr = valid_value;
			}
			break;
		}
		case QUEC_MIFI_TMR_BRIDGE_TYPE:
		{
			valid_value = (set_value > 0 && set_value <= QUEC_MIFI_TMR_BRIDGE_MAX_CNT)?(set_value):(QUEC_MIFI_TMR_INVALID_CNT);
			if(valid_value == QUEC_MIFI_TMR_INVALID_CNT){
				ret = kGeneralErr;
			}else{
				p_tmr_cfg->bridge_tmr = valid_value;
			}
			break;
		}
		default:
		{
			ret = kGeneralErr;
		}
	}


	return ret;
	
}

int quec_get_qcfg_mifi_tmr_cnt(int        type, int *get_value)
{
	int ret = kNoErr;
	quec_mifi_tmr_ctrl_s *p_tmr_cfg = &g_mifi_tmr_cfg;

	switch (type)
	{
		case QUEC_MIFI_TMR_ARP_TYPE:
		{
			*get_value = p_tmr_cfg->arp_tmr;
			break;
		}
		case QUEC_MIFI_TMR_NAT_TYPE:
		{
			*get_value = p_tmr_cfg->nat_tmr;
			break;
		}
		case QUEC_MIFI_TMR_BRIDGE_TYPE:
		{
			*get_value = p_tmr_cfg->bridge_tmr;
			break;
		}
		default:
		{
			ret = kGeneralErr;
		}
	}

	return ret;

}

RETURNCODE_T  quectel_exec_qcfg_mifi_tmr_cmd
(
     const utlAtParameterOp_T        op,                    /* AT cmd type                  */
     const char                     *command_name_p,        /* AT cmd name                  */
     const utlAtParameterValue_P2c   parameter_values_p,    /* AT cmd value                 */
     const size_t                    num_parameters,        /* AT cmd number                */
     const char                     *info_text_p,           /* AT cmd usage string          */
     unsigned int                   *xid_p,                 /* AT cmd handle                */
     void                           *arg_p              /* AT cmd parser number         */
)
{
	RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
	CiReturnCode     ret      = CIRC_FAIL;
	QuecOSStatus status=QUEC_SUCCESS;
	int              type;
	UINT32  index;

	UINT32 atHandle =      *xid_p;
	index  = *(TelAtParserID *)arg_p;
	UINT8 param_num = 0;
	char res_buf[100]={0};
	char  cfg_cmd_param_str[20] = {0};
	INT16 cfg_cmd_param_str_len=0;

	int type_value = 0;
	int tmr_value  = 0;
	UINT8 is_valid = false;
	UINT8 resp_len=0;
	memset(res_buf, 0, sizeof(res_buf));
	memset(cfg_cmd_param_str, 0, sizeof(cfg_cmd_param_str));
	param_num = quec_get_at_param_num(parameter_values_p,num_parameters);

	atcmd_general_log("command type=%d,param_num=%d",op,param_num);
	switch (op)
	{
		case TEL_EXT_SET_CMD:    /* AT+QCFG="mifi/tmr",..  */
		{
			if(param_num == 2)   //query
			{
				if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE)){
					if(str2int32(cfg_cmd_param_str, 1, &type_value)){  //0-9
						ret = quec_get_qcfg_mifi_tmr_cnt(type_value,&tmr_value);
						if(ret == kNoErr){
							atcmd_general_log("get mifi tmr %d value=%d",type_value,tmr_value);
							resp_len = snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"mifi/tmr\",%d,%d\r\n", type_value, tmr_value);
							ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
							break;
						}
					}
				}
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
			}
			else if(param_num == 3) //set
			{
				if ((getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE)){
					if(str2int32(cfg_cmd_param_str,1,&type_value)){
						is_valid = true;
					}else{
						is_valid = false;
					}
				}
				if ((is_valid == true) && (getExtString(parameter_values_p, 2, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE)){
					if(str2int32(cfg_cmd_param_str,3,&tmr_value)){//0-999
						is_valid = true;
					}else{
						is_valid = false;
					}
				}
				if(is_valid == true){
					atcmd_general_log("set mifi tmr %d value=%d",type_value, tmr_value);
					ret = quec_set_qcfg_mifi_tmr_cnt(type_value, tmr_value);
					if(ret == kNoErr){
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
						break;
					}
				}
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
			}
			else
			{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
			}
			break;
		}

		case TEL_EXT_TEST_CMD:    /* AT+QCFG=? */
		{
			resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QCFG: \"mifi/tmr\",(%d-%d),<value>\r\n", QUEC_MIFI_TMR_ARP_TYPE,QUEC_MIFI_TMR_TYPE_MAX-1);
			ret=quec_siolib_transmit_to_atp((TelAtParserID)index,(uint8 *)res_buf,resp_len,NULL);
			break;
		}
		default:
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
			break;
		}

	}

	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return(rc);
}


#endif


