void quec_electric_fence_delete_all_blackcell(void)
{
	int i=0;
	int ret=0;

	quec_get_fence_black_cell_num();
	if(g_quec_electric_fence_list.blackcell_num == 0)
	{
		atcmd_general_log("quec_electric_fence_delete_all_blackcell:no blackcell"); 
	}
	else 
	{
		for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
		{
			if(g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
			{
				memset(&g_quec_electric_fence_list.blackcellid_list[i], 0, sizeof(g_quec_electric_fence_list.blackcellid_list[i]));
			}
		}
		g_quec_electric_fence_list.blackcell_num = 0;
		
		ret = quectel_nv_fat_write(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list, sizeof(g_quec_electric_fence_list));
		if (ret != QUEC_SUCCESS)
		{
			atcmd_general_log("quec_electric_fence_delete_all_blackcell:quec_electric_fence_config write failed"); 
		}
	}	
}

void quec_electric_fence_send_event_msg(int event)
{
	if((g_quec_electric_fence_list.blackcell_num == 0) && (event != POWERDOWN_EVENT))
	{
		atcmd_general_log("quec_electric_fence_send_event_msg: no blackcell");
		return;
	}
	atcmd_general_log("quec_electric_fence_send_event_msg: event %d",event);
	quec_send_msg_to_handle_task(QUEC_ELECTRIC_FENCE_EVENT_MSG, (char *)&event, sizeof(int));
}

void quec_electric_fence_send_prevent_event_msg(int prevent_event)
{
	if((prevent_event < QUEC_BLACKCELL_REGISTER_SUCCESS) || (prevent_event > QUEC_BLACKCELL_PREVENT_TIMEOUT))
	{
		atcmd_general_log("quec_electric_fence_send_prevent_event_msg: invaild prevent_event");
		return;
	}

	if(g_quec_electric_fence_list.blackcell_num == 0)
	{
		atcmd_general_log("quec_electric_fence_send_prevent_event_msg: no blackcell, do not send prevent_event_msg");
		return;
	}
	
	atcmd_general_log("quec_electric_fence_send_prevent_event_msg: prevent_event %d",prevent_event);
	quec_send_msg_to_handle_task(QUEC_ELECTRIC_FENCE_PREVENT_MSG, (char *)&prevent_event, sizeof(int));
}

void quec_electric_fence_send_blacklwip_event_msg(int blacklwip_event)
{
	if((blacklwip_event < QUEC_BLACKWLIP_PING_SUCCESS) || (blacklwip_event > QUEC_BLACKWLIP_PING_RESET))
	{
		atcmd_general_log("quec_electric_fence_send_blacklwip_event_msg: invaild event");
		return;
	}
	atcmd_general_log("quec_electric_fence_send_blacklwip_event_msg: event %d",blacklwip_event);
	quec_send_msg_to_handle_task(QUEC_ELECTRIC_FENCE_BLACKLWIP_MSG, (char *)&blacklwip_event, sizeof(int));
}

