UINT8 quec_electric_fence_preventiontimer_get_status(void)
{
    quec_timer_status_t timerstatus ={0};
	int ret = 0;

	if (quec_electric_fence_preventiontimer == NULL)
	{
		return PREVENTMR_STA_NULL;
	}
	else 
	{
		ret = quec_rtos_timer_get_status(quec_electric_fence_preventiontimer,&timerstatus);
		if (ret != kNoErr)
		{
			atcmd_general_log("quec_electric_fence_list_update_by_preventmsg get status fail,can not start");
			return PREVENTMR_STA_ERROR;
		}
	
		if(timerstatus.status == QUEC_TMR_STA_DISABLED)
		{
			return PREVENTMR_STA_DISABLED;
		}
		else
		{
			atcmd_general_log("quec_electric_fence_list_update_by_preventmsg timer already start");
			return PREVENTMR_STA_ENABLED;
		}
	}

}
void quec_electric_fence_preventiontimer_callback(void)
{
    UINT8 creg_status=0;
	UINT8 cereg_status=0;
	UINT8 prevent_event=0;

#if QUEC_DUAL_SIM_SUPPORT
		creg_status= quec_regstatus_asr2quec(quec_creg_info[isMasterSim0() ? SIM1 : SIM2].RegStatus, 1);
		cereg_status=quec_regstatus_asr2quec(quec_cereg_info[isMasterSim0() ? SIM1 : SIM2].status, 1);
#else
		creg_status= quec_regstatus_asr2quec(quec_creg_info.RegStatus, 1);
		cereg_status=quec_regstatus_asr2quec(quec_cereg_info.status, 1);
#endif 
	
		if((creg_status==1) || (creg_status==5)
		 ||(cereg_status==1) || (cereg_status==5))
		{
			prevent_event = QUEC_BLACKCELL_REGISTER_SUCCESS;
		}
		else 
		{
			prevent_event = QUEC_BLACKCELL_PREVENT_TIMEOUT;
		}
		
		atcmd_general_log("quec_electric_fence_preventiontimer_callback: prevent event %d",prevent_event);	
		quec_electric_fence_send_prevent_event_msg(prevent_event);
}

QuecOSStatus quec_electric_fence_list_set_blackcell(UINT8 optype,UINT8 rat,UINT32 arfcn,UINT16 cellId,UINT8 weightmask,UINT8 event_index)
{
	bool IsVaild = TRUE;
	bool IsChanged = FALSE;
    int MarkFound = -1;
    int MarkFirstEmpty = -1;
	int temp_index = -1;
	int mintickindex = 0;
	int mintick=0;
	int ret = 0;
	int i=0;
    quec_black_cell_s_t quec_blackcell_delete = {0};
	UINT8 preventimer_status=0;

	if(optype == BLACKCELL_ADD)	
	{
		quec_get_black_cell_num();
		switch (rat)
	    {
	        case BLACKCELL_GSM:    
	        {      
	        	if( g_quec_blackcell.GsmBlackCellList.numOfBlackCell > QUEC_MAX_BLACK_CELL_NUM)
	        	{
	        		IsVaild = FALSE;
	        	}
				break;
	        }
			case BLACKCELL_WCDMA:
			{
				if( g_quec_blackcell.UmtsBlackCellList.numOfBlackCell > QUEC_MAX_BLACK_CELL_NUM)
	        	{
	        		IsVaild = FALSE;
	        	}											
				break;
			}
			case BLACKCELL_LTE:
			{           
	        	if( g_quec_blackcell.LteBlackCellList.numOfBlackCell > QUEC_MAX_BLACK_CELL_NUM)
	        	{
	        		IsVaild = FALSE;
	        	}
				break;
	        }	  
	        default:
	        {
				atcmd_general_log("quec_electric_fence_list_set_blackcell: invaild rat %d",rat);
				return kGeneralErr;
	        }
	 
	    }

	    if(IsVaild== FALSE)
	    {
	    	atcmd_general_log("quec_electric_fence_list_set_blackcell: quec blackcell rat %d overflow",rat);
			return kGeneralErr;
	    }

		if(g_quec_electric_fence_list.blackcell_num <= QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM)
		{
			for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
			{
				if ( (g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
				 &&  (g_quec_electric_fence_list.blackcellid_list[i].rat == rat)
				 &&  (g_quec_electric_fence_list.blackcellid_list[i].arfcn == arfcn)
				 &&  (g_quec_electric_fence_list.blackcellid_list[i].cellId == cellId))
				{
					MarkFound = i;
				}

				if(g_quec_electric_fence_list.blackcellid_list[i].vaild == FALSE)
				{
					if((MarkFirstEmpty == -1) && (MarkFound == -1))
					{
						MarkFirstEmpty = i;
					}
				}
			}
		}
		else
		{
			atcmd_general_log("quec_electric_fence_list_set_blackcell: more than ten, invalid");
			return kGeneralErr;
		}

		atcmd_general_log("quec_electric_fence_list_set_blackcell: new rat %d, arfcn %d,cellid %d weightmask %d event %d, MarkFound %d MarkFirstEmpty %d",
		           rat,arfcn,cellId,weightmask,event_index,MarkFound,MarkFirstEmpty);

		if(MarkFound != -1)
		{
			temp_index = MarkFound;
			if( (g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask & POWERDOWN_EVENT) != (weightmask & POWERDOWN_EVENT))
			{
				IsChanged = TRUE;
				atcmd_general_log("quec_electric_fence_list_set_blackcell: weight POWERDOWN_EVENT %d add %d",g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask,weightmask);
			}
			g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask = g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask | weightmask;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].event_index = event_index;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].black_ticks = OSAGetTicks();
			
			atcmd_general_log("quec_electric_fence_list_set_blackcell: already set, update new weight %d new event %d new ticks %d",
					 g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask,event_index,g_quec_electric_fence_list.blackcellid_list[MarkFound].black_ticks);
		}
		else if (MarkFirstEmpty != -1)
		{
			temp_index = MarkFirstEmpty;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].vaild = TRUE;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].rat = rat;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].arfcn = arfcn;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].cellId = cellId;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].weightmask = weightmask;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].event_index = event_index;
			g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].black_ticks = OSAGetTicks();
			g_quec_electric_fence_list.blackcell_num++;

			atcmd_general_log("quec_electric_fence_list_set_blackcell: add blackcell weight%d event %d ticks %d",
					g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].weightmask,event_index,g_quec_electric_fence_list.blackcellid_list[MarkFirstEmpty].black_ticks);
		}
		else
		{
			mintick = g_quec_electric_fence_list.blackcellid_list[0].black_ticks;
			mintickindex = 0;

			for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
			{
				if(g_quec_electric_fence_list.blackcellid_list[i].black_ticks < mintick)
				{
					mintickindex = i;
					mintick = g_quec_electric_fence_list.blackcellid_list[i].black_ticks;
				}
			}

			g_quec_blackcell.opType = BLACKCELL_DELETE;
			g_quec_blackcell.rat = g_quec_electric_fence_list.blackcellid_list[mintickindex].rat;
			quec_update_cell_id(g_quec_electric_fence_list.blackcellid_list[mintickindex].arfcn,
			                    g_quec_electric_fence_list.blackcellid_list[mintickindex].cellId,
			                    g_quec_electric_fence_list.blackcellid_list[mintickindex].rat);
	
			atcmd_general_log("quec_electric_fence_list_set_blackcell: full cell arfcn %d,cellid %d weightmask %d event %d clear",
								g_quec_electric_fence_list.blackcellid_list[mintickindex].arfcn,
								g_quec_electric_fence_list.blackcellid_list[mintickindex].cellId,
								g_quec_electric_fence_list.blackcellid_list[mintickindex].weightmask,
								g_quec_electric_fence_list.blackcellid_list[mintickindex].event_index);
			
			temp_index = mintickindex;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].vaild = TRUE;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].rat = rat;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].arfcn = arfcn;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].cellId = cellId;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].weightmask = weightmask;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].event_index = event_index;
			g_quec_electric_fence_list.blackcellid_list[mintickindex].black_ticks = OSAGetTicks();

		}

		if(temp_index != -1)
		{
			if(g_quec_electric_fence_list.blackcellid_list[temp_index].weightmask != NONE_OPERATE)
			{
				//quec_gwl_blackcell_process(arfcn,cellId,rat,BLACKCELL_ADD);
				g_quec_blackcell.opType = BLACKCELL_ADD;
				g_quec_blackcell.rat = rat;
				quec_update_cell_id(arfcn,cellId,rat);
				quec_get_black_cell_num();
				Quec_DEV_SetBlackCellReq((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE), &g_quec_blackcell);
				if (quec_get_black_cell_prevention_mode() == QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_MODE_ON)
				{
					preventimer_status = quec_electric_fence_preventiontimer_get_status();
					if((preventimer_status == PREVENTMR_STA_NULL) || (preventimer_status == PREVENTMR_STA_DISABLED))
					{
						quec_electric_fence_send_prevent_event_msg(QUEC_BLACKCELL_NETWORK_DROPOUT);
					}
				}
			}
		}

		if (( (g_quec_electric_fence_list.blackcellid_list[temp_index].weightmask & POWERDOWN_EVENT) == 0)
			|| (IsChanged == TRUE))
		{
			atcmd_general_log("quec_electric_fence_list_set_blackcell: weight %d, need save to nv",weightmask);
			ret = quectel_nv_fat_write(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list, sizeof(g_quec_electric_fence_list));
		     if (ret != QUEC_SUCCESS)
			{
				atcmd_general_log("quec_electric_fence_list_set_blackcell: quec_electric_fence_config write failed"); 
				return kGeneralErr;
			}
		}

		if( (g_quec_electric_fence_list.blackcellid_list[temp_index].weightmask & TIMER_EVENT) != 0)
		{
		   quec_electric_fence_recover_timer_start(g_quec_electric_fence_list.blackcelltimer_size*1000,FALSE,quec_electric_fence_recover_timer_callback,0);
		   atcmd_general_log("quec_electric_fence_list_set_blackcell: timer start"); 
		}

		return kNoErr;
	}
	else if(optype == BLACKCELL_DELETE)
	{
	    memset(&quec_blackcell_delete,0,sizeof(quec_black_cell_s_t));
		for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
		{
			if ( (g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
			 &&  (g_quec_electric_fence_list.blackcellid_list[i].rat == rat)
			 &&  (g_quec_electric_fence_list.blackcellid_list[i].arfcn == arfcn)
			 &&  (g_quec_electric_fence_list.blackcellid_list[i].cellId == cellId))
			{
				MarkFound = i;
			}
		}

		if(MarkFound != -1)
		{
			quec_blackcell_delete.opType = optype;
			g_quec_blackcell.opType = optype;
			quec_blackcell_delete.rat = rat;
			quec_delete_black_cell_item(arfcn,cellId,rat,&quec_blackcell_delete);
			quec_update_cell_id(arfcn,cellId,rat);

			g_quec_electric_fence_list.blackcellid_list[MarkFound].vaild = FALSE;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].rat = 0;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].cellId = 0;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].arfcn = 0;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask = 0;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].event_index = 0;
			g_quec_electric_fence_list.blackcellid_list[MarkFound].black_ticks = 0;
			g_quec_electric_fence_list.blackcell_num--;

			Quec_DEV_SetBlackCellReq((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE), &quec_blackcell_delete);
			if ( (g_quec_electric_fence_list.blackcellid_list[MarkFound].weightmask & POWERDOWN_EVENT) == 0)
			{
				atcmd_general_log("quec_electric_fence_list_set_blackcell: DELETE rat %d, arfcn %d,cellid %d weight %d, need save to nv",rat,arfcn,cellId,weightmask);
				ret = quectel_nv_fat_write(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list, sizeof(g_quec_electric_fence_list));
		     	if (ret != QUEC_SUCCESS)
				{
					atcmd_general_log("quec_electric_fence_config write failed"); 
					return kGeneralErr;
				}
			}
			return kNoErr;
		}
		else 
		{
			atcmd_general_log("quec quec_electric_fence_list: rat %d, arfcn %d,cellid %d not on the blackcelllist",rat,arfcn,cellId);
			return kNoErr;
		}
	}
	else
	{
		atcmd_general_log("quec_electric_fence_list_set_blackcell: invaild optype");
		return kGeneralErr;
	}
}


void quec_electric_fence_list_update_by_event(int event)
{
	int i=0;
	bool IsChanged = FALSE; 
	bool TimeInitFlag = FALSE;
	bool ReqSendflag = FALSE;
	int ret = 0;
    quec_black_cell_s_t quec_blackcell_delete = {0};
	UINT8 preventimer_status=0;

	if((g_quec_electric_fence_list.blackcell_num == 0) && (event != POWERDOWN_EVENT))
	{
		atcmd_general_log("quec_electric_fence_list: no blackcell");
		return;
	}

	atcmd_general_log("quec_electric_fence_list_update_by_event: event %d",event);
	switch (event)
    {
        case POWERDOWN_EVENT:    
        {      
			for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
			{
				if ((g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
				 &&  ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & POWERDOWN_EVENT) == 0)
				 &&	 (g_quec_electric_fence_list.blackcellid_list[i].weightmask != NONE_OPERATE))
				{
					if(ReqSendflag != TRUE)
				    {
				    	ReqSendflag = TRUE;
					}
					atcmd_general_log("quec_electric_fence_list_update_by_event: event %d rat %d arfcn %d cellId %d weight %d power on",
						event,
						g_quec_electric_fence_list.blackcellid_list[i].rat,
						g_quec_electric_fence_list.blackcellid_list[i].arfcn,
						g_quec_electric_fence_list.blackcellid_list[i].cellId,
						g_quec_electric_fence_list.blackcellid_list[i].weightmask);
					
					g_quec_electric_fence_list.blackcellid_list[i].black_ticks = OSAGetTicks();

					/* 1606 Only lte is considered here */					   
					g_quec_blackcell.opType = BLACKCELL_ADD;
					g_quec_blackcell.rat = g_quec_electric_fence_list.blackcellid_list[i].rat;
					quec_update_cell_id(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
					                    g_quec_electric_fence_list.blackcellid_list[i].cellId,
					                    g_quec_electric_fence_list.blackcellid_list[i].rat);
					
					if(((g_quec_electric_fence_list.blackcellid_list[i].weightmask & TIMER_EVENT) != 0)
						&&(TimeInitFlag == FALSE))
					{
						TimeInitFlag = TRUE;
					}
				}
				else if ((g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
				 &&  ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & POWERDOWN_EVENT) != 0))
				{
					IsChanged = TRUE;
					atcmd_general_log("quec_electric_fence_list_update_by_event: event %d rat %d arfcn %d cellId %d weight %d clear",
						event,
						g_quec_electric_fence_list.blackcellid_list[i].rat,
						g_quec_electric_fence_list.blackcellid_list[i].arfcn,
						g_quec_electric_fence_list.blackcellid_list[i].cellId,
						g_quec_electric_fence_list.blackcellid_list[i].weightmask);
					
					g_quec_electric_fence_list.blackcellid_list[i].vaild = FALSE;
					g_quec_electric_fence_list.blackcellid_list[i].rat = 0;
					g_quec_electric_fence_list.blackcellid_list[i].cellId = 0;
					g_quec_electric_fence_list.blackcellid_list[i].arfcn = 0;
					g_quec_electric_fence_list.blackcellid_list[i].weightmask = 0;
					g_quec_electric_fence_list.blackcellid_list[i].event_index = 0;
					g_quec_electric_fence_list.blackcellid_list[i].black_ticks = 0;
					g_quec_electric_fence_list.blackcell_num--;
				}
			}

			if(ReqSendflag == TRUE)
			{
				quec_get_black_cell_num();
				Quec_DEV_SetBlackCellReq((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE), &g_quec_blackcell);
				if (quec_get_black_cell_prevention_mode() == QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_MODE_ON)
				{
					preventimer_status = quec_electric_fence_preventiontimer_get_status();
					if((preventimer_status == PREVENTMR_STA_NULL) || (preventimer_status == PREVENTMR_STA_DISABLED))
					{
						quec_electric_fence_send_prevent_event_msg(QUEC_BLACKCELL_NETWORK_DROPOUT);
					}
				}
			}
			if(TimeInitFlag == TRUE)
			{		   
				atcmd_general_log("quec_electric_fence_list_update_by_event: power on timer start"); 
				quec_electric_fence_recover_timer_start(g_quec_electric_fence_list.blackcelltimer_size*1000,FALSE,quec_electric_fence_recover_timer_callback,0);
			}
			
			break;
        }
		case CFUN_EVENT:
		{
		    memset(&quec_blackcell_delete,0,sizeof(quec_black_cell_s_t));
			for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
			{
				if ((g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
				 &&  ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & CFUN_EVENT) != 0))
				{
					if(ReqSendflag != TRUE)
				    {
				    	ReqSendflag = TRUE;
					}
					
					if((IsChanged == FALSE) && ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & POWERDOWN_EVENT) == 0))
					{
						IsChanged = TRUE;
					}			

					quec_blackcell_delete.opType = BLACKCELL_DELETE;
					g_quec_blackcell.opType = BLACKCELL_DELETE;
					quec_blackcell_delete.rat = g_quec_electric_fence_list.blackcellid_list[i].rat;
					quec_delete_black_cell_item(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
					                    g_quec_electric_fence_list.blackcellid_list[i].cellId,
					                    g_quec_electric_fence_list.blackcellid_list[i].rat
					                    ,&quec_blackcell_delete);
					quec_update_cell_id(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
					                    g_quec_electric_fence_list.blackcellid_list[i].cellId,
					                    g_quec_electric_fence_list.blackcellid_list[i].rat);

					atcmd_general_log("quec_electric_fence_list_update_by_event: event %d rat %d arfcn %d cellId %d weight %d clear",
						event,
						g_quec_electric_fence_list.blackcellid_list[i].rat,
						g_quec_electric_fence_list.blackcellid_list[i].arfcn,
						g_quec_electric_fence_list.blackcellid_list[i].cellId,
						g_quec_electric_fence_list.blackcellid_list[i].weightmask);

					g_quec_electric_fence_list.blackcellid_list[i].vaild = FALSE;
					g_quec_electric_fence_list.blackcellid_list[i].rat = 0;
					g_quec_electric_fence_list.blackcellid_list[i].cellId = 0;
					g_quec_electric_fence_list.blackcellid_list[i].arfcn = 0;
					g_quec_electric_fence_list.blackcellid_list[i].weightmask = 0;
					g_quec_electric_fence_list.blackcellid_list[i].event_index = 0;
					g_quec_electric_fence_list.blackcellid_list[i].black_ticks = 0;
					g_quec_electric_fence_list.blackcell_num--;
				}
			}	

			if(ReqSendflag == TRUE)
			{
				Quec_DEV_SetBlackCellReq((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE), &quec_blackcell_delete);
			}
			break;
		}
		case TIMER_EVENT:
		{       
		    memset(&quec_blackcell_delete,0,sizeof(quec_black_cell_s_t));
			for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
			{
				if ((g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
				 &&  ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & TIMER_EVENT) != 0))
				{	
					if(ReqSendflag != TRUE)
				    {
				    	ReqSendflag = TRUE;
					}
					if((IsChanged == FALSE) && ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & POWERDOWN_EVENT)== 0))
					{
						IsChanged = TRUE;
					}

					quec_blackcell_delete.opType = BLACKCELL_DELETE;
					g_quec_blackcell.opType = BLACKCELL_DELETE;
					quec_blackcell_delete.rat = g_quec_electric_fence_list.blackcellid_list[i].rat;
					quec_delete_black_cell_item(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
					                    g_quec_electric_fence_list.blackcellid_list[i].cellId,
					                    g_quec_electric_fence_list.blackcellid_list[i].rat
					                    ,&quec_blackcell_delete);
					quec_update_cell_id(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
					                    g_quec_electric_fence_list.blackcellid_list[i].cellId,
					                    g_quec_electric_fence_list.blackcellid_list[i].rat);

					atcmd_general_log("quec_electric_fence_list_update_by_event: event %d rat %d arfcn %d cellId %d weight %d clear",
						event,
						g_quec_electric_fence_list.blackcellid_list[i].rat,
						g_quec_electric_fence_list.blackcellid_list[i].arfcn,
						g_quec_electric_fence_list.blackcellid_list[i].cellId,
						g_quec_electric_fence_list.blackcellid_list[i].weightmask);

					g_quec_electric_fence_list.blackcellid_list[i].vaild = FALSE;
					g_quec_electric_fence_list.blackcellid_list[i].rat = 0;
					g_quec_electric_fence_list.blackcellid_list[i].cellId = 0;
					g_quec_electric_fence_list.blackcellid_list[i].arfcn = 0;
					g_quec_electric_fence_list.blackcellid_list[i].weightmask = 0;
					g_quec_electric_fence_list.blackcellid_list[i].event_index = 0;
					g_quec_electric_fence_list.blackcellid_list[i].black_ticks = 0;
					g_quec_electric_fence_list.blackcell_num--;

				}
			}	
			
			if(ReqSendflag == TRUE)
			{	
				Quec_DEV_SetBlackCellReq((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE), &quec_blackcell_delete);
			}
			break;
        }	  
        default:
        {
			atcmd_general_log("quec_electric_fence_list: invaild event %d",event);
			return;
        }
    }

	if(IsChanged == TRUE)
	{
		ret = quectel_nv_fat_write(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list, sizeof(g_quec_electric_fence_list));
     	if (ret != QUEC_SUCCESS)
		{
			atcmd_general_log("quec_electric_fence_config write failed"); 
		}
	}
}

void quec_electric_fence_list_update_by_preventmsg(UINT8 prevent_level)
{
	int i=0;
	bool IsChanged = FALSE; 
	bool ReqSendflag = FALSE;
	int ret = 0;
    quec_black_cell_s_t quec_blackcell_delete = {0};
	UINT8 weight_fence = 0;
	bool IsOver = FALSE;

	if(g_quec_electric_fence_list.blackcell_num == 0)
	{
		atcmd_general_log("quec_electric_fence_list: no blackcell");
		quec_electric_fence_preventiontimer_stop();
    	quec_electric_fence_preventiontimer_delete();
		return;
	}

	atcmd_general_log("quec_electric_fence_list_update_by_preventmsg: level %d",prevent_level);

	if(prevent_level == QUEC_BLACKCELL_REGISTER_SUCCESS)
	{
		quec_electric_fence_preventiontimer_stop();
    	quec_electric_fence_preventiontimer_delete();
	}
	else if(prevent_level == QUEC_BLACKCELL_NETWORK_DROPOUT)
	{
    	quec_electric_fence_preventiontimer_start(g_quec_electric_fence_list.blackcellpreventiontimer_size*1000,FALSE,quec_electric_fence_preventiontimer_callback,0);
	}
	else if((prevent_level >= 2) && (prevent_level <= 4))
	{  
		if(prevent_level == 2)
		{
			weight_fence = TIMER_EVENT;
			IsOver = FALSE;
		}
		else if(prevent_level == 3)
		{
			weight_fence = TIMER_EVENT + CFUN_EVENT;
			IsOver = FALSE;
		}
		else if(prevent_level == 4)
		{
			weight_fence = TIMER_EVENT + CFUN_EVENT + POWERDOWN_EVENT;
			IsOver = TRUE;
		}

		memset(&quec_blackcell_delete,0,sizeof(quec_black_cell_s_t));
		for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
		{
			if ((g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
			 &&  ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & weight_fence) != 0))
			{
				if(ReqSendflag != TRUE)
				{
					ReqSendflag = TRUE;
				}		

				if((IsChanged == FALSE) && ((g_quec_electric_fence_list.blackcellid_list[i].weightmask & POWERDOWN_EVENT)== 0))
				{
					IsChanged = TRUE;
				}
				
				quec_blackcell_delete.opType = BLACKCELL_DELETE;
				g_quec_blackcell.opType = BLACKCELL_DELETE;
				quec_blackcell_delete.rat = g_quec_electric_fence_list.blackcellid_list[i].rat;
				quec_delete_black_cell_item(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
									g_quec_electric_fence_list.blackcellid_list[i].cellId,
									g_quec_electric_fence_list.blackcellid_list[i].rat
									,&quec_blackcell_delete);
				quec_update_cell_id(g_quec_electric_fence_list.blackcellid_list[i].arfcn,
									g_quec_electric_fence_list.blackcellid_list[i].cellId,
									g_quec_electric_fence_list.blackcellid_list[i].rat);

				atcmd_general_log("quec_electric_fence_list_update_by_preventmsg: weightfence %d rat %d arfcn %d cellId %d weight %d clear",
					weight_fence,
					g_quec_electric_fence_list.blackcellid_list[i].rat,
					g_quec_electric_fence_list.blackcellid_list[i].arfcn,
					g_quec_electric_fence_list.blackcellid_list[i].cellId,
					g_quec_electric_fence_list.blackcellid_list[i].weightmask);
				
				g_quec_electric_fence_list.blackcellid_list[i].vaild = FALSE;
				g_quec_electric_fence_list.blackcellid_list[i].rat = 0;
				g_quec_electric_fence_list.blackcellid_list[i].cellId = 0;
				g_quec_electric_fence_list.blackcellid_list[i].arfcn = 0;
				g_quec_electric_fence_list.blackcellid_list[i].weightmask = 0;
				g_quec_electric_fence_list.blackcellid_list[i].event_index = 0;
				g_quec_electric_fence_list.blackcellid_list[i].black_ticks = 0;
				
				g_quec_electric_fence_list.blackcell_num--;
			}
		}
		
		if(ReqSendflag == TRUE)
		{	
			Quec_DEV_SetBlackCellReq((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE), &quec_blackcell_delete);
		}

		if(IsChanged == TRUE)
		{
			ret = quectel_nv_fat_write(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list, sizeof(g_quec_electric_fence_list));
			if (ret != QUEC_SUCCESS)
			{
				atcmd_general_log("quec_electric_fence_config write failed"); 
			}
		}

		if(IsOver == FALSE)
		{
			quec_electric_fence_preventiontimer_start((g_quec_electric_fence_list.blackcellpreventiontimer_size*1000)/2,FALSE,quec_electric_fence_preventiontimer_callback,0);
		}
		else
		{
			quec_electric_fence_preventiontimer_stop();
    		quec_electric_fence_preventiontimer_delete();
		}
	}
	else 
	{
		quec_electric_fence_preventiontimer_stop();
    	quec_electric_fence_preventiontimer_delete();
	}
	
}

void quec_electric_fence_list_update_by_blacklwipmsg(int blacklwip_event)
{
	char res_buf[128] = {0};
	int ret = 0;

	atcmd_general_log("quec_electric_fence_list_update_by_blacklwipmsg: event %d",blacklwip_event);

	if(blacklwip_event == QUEC_BLACKWLIP_PING_FAILD)
	{	
		if(g_quec_blacklwipcfg.pingcount <= g_quec_blacklwipcfg.retrynum)
		{
#if QUEC_DUAL_SIM_SUPPORT
			SendATCMDWaitResp((isMasterSim0() ? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2), "AT+CFUN=0\r\n", 20, NULL, 1, NULL, res_buf, sizeof(res_buf));
#else
			SendATCMDWaitResp(TEL_AT_CMD_ATP_QUEC_INTERNAL, "AT+CFUN=0\r\n", 20, NULL, 1, NULL, res_buf, sizeof(res_buf));		
#endif

#if QUEC_DUAL_SIM_SUPPORT
			SendATCMDWaitResp((isMasterSim0() ? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2), "AT+CFUN=1\r\n", 20, NULL, 1, NULL, res_buf, sizeof(res_buf));
#else
			SendATCMDWaitResp(TEL_AT_CMD_ATP_QUEC_INTERNAL, "AT+CFUN=1\r\n", 20, NULL, 1, NULL, res_buf, sizeof(res_buf));		
#endif
		}
	}
	
}


void quec_electric_fence_list_cfg_init_nv(void)
{
	QuecOSStatus ret = kGeneralErr;
	quec_electric_fence_list g_quec_electric_fence_list_temp;

	ret = quectel_nv_fat_read(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list_temp, sizeof(g_quec_electric_fence_list_temp));
	if(ret != QUEC_FAT_SUCCESS)
	{
		atcmd_general_log("quec_electric_fence_config read failed"); 
	}
	else 
	{
		memcpy(&g_quec_electric_fence_list, &g_quec_electric_fence_list_temp,sizeof(g_quec_electric_fence_list_temp));
	}

	return;
}

void quec_electric_fence_lwip_uplink_count(void)
{
	static UINT32 startticks=0;
	UINT32 endticks=0;


	if(g_quec_blacklwipcfg.blacklwip_packectcount == g_quec_blacklwipcfg.blacklwip_fencenum)
	{
		startticks = OSAGetTicks();
	}
	atcmd_general_log("quec_electric_fence_lwip_uplink_count test count %d num %d start %d end %d",g_quec_blacklwipcfg.blacklwip_packectcount,g_quec_blacklwipcfg.blacklwip_fencenum,startticks,endticks); 

	g_quec_blacklwipcfg.blacklwip_packectcount--;
	
	if(g_quec_blacklwipcfg.blacklwip_packectcount == 0)
	{
		endticks = OSAGetTicks();
		atcmd_general_log("quec_electric_fence_lwip_uplink_count lost %d start %d end %d pingcount %d",g_quec_blacklwipcfg.blacklwip_fencenum,startticks,endticks,g_quec_blacklwipcfg.pingcount); 
		if(((endticks - startticks)*5) < (g_quec_blacklwipcfg.blacklwip_fencecycle*1000))
		{
			if(g_quec_blacklwipcfg.pingcount < g_quec_blacklwipcfg.retrynum)
			{	
				quec_blacklwipcfg_ping(g_quec_blacklwipcfg.athandle);
				g_quec_blacklwipcfg.pingcount++;
			}
			else 
			{
				g_quec_blacklwipcfg.blacklwip_packectcount = g_quec_blacklwipcfg.blacklwip_fencenum;
			}
		}
		else 
		{
			g_quec_blacklwipcfg.blacklwip_packectcount = g_quec_blacklwipcfg.blacklwip_fencenum;
		}
	}	
}

void quec_electric_fence_lwip_downlink_count(void)
{
	g_quec_blacklwipcfg.blacklwip_packectcount = g_quec_blacklwipcfg.blacklwip_fencenum;

	if(g_quec_blacklwipcfg.pingcount >= g_quec_blacklwipcfg.retrynum)
	{
		atcmd_general_log("quec_electric_fence_lwip_downlink_count ping count %d reset",g_quec_blacklwipcfg.pingcount); 
		g_quec_blacklwipcfg.pingcount = 0;
	}
}

RETURNCODE_T quectel_exec_blackcellex_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */  
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */   
    void                           *arg_p               /* AT cmd parser number */
)
{
    RETURNCODE_T    rc = INITIAL_RETURN_CODE;
    CiReturnCode    ret = CIRC_SUCCESS;
    TelAtParserID   sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32          atHandle  = MAKE_AT_HANDLE(sAtpIndex);
    UINT8 i = 0;
    UINT8 validCmd = TRUE;
    UINT8 arg_cnt = 0;
    UINT8 arg_index = 0;
    int  cmdopType = 0;
    int  rat = (int)BLACKCELL_GSM;
    int  resp_len = 0;
    char blackcell_list[QUEC_MAX_BLACK_CELL_LEN] = {0};
    INT16 blackcell_list_len = 0;
    int afrcn = 0;
    int cellId = 0;
	UINT8 weightmask = 0;
 	char blackcellbuf[512] = {0};
	int  blackcellbuflen = 0;
	
    *xid_p = atHandle;
    switch (op)
    {
        case TEL_EXT_TEST_CMD:
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
            break;
        }
        case TEL_EXT_SET_CMD:
        {
		   arg_cnt = quec_get_at_param_num(parameter_values_p,num_parameters);

		   while( (arg_index < arg_cnt) && (validCmd == TRUE) )
		   {
                switch(arg_index)
                {
					case 0: /*cmdopType: 0 is set 1 is detele black cell */
					{
						if( getExtValue( parameter_values_p, 0, &cmdopType, 0, 1, 0) == FALSE )
                        {
                            validCmd = FALSE;
                        } 
                        else 
                        {
                            g_quec_blackcell.opType = cmdopType;
                        }
					}
				    break;

					case 1: /*rat: 0 is gsm 1 is wcdma 2 is lte add or delete which rat black cell*/
					{
						if( getExtValue( parameter_values_p, 1, &rat, BLACKCELL_GSM, BLACKCELL_LTE, BLACKCELL_GSM) == FALSE )
                        {
							validCmd = FALSE;
						}
						else
                        {
							g_quec_blackcell.rat = rat;
						}
					}
					break;
					
					case 2: /*black cell list*/
					{
                        if ((getExtString(parameter_values_p, 2, blackcell_list, QUEC_MAX_BLACK_CELL_LEN, &blackcell_list_len, NULL) == FALSE))
                        {
                            validCmd = FALSE;
                        }
                        else 
                        {
                            if (blackcell_list_len == 0)
                            {
                                atcmd_general_log("quec blackcellex: not add or delete black cell");
                            }
                            else 
                            {
                                char *ret_str = NULL;

                                ret_str = strtok(blackcell_list,":");
                                if(ret_str != NULL)
                                {
                                    if(FALSE == str2int32(ret_str,5,&afrcn))
                                    {
                                        validCmd = FALSE;
                                        atcmd_general_log("quec blackcellex: str2int32 afrcn failed");
                                        break;
                                    }
                                    else 
                                    {
                                        ret_str = strtok(NULL,":");
                                        if (ret_str != NULL)
                                        {
                                            if (FALSE == str2int32(ret_str,5,&cellId))
                                            {
                                                validCmd = FALSE;
                                                atcmd_general_log("quec blackcellex: str2int32 cellid failed");
                                                break;
                                            }
                                        }
                                    }
                                }
                            }
                        }
					}
					break;
					
					case 3: /*weight mask*/
					{
                        if ( getExtValue( parameter_values_p, 3, &weightmask, NONE_OPERATE, ALL_EVENT, POWERDOWN_EVENT) == FALSE )
                        {
                            validCmd = FALSE;
                        }
                        else 
                        {
                            atcmd_general_log("quec_electric_fence_list: %d,%d,%d --- %d-%d-%d",rat,afrcn,cellId,(weightmask & POWERDOWN_EVENT),(weightmask & CFUN_EVENT),(weightmask & TIMER_EVENT));
                        }
					}
					break;
					default:
                    {
                        validCmd = FALSE;
                        atcmd_general_log("quec blackcellex: param invalid=%d",arg_cnt);
                        break;
                    }
                }
                arg_index++;
           }

		if (validCmd == TRUE)
		{
			ret = quec_electric_fence_list_set_blackcell(cmdopType,rat,afrcn,cellId,weightmask,0xFF);
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL );
		}
		else 
		{
		   ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
		}
		break;
		}

        case TEL_EXT_GET_CMD:
        {
        	memset(blackcellbuf, 0, sizeof(blackcellbuf));
			blackcellbuflen = 0;
        	for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
			{
				//if (g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
				{
					blackcellbuflen += snprintf(blackcellbuf+blackcellbuflen,sizeof(blackcellbuf)-blackcellbuflen,
						"+QBLACKCELLEX: %d,%d,%d,%d,%d,%d\r\n",
						   g_quec_electric_fence_list.blackcellid_list[i].vaild,
						   g_quec_electric_fence_list.blackcellid_list[i].rat,
						   g_quec_electric_fence_list.blackcellid_list[i].arfcn,
						   g_quec_electric_fence_list.blackcellid_list[i].cellId,
					       g_quec_electric_fence_list.blackcellid_list[i].weightmask,
					       g_quec_electric_fence_list.blackcellid_list[i].event_index);
				}
			}
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, blackcellbuf);
            break;

        }
        default:
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
            break;
        }
    }
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

RETURNCODE_T quectel_exec_blackcellcfgex_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */  
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */   
    void                           *arg_p               /* AT cmd parser number */
)
{
    RETURNCODE_T    rc = INITIAL_RETURN_CODE;
    CiReturnCode    ret = CIRC_SUCCESS;
    TelAtParserID   sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32          atHandle  = MAKE_AT_HANDLE(sAtpIndex);
    int blackcellcfg = 0;
    int resp_len = 0;
    char res_buf[128] = {0};
    UINT8 validCmd = TRUE;
    UINT8 arg_cnt = 0;
	UINT8 arg_index = 0;

	int i=0;
	int delete_timer_size=0;
	int prevention_mode=0;
	int prevention_timer_size=0;
	int reject_judge_mode=0;
	int reject_judge_count=0;
	int black_loop_num=0;
    int black_loop_cycle=0;
	
	UINT8 blackeventweight=0;
	bool IsChanged = FALSE;
	
    *xid_p = atHandle;
    switch (op)
    {
        case TEL_EXT_TEST_CMD:
        {
            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QBLACKCELLCFGEX: (0,1),(300-86400),(0,1),(60-3600),(0,1),(1-255),(1,255),(300-32400)\r\n");
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
            break;
        }
        case TEL_EXT_SET_CMD:
        {
		   arg_cnt = quec_get_at_param_num(parameter_values_p,num_parameters);
		   atcmd_general_log("quec blackcellcfg: param num = %d",arg_cnt);
		   while( (arg_index < arg_cnt) && (validCmd == TRUE) )
		   {
		  	 	switch(arg_index)
				{
					case 0: /*fence_status: 0 is off 1 is on */
					{
						if( getExtValue( parameter_values_p, 0, &blackcellcfg, QUEC_BLACKCELL_DISABLE, QUEC_BLACKCELL_ENABLE, QUEC_BLACKCELL_DISABLE) == FALSE )
				        {
				            validCmd = FALSE;
				        }
					}
				    break;

					case 1: /*fence cell delete timer*/
					{
						if( getExtValue( parameter_values_p, 1, &delete_timer_size, QUEC_BLACK_ELECTRIC_FENCE_TIMER_MIN, QUEC_BLACK_ELECTRIC_FENCE_TIMER_MAX, QUEC_BLACK_ELECTRIC_FENCE_TIMER_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;

					case 2:/*prevention mode: 0 is off, 1 is on*/
					{
						if( getExtValue( parameter_values_p, 2, &prevention_mode, QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_MODE_OFF, QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_MODE_ON, QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_MODE_ON) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					
					case 3:/*prevention mode timer*/
					{
						if( getExtValue( parameter_values_p, 3, &prevention_timer_size, QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_TIMER_MIN, QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_TIMER_MAX, QUEC_BLACK_ELECTRIC_FENCE_PREVENTION_TIMER_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					
					case 4:/*Scenario 1-3 judge mode: 0 is continuous, 1 is accumulate*/
					{
						if( getExtValue( parameter_values_p, 4, &reject_judge_mode, QUEC_BLACK_ELECTRIC_FENCE_CONTINUOUS_JUDGE, QUEC_BLACK_ELECTRIC_FENCE_ACCUMULATE_JUDGE, QUEC_BLACK_ELECTRIC_FENCE_CONTINUOUS_JUDGE) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					
					case 5:/*Scenario 1-3 judge count*/
					{
						if( getExtValue( parameter_values_p, 5, &reject_judge_count, QUEC_BLACK_ELECTRIC_FENCE_REJECT_COUNT_MIN, QUEC_BLACK_ELECTRIC_FENCE_REJECT_COUNT_MAX, QUEC_BLACK_ELECTRIC_FENCE_REJECT_COUNT_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;

					case 6:/*Scenario 1 judge mode: 0 is continuous, 1 is accumulate*/
					{
						if( getExtValue( parameter_values_p, 6, &black_loop_num, QUEC_BLACK_ELECTRIC_FENCE_ALGRAPH_LOOP_NUM_MIN, QUEC_BLACK_ELECTRIC_FENCE_ALGRAPH_LOOP_NUM_MAX, QUEC_BLACK_ELECTRIC_FENCE_ALGRAPH_LOOP_NUM_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					
					case 7:
					{
						if( getExtValue( parameter_values_p, 7, &black_loop_cycle, QUEC_BLACK_ELECTRIC_FENCE_ALGRAPH_LOOP_CYCLE_MIN, QUEC_BLACK_ELECTRIC_FENCE_ALGRAPH_LOOP_CYCLE_MAX, QUEC_BLACK_ELECTRIC_FENCE_ALGRAPH_LOOP_CYCLE_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					default:
				    {
				        validCmd = FALSE;
				        atcmd_general_log("quec blackcellcfg: param invalid=%d",arg_cnt);
				        break;
				    }
				}
                arg_index++;
		   }
           
           if (validCmd == TRUE)
           {
           	
				if(arg_cnt == 8)
				{
	           		if(black_loop_cycle != quec_get_black_cell_fence_loop_cycle())
					{
						IsChanged = TRUE;
						quec_set_black_cell_fence_loop_cycle(black_loop_cycle);
	           		}
				}
				if(arg_cnt >= 7)
				{
	           		if(black_loop_num != quec_get_black_cell_fence_loop_num())
					{
						IsChanged = TRUE;
						quec_set_black_cell_fence_loop_num(black_loop_num);
	           		}
				}
				if(arg_cnt >= 6)
				{
	           		if(reject_judge_count != quec_get_black_cell_reject_judge_num())
					{
						IsChanged = TRUE;
						quec_set_black_cell_reject_judge_num(reject_judge_count);
	           		}
				}
				if(arg_cnt >= 5)
				{
	           		if(reject_judge_mode != quec_get_black_cell_reject_judge_mode())
					{
						IsChanged = TRUE;
						quec_set_black_cell_reject_judge_mode(reject_judge_mode);
	           		}
				}	
				if(arg_cnt >= 4)
				{
	           		if(prevention_timer_size != quec_get_black_cell_preventiontimer_size())
					{
						IsChanged = TRUE;
						quec_set_black_cell_preventiontimer_size(prevention_timer_size);
	           		}
				}
				if(arg_cnt >= 3)
				{
	           		if(prevention_mode != quec_get_black_cell_prevention_mode())
					{
						IsChanged = TRUE;
						quec_set_black_cell_prevention_mode(prevention_mode);
	           		}
				}
				if(arg_cnt >= 2)
				{
	           		if(delete_timer_size != quec_get_black_cell_deletetimer_size())
					{
						IsChanged = TRUE;
						quec_set_black_cell_deletetimer_size(delete_timer_size);
	           		}
				}
				if(arg_cnt >= 1)
				{
	           		if(blackcellcfg != quec_get_black_cell_cfg_ex())
					{
						IsChanged = TRUE;
						quec_set_black_cell_cfg_ex(blackcellcfg);
						if (QUEC_BLACKCELL_DISABLE == quec_get_black_cell_cfg_ex())
						{
							quec_delete_all_blackcell();
							quec_get_fence_black_cell_num();
							if(g_quec_electric_fence_list.blackcell_num != 0)
							{
								for(i=0; i<QUEC_BLACK_ELECTRIC_FENCE_CELL_MAX_NUM; i++)
								{
									if(g_quec_electric_fence_list.blackcellid_list[i].vaild == TRUE)
									{
										memset(&g_quec_electric_fence_list.blackcellid_list[i], 0, sizeof(g_quec_electric_fence_list.blackcellid_list[i]));
									}
								}
								g_quec_electric_fence_list.blackcell_num = 0;
							}
						}
	           		}
				}
				
				if(IsChanged == TRUE)
				{
					ret = quectel_nv_fat_write(QUEC_ELECTRIC_FENCE_CONFIG, &g_quec_electric_fence_list, sizeof(g_quec_electric_fence_list));
			     	if (ret != QUEC_SUCCESS)
					{
						atcmd_general_log("quec blackcellcfg: quec_electric_fence_config write failed"); 
					}
					else 
					{
						atcmd_general_log("quec blackcellcfg: quec_electric_fence_config write success"); 
					}
				}
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL );
           }
           else 
           {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
           }
           break;
        }
        
        case TEL_EXT_GET_CMD:
        {
            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QBLACKCELLCFGEX: %d,%d,%d,%d,%d,%d,%d,%d\r\n", 
											quec_get_black_cell_cfg_ex(),
											quec_get_black_cell_deletetimer_size(),
											quec_get_black_cell_prevention_mode(),
											quec_get_black_cell_preventiontimer_size(),
											quec_get_black_cell_reject_judge_mode(),
											quec_get_black_cell_reject_judge_num(),
											quec_get_black_cell_fence_loop_num(),
											quec_get_black_cell_fence_loop_cycle());
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
            break;
        }
        default:
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
            break;
        }
    }
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

