RETURNCODE_T quectel_exec_blacklwipcfg_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */  
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */   
    void                           *arg_p               /* AT cmd parser number */
)
{
    RETURNCODE_T    rc = INITIAL_RETURN_CODE;
    CiReturnCode    ret = CIRC_SUCCESS;
    TelAtParserID   sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32          atHandle  = MAKE_AT_HANDLE(sAtpIndex);
    int resp_len = 0;
    char res_buf[256] = {0};
    UINT8 validCmd = TRUE;
    UINT8 arg_cnt = 0;
	UINT8 arg_index = 0;

	int i=0;
	int blacklwipcfg_vaild=0;
	UINT32 blacklwip_fencenum=0;
    UINT32 blacklwip_fencecycle=0;
	UINT8 blacklwip_retrynum=0;
	char blackping_host[256]={0};
	UINT8 blackping_host_len=0;
	UINT8 blackcell_vaild=0;
    *xid_p = atHandle;
    switch (op)
    {
        case TEL_EXT_TEST_CMD:
        {	
            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QBLACKLWIPCFG: (0,1),(0-255),(0-86400),(0-255),<host>,(0,1)\r\n");
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
            break;
        }
        case TEL_EXT_SET_CMD:
        {
		   arg_cnt = quec_get_at_param_num(parameter_values_p,num_parameters);
		   atcmd_general_log("quec blackcellweight: param num = %d",arg_cnt);
		   while( (arg_index < arg_cnt) && (validCmd == TRUE) )
		   {
		  	 	switch(arg_index)
				{		
					case 0:
					{
						if( getExtValue( parameter_values_p, 0, &blacklwipcfg_vaild, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_OFF, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_ON, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_OFF) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					case 1:
					{
						if( getExtValue( parameter_values_p, 1, &blacklwip_fencenum, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_COUNT_MIN, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_COUNT_MAX, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_COUNT_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					case 2:
					{
						if( getExtValue( parameter_values_p, 2, &blacklwip_fencecycle, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_CYCLE_MIN, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_CYCLE_MAX, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_CYCLE_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					case 3:
					{
						if( getExtValue( parameter_values_p, 3, &blacklwip_retrynum, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_RETRYNUM_MIN, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_RETRYNUM_MAX, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_RETRYNUM_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					case 4:
					{
						if( getExtString( parameter_values_p, 4, &blackping_host, sizeof(blackping_host)-1, &blackping_host_len, NULL) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					case 5:
					{
						if( getExtValue( parameter_values_p, 5, &blackcell_vaild, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_BLACKCELL_INVAILD, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_BLACKCELL_VAILD, QUEC_BLACK_ELECTRIC_FENCE_LWIPCFG_BLACKCELL_DEFAULT) == FALSE )
				        {
							validCmd = FALSE;
						}
					}
					break;
					default:
				    {
				        validCmd = FALSE;
				        atcmd_general_log("quec blackcellweight: param invalid=%d",arg_cnt);
				        break;
				    }
				}
                arg_index++;
		   }
           
           if (validCmd == TRUE)
           {
		   		if(arg_cnt == 6)
				{
					g_quec_blacklwipcfg.blackcell_vaild = blacklwipcfg_vaild;
				}
				if(arg_cnt >= 5)
				{
					memset(g_quec_blacklwipcfg.blackping_host, 0, sizeof(g_quec_blacklwipcfg.blackping_host));
					strncpy(g_quec_blacklwipcfg.blackping_host, blackping_host, strlen(blackping_host));
				}
				if(arg_cnt >= 4)
				{
					g_quec_blacklwipcfg.retrynum = blacklwip_retrynum;
				}
				if(arg_cnt >= 3)
				{
					g_quec_blacklwipcfg.blacklwip_fencecycle = blacklwip_fencecycle;
				}
				if(arg_cnt >= 2)
				{
					g_quec_blacklwipcfg.blacklwip_fencenum = blacklwip_fencenum;
				}
				if(arg_cnt >= 1)
				{
					g_quec_blacklwipcfg.vaild = blacklwipcfg_vaild;
				}

				g_quec_blacklwipcfg.athandle = atHandle;
				g_quec_blacklwipcfg.blacklwip_packectcount = g_quec_blacklwipcfg.blacklwip_fencenum;
				
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL );
	       }
           else 
           {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
           }
           break;
        }
        
        case TEL_EXT_GET_CMD:
        {
			resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QBLACKLWIPCFG: %d,%d,%d,%d,\"%s\",%d\r\n",
									g_quec_blacklwipcfg.vaild,
									g_quec_blacklwipcfg.blacklwip_fencenum,
									g_quec_blacklwipcfg.blacklwip_fencecycle,
									g_quec_blacklwipcfg.retrynum,
									g_quec_blacklwipcfg.blackping_host,
									g_quec_blacklwipcfg.blackcell_vaild);
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
            break;
        }
        default:
        {
            ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL );
            break;
        }
    }
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

int quec_locate_scell_node(QuecScellALGragh ScellALGragh, UINT32 afrcn, UINT16 cellId)
{
	int i=0;
	
    for(i=0; i<ScellALGragh.vertex_num; i++)
    {
       if( (afrcn == ScellALGragh.QuecScellNodeList[i].quecscellinfo.afrcn) 
	   	&& (cellId == ScellALGragh.QuecScellNodeList[i].quecscellinfo.cellId))
        {
        	return i;
	   	}
    }
	
    return -1;
}

void quec_judge_scellpath_loop(QuecScellALGragh* ScellALGragh)
{
	int i=0;
	int DegreeStack[QUEC_SCELL_VERTEX_NUM_MAX+1] = {};
	QuecScelldegreeInfo CurrentScelldegree[QUEC_SCELL_VERTEX_NUM_MAX] = {};
	int stackindex= 0;
	UINT8 index_temp = 0;
	QuecScellSwitchArcNode *p;
	
	if(ScellALGragh == NULL)
	{
		atcmd_general_log("quec_judge_scellpath_loop: ScellALGragh NULL");
	    return ;
	}
	
	for(i = 0; i<ScellALGragh->vertex_num; i++)
	{
		CurrentScelldegree[i].indegree = ScellALGragh->QuecScellNodeList[i].quecscellinfo.indegree;
		CurrentScelldegree[i].outdegree = ScellALGragh->QuecScellNodeList[i].quecscellinfo.outdegree;
		CurrentScelldegree[i].isvisited = FALSE;
		
		if( ( (CurrentScelldegree[i].indegree == 0) || (CurrentScelldegree[i].outdegree == 0))
			&& (CurrentScelldegree[i].isvisited == FALSE))
		{
			DegreeStack[stackindex] = i;
			stackindex++;
			CurrentScelldegree[i].isvisited = TRUE;
		}
	}

	//stackindex --- Pointing to the next empty position at the top of the stack
	while(stackindex > 0)
	{
		stackindex--;
		index_temp= DegreeStack[stackindex];
		
		//indegree
		p = ScellALGragh->QuecScellNodeList[index_temp].firstarc;
		while(p != NULL)
		{
			CurrentScelldegree[p->dstvertex_index].indegree--;
			p = p->nextarc;
		}
		
		//outdegree
		for(i = 0; i<ScellALGragh->vertex_num; i++)
		{
			p = ScellALGragh->QuecScellNodeList[i].firstarc;
			while(p != NULL)
			{
				if(p->dstvertex_index == index_temp)
				{
					CurrentScelldegree[i].outdegree--;
				}
				p = p->nextarc;
			}
		}

		for(i = 0; i<ScellALGragh->vertex_num; i++)
		{			
			if( ( (CurrentScelldegree[i].indegree == 0) || (CurrentScelldegree[i].outdegree == 0))
				&& (CurrentScelldegree[i].isvisited == FALSE))
			{
				DegreeStack[stackindex] = i;
				stackindex++;
				CurrentScelldegree[i].isvisited = TRUE;
			}
		}
	}

	for(i = 0; i<ScellALGragh->vertex_num; i++)
	{			
		if(CurrentScelldegree[i].isvisited == FALSE)
		{
			ScellALGragh->QuecScellNodeList[i].quecscellinfo.isloop = TRUE;
			atcmd_general_log("quec_judge_scellpath_loop: index %d afrcn %d cellId %d",
				i,ScellALGragh->QuecScellNodeList[i].quecscellinfo.afrcn,ScellALGragh->QuecScellNodeList[i].quecscellinfo.cellId);
			if (ScellALGragh->loopflag != TRUE)
			{
				ScellALGragh->loopflag = TRUE;
			}
		}
	}
}

void quec_clear_scellpath_record(QuecScellALGragh* ScellALGragh)
{
	int i=0;
	QuecScellSwitchArcNode *p;
	QuecScellSwitchArcNode *p_next;

	if(ScellALGragh == NULL)
	{
		atcmd_general_log("quec_clear_scellpath_record: ScellALGragh NULL");
	    return;
	}
		
    for(i=0; i<ScellALGragh->vertex_num; i++)
    {
    	p = ScellALGragh->QuecScellNodeList[i].firstarc;
		while(p != NULL)
		{
			p_next = p->nextarc;
			free(p);
			p = p_next;
		}

		p = NULL;
		p_next = NULL;
		memset(&ScellALGragh->QuecScellNodeList[i],0,sizeof(ScellALGragh->QuecScellNodeList[i]));
    }
	
	ScellALGragh->vertex_num = 0;
	ScellALGragh->arc_num = 0;

}

int quec_insert_scell_node(QuecScellALGragh* ScellALGragh, UINT32 afrcn, UINT16 cellId)
{
	int insert_nodeindex = 0;
	int i=0;

	if(ScellALGragh == NULL)
	{
		atcmd_general_log("quec_insert_scell_node: ScellALGragh NULL");
	    return -1;
	}
	
	if((afrcn == 0) || (cellId == 0))
	{
		atcmd_general_log("quec_insert_scell_node: cell invaild");
	    return -1;
	}
	
    for(i=0; i<ScellALGragh->vertex_num; i++)
    {
       if( (afrcn == ScellALGragh->QuecScellNodeList[i].quecscellinfo.afrcn) 
	   	&& (cellId == ScellALGragh->QuecScellNodeList[i].quecscellinfo.cellId))
        {
        	atcmd_general_log("quec_insert_scell_node: already insert node index %d, afrcn %d, cellId %d",i,afrcn,cellId);
        	return 0;
	   	}
    }

	if(ScellALGragh->vertex_num < QUEC_SCELL_VERTEX_NUM_MAX-1)
	{
		insert_nodeindex = ScellALGragh->vertex_num;
	}
	else
	{
		atcmd_general_log("quec_insert_scell_node: scell node insert faild");
	    return -1;
	}
	
	ScellALGragh->QuecScellNodeList[insert_nodeindex].vertex_index = insert_nodeindex;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.afrcn = afrcn;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.cellId = cellId;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.arrive_num = 1;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.indegree = 0;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.outdegree = 0;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.latest_ticks[0].arrive_ticks = OSAGetTicks();
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.latest_ticks[0].srccell_index = 0xFF;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.latest_ticks[0].inarc_index = 0xFF;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.latest_ticks[0].inarc_type = 0xFF;
	ScellALGragh->QuecScellNodeList[insert_nodeindex].firstarc = NULL;
		
	atcmd_general_log("quec_insert_scell_node: insert node index %d, afrcn %d, cellId %d ticks %d",
	        insert_nodeindex,
	        ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.afrcn,
	        ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.cellId,
	        ScellALGragh->QuecScellNodeList[insert_nodeindex].quecscellinfo.latest_ticks[0].arrive_ticks);

	ScellALGragh->vertex_num++;
    return 0;
}


int quec_insert_scell_arc
(	QuecScellALGragh* ScellALGragh,     
	CiDevCommonLteCellInfo sourceLteCell, 
	CiDevCommonLteCellInfo dstceLteCell,
	UINT8                  rsrpOfsourceCell,
    UINT8                  rsrqOfsourceCell,
    UINT8                  rsrpOfdstceLteCell,
    UINT8                  rsrqOfdstceLteCell,
    UINT8                  eventtype)
{
	int insert_acrindex = 0;
	int src_index = 0;
	int dst_index = 0;
	UINT32 start_ticks = 0;
	UINT32 end_ticks = 0;
	UINT32 loop_sec_ms = 0;
	int ret = 0;
	int i = 0;
	bool IsNewpath= TRUE;
	QuecScellSwitchArcNode *InsertArc;
	QuecScellSwitchArcNode *p;
	CiDevPrimSetCellSelectCfgReq pSetCellSelectCfgReq = {0}; 
	UINT8 minrsrp_value = 0;
	UINT8 minrsrp_index = 0;
	UINT8 minrsrq_value = 0;
	UINT8 minrsrq_index = 0;
	UINT8 reselectcount_temp[QUEC_SCELL_VERTEX_NUM_MAX]={0};
	UINT8 worst_index = 0;
	UINT8 worst_value = 0;

	if(ScellALGragh == NULL)
	{
		atcmd_general_log("quec_insert_scell_arc: ScellALGragh NULL");
	    return -1;
	}

	if((sourceLteCell.euArfcn == 0) || (dstceLteCell.euArfcn == 0)
	 ||(sourceLteCell.euArfcn == 0xFFFFFFFF) || (dstceLteCell.euArfcn == 0xFFFFFFFF))
	{
		atcmd_general_log("quec_insert_scell_arc: cell invaild");
	    return -1;
	}

	if(ScellALGragh->arc_num < QUEC_SCELL_ARC_NUM_MAX-1)
	{
		insert_acrindex = ScellALGragh->arc_num;
	}
	else
	{
		atcmd_general_log("quec_insert_scell_arc: arc insert faild");
	    return -1;
	}
	

    src_index = quec_locate_scell_node(*ScellALGragh,sourceLteCell.euArfcn,sourceLteCell.phyCellId);
	atcmd_general_log("quec_insert_scell_arc: src node index %d, afrcn %d, cellId %d",src_index,sourceLteCell.euArfcn,sourceLteCell.phyCellId);

	if(src_index < 0) 
	{
		ret =quec_insert_scell_node(ScellALGragh,sourceLteCell.euArfcn,sourceLteCell.phyCellId);
		if(ret != 0) 
		{
			atcmd_general_log("quexc_insert_scell_arc: src node insert faild");
			return -1;
		}
		src_index = quec_locate_scell_node(*ScellALGragh,sourceLteCell.euArfcn,sourceLteCell.phyCellId);
	}

    dst_index = quec_locate_scell_node(*ScellALGragh,dstceLteCell.euArfcn,dstceLteCell.phyCellId);
	atcmd_general_log("quec_insert_scell_arc: dst node index %d, afrcn %d, cellId %d",dst_index,dstceLteCell.euArfcn,dstceLteCell.phyCellId);	
	if(dst_index < 0) 
	{
		ret =quec_insert_scell_node(ScellALGragh,dstceLteCell.euArfcn,dstceLteCell.phyCellId);
		if(ret != 0) 
		{
			atcmd_general_log("quec_insert_scell_arc: dst node insert faild");
			return -1;
		}
		dst_index = quec_locate_scell_node(*ScellALGragh,dstceLteCell.euArfcn,dstceLteCell.phyCellId);
	}

	atcmd_general_log("quec_insert_scell_arc: node init success %d %d",src_index,dst_index);

	p = ScellALGragh->QuecScellNodeList[src_index].firstarc;
	while(p != NULL)
	{
		if(p->dstvertex_index == dst_index)
		{
			atcmd_general_log("quec_insert_scell_arc: path already insert do not judge loop arc index %d, src %d, dst %d",p->arc_index,src_index,dst_index);
			IsNewpath = FALSE;
		}
		p = p->nextarc;
	}

	//graph arc
	InsertArc = (QuecScellSwitchArcNode*)malloc(sizeof(QuecScellSwitchArcNode));
	InsertArc->arc_index = insert_acrindex;
	InsertArc->dstvertex_index = dst_index;
	InsertArc->switch_ticks = OSAGetTicks();
	InsertArc->switch_type = eventtype;
	InsertArc->nextarc = ScellALGragh->QuecScellNodeList[src_index].firstarc;
	ScellALGragh->arc_num++;

	//sourcecell
	ScellALGragh->QuecScellNodeList[src_index].firstarc = InsertArc;
	ScellALGragh->QuecScellNodeList[src_index].quecscellinfo.outdegree++;
	if ((rsrpOfsourceCell != 0xFF) && (rsrpOfsourceCell != 0))
	{
		ScellALGragh->QuecScellNodeList[src_index].quecscellinfo.rsrp = rsrpOfsourceCell;
	}

	if ((rsrqOfsourceCell != 0xFF) && (rsrqOfsourceCell != 0))
	{
		ScellALGragh->QuecScellNodeList[src_index].quecscellinfo.rsrq = rsrqOfsourceCell;
	}

	//destcell
	if (ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num >0)
	{
		//quecscellinfo.latest_ticks[10],9 corresponds to the upper limit
		for(i= (ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num > 9) ? 9 : ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num; i>0; i--)
		{
#if 1
			atcmd_general_log("test quec_insert_scell_arc: i %d %d %d",ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num,9,i);
#endif
			ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].arrive_ticks 
				= ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i-1].arrive_ticks;
			ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].srccell_index 
				= ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i-1].srccell_index;
			ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].inarc_index 
				= ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i-1].inarc_index;
			ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].inarc_type 
				= ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i-1].inarc_type;
		}
	}
	ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.indegree++;
	ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[0].arrive_ticks = InsertArc->switch_ticks;
	ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[0].srccell_index = src_index;
	ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[0].inarc_index = InsertArc->arc_index;
	ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[0].inarc_type = InsertArc->switch_type;
	ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num++;
	
	if ((rsrpOfdstceLteCell != 0xFF) && (rsrpOfdstceLteCell != 0))
	{
		ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrp = rsrpOfdstceLteCell;
	}

	if ((rsrqOfdstceLteCell != 0xFF) && (rsrqOfdstceLteCell != 0))
	{
		ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrq = rsrqOfdstceLteCell;
	}

	atcmd_general_log("quexc_insert_scell_arc: src %d %d %d dst %d %d %d arcindex %d arriveticks %d arrivetime %d",
			src_index,rsrpOfsourceCell,rsrqOfsourceCell,
			dst_index,rsrpOfdstceLteCell,rsrqOfdstceLteCell,
			InsertArc->arc_index,
			InsertArc->switch_ticks,
			ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num);


	if(IsNewpath == TRUE)
	{

		quec_judge_scellpath_loop(ScellALGragh);

	}

	if(ScellALGragh->loopflag == TRUE)
	{
		if(ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.isloop == TRUE)
	    {
	 		if(ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.arrive_num >= (quec_get_black_cell_fence_loop_num() + 1))
			{
				start_ticks = ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[2].arrive_ticks;
				end_ticks = ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[0].arrive_ticks;
				loop_sec_ms = (end_ticks - start_ticks) * 5;
				atcmd_general_log("quexc_insert_scell_arc: loop start_ticks %d end_ticks %d loop_sec_ms %d",start_ticks,end_ticks,loop_sec_ms);

				if(loop_sec_ms <= (quec_get_black_cell_fence_loop_cycle()*1000))
				{
					if(ScellALGragh->loop_level == 0)
					{
						pSetCellSelectCfgReq.offset_scell 		    = 	5;
						pSetCellSelectCfgReq.offset_ncell_lte 		= 	5;
						ret = DEV_SetCellSelectOffset((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE),&pSetCellSelectCfgReq);
						/*ret = DEV_SetMeasReportConfigData((isMasterSim0() ? SIMULATE_SIM1_REQ_HANDLE : SIMULATE_SIM2_REQ_HANDLE),10,-10);*/

						quec_clear_scellpath_record(ScellALGragh);
						ScellALGragh->loop_level = 1;
					}
					else 
					{
#if 1
						memset(reselectcount_temp,0,sizeof(reselectcount_temp));
						
						for(i=0; i<quec_get_black_cell_fence_loop_num(); i++)
						{
							if(ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].srccell_index < ScellALGragh->vertex_num)
							{
								if(ScellALGragh->QuecScellNodeList[ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].srccell_index].quecscellinfo.isloop == TRUE)
								{
									reselectcount_temp[ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.latest_ticks[i].srccell_index]++;
								}
							}
						}

						worst_index = src_index;
						worst_value = 1;

						for(i=0; i<ScellALGragh->vertex_num; i++)
						{
							if(reselectcount_temp[i] > worst_value)
							{
								worst_index = i;
								worst_value = reselectcount_temp[i];
									
							}
						}

						atcmd_general_log("quexc_insert_scell_arc: reslect judge index %d num %d",worst_index,worst_value);	
						
						minrsrq_value = ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrq;
						minrsrq_index = dst_index;
						minrsrp_value = ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrp;
						minrsrp_index = dst_index;
						atcmd_general_log("quexc_insert_scell_arc: dst %d rsrq %d rsrp %d, worst %d  rsrq %d rsrp %d",
							dst_index,
							ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrq,
							ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrp,
							worst_index,
							ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.rsrq,
							ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.rsrp);	
						
						if(ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrq > ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.rsrq)
						{
							minrsrq_value = ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.rsrq;
							minrsrq_index = worst_index;
						}
						
						if(ScellALGragh->QuecScellNodeList[dst_index].quecscellinfo.rsrp > ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.rsrp)
						{
							minrsrp_value = ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.rsrp;
							minrsrp_index = worst_index;
						}

						// RSRQ 3GPP converted to -15 
						if(minrsrq_value < 10)
						{
							quec_electric_fence_list_set_blackcell(
								BLACKCELL_ADD,
								BLACKCELL_LTE,
								ScellALGragh->QuecScellNodeList[minrsrq_index].quecscellinfo.afrcn,
								ScellALGragh->QuecScellNodeList[minrsrq_index].quecscellinfo.cellId,
								quec_get_black_event_weight(FENCE_REGISTER_PING_PONG),
								FENCE_REGISTER_PING_PONG);
						}
						else 
						{
							quec_electric_fence_list_set_blackcell(
								BLACKCELL_ADD,
								BLACKCELL_LTE,
								ScellALGragh->QuecScellNodeList[minrsrp_index].quecscellinfo.afrcn,
								ScellALGragh->QuecScellNodeList[minrsrp_index].quecscellinfo.cellId,
								quec_get_black_event_weight(FENCE_REGISTER_PING_PONG),
								FENCE_REGISTER_PING_PONG);
						}	

						quec_clear_scellpath_record(ScellALGragh);
						ScellALGragh->loop_level++;
#else					
					    worst_index = quec_judge_scellpath_loop_by_node(ScellALGragh,dst_index);

						if(worst_index != -1)
						{							
								quec_electric_fence_list_set_blackcell(
								BLACKCELL_ADD,
								BLACKCELL_LTE,
								ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.afrcn,
								ScellALGragh->QuecScellNodeList[worst_index].quecscellinfo.cellId,
								quec_get_black_event_weight(FENCE_REGISTER_PING_PONG),
								FENCE_REGISTER_PING_PONG);

								quec_clear_scellpath_record(ScellALGragh);
								ScellALGragh->loop_level++;
						}
#endif

					}
				}
			}
		}
	}
	
    return 0;
}
