extern void USB2MgrDeviceUnplug(void);
extern void USB2MgrDevicePlugIn(void);
extern BOOL USB2MgrIsDeviceControllerEnabled (void);
RETURNCODE_T  quectel_exec_qdbgcfg_usbunplug_cmd
(
         const utlAtParameterOp_T        op,                 /* AT cmd type          */
         const char                     *command_name_p,     /* AT cmd name          */
         const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
         const size_t                    num_parameters,     /* AT cmd number        */
         const char                     *info_text_p,        /* AT cmd usage string  */
         unsigned int                   *xid_p,              /* AT cmd handle        */
         void                           *arg_p
)
{
	TelAtParserID sAtpIndex = * (TelAtParserID *) arg_p;
    UINT32 atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    
	 *xid_p = atHandle;
	RETURNCODE_T rc = INITIAL_RETURN_CODE;
	CiReturnCode ret = CIRC_FAIL;
	uint8 num_param = quec_get_at_param_num(parameter_values_p, num_parameters);

    char res_buf[100] = {0};
    UINT8 resp_len = 0;

    char  cfg_cmd_param_str[20] = {0};
    UINT8 cfg_cmd_param_str_len = 0;
	int trace_len = 0;
	int current_len;
	int position_param = 0;
	int position = 0;
	
    atcmd_general_log("command type=%d,param_num=%d", op, num_param);
	
	switch(op)
	{
		case TEL_EXT_SET_CMD:
		{
	        if (num_param == 1)
	        {
	            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QDBGCFG: \"usb/unplug\",%d", 
					!USB2MgrIsDeviceControllerEnabled());
	            //ret = quec_siolib_transmit_to_atp(sAtpIndex, res_buf, resp_len, NULL);
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
	            break;
	        }
	        else if (num_param == 2)
	        {
                position_param =parameter_values_p[1].value.decimal;
                atcmd_general_log("position_param=%d", position_param);
				if (position_param == 0)
				{
                    USB2MgrDevicePlugIn();
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				}
				else if (position_param == 1)
				{
                    USB2MgrDeviceUnplug();
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				}
				else
				{
	                 ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
					 break;
				}
	        }
	        else
	        {
	             ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, CME_INVALID_PARAM, NULL);
	        }
	        break;
    	}
		case TEL_EXT_GET_CMD:
		case TEL_EXT_TEST_CMD:
        {
            resp_len = snprintf(res_buf, sizeof(res_buf)-1, "+QDBGCFG: \"usb/unplug\",(0,1)\r\n");
            ret = quec_siolib_transmit_to_atp(sAtpIndex, res_buf, resp_len, NULL);
            break;
        }
		default:
        {
            ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
            break;
        }
	}
	/* handle the return value */
	rc = HANDLE_RETURN_VALUE(ret);
	return rc;

}

RETURNCODE_T  quectel_exec_qdbgcfg_gps_debug_level_cmd
(
         const utlAtParameterOp_T        op,                 /* AT cmd type          */
         const char                     *command_name_p,     /* AT cmd name          */
         const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */
         const size_t                    num_parameters,     /* AT cmd number        */
         const char                     *info_text_p,        /* AT cmd usage string  */
         unsigned int                   *xid_p,              /* AT cmd handle        */
         void                           *arg_p
)
{
    RETURNCODE_T     rc       = INITIAL_RETURN_CODE;
    CiReturnCode     ret      = CIRC_FAIL;
    QuecOSStatus status=QUEC_SUCCESS;
    QuecOSStatus quec_status=QUEC_SUCCESS;

    UINT32  atHandle = MAKE_AT_HANDLE(* (TelAtParserID *) arg_p);
    *xid_p = atHandle;
    UINT32 index  = *(TelAtParserID *)arg_p;
    UINT8 param_num=0;
    
    char res_buf[50]={0};
    UINT8 resp_len=0;
    int gps_level =0;   
    /*
     **  Check the format of the request.
     */
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);

    atcmd_general_log("command type=%d,param_num=%d",op,param_num);
    switch (op)
    {
        case TEL_EXT_SET_CMD:    /* AT+QDBGCFG="interrupt/log",..  */
            {
                if(param_num == 1)
                {
                	#ifdef QUEC_AT_GPS_ENABLE
                    resp_len=snprintf(res_buf,sizeof(res_buf)-1,"+QDBGCFG: \"gps/debug\",%d\r\n",gps_get_debug_level());
					#endif
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, res_buf);
                    break;
                }
                else if(param_num == 2)
                {
                    gps_level = parameter_values_p[1].value.decimal; 
                    atcmd_general_log("gps_level: %d",gps_level);
					#ifdef QUEC_AT_GPS_ENABLE
                   	gps_set_debug_level(gps_level);
					#endif
                   	ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, NULL); 
                    
                }
                else
                {   
                    atcmd_general_log("param_num=%d is invalid", param_num);
                    ret = ATRESP( atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);  
                    break;
                }

             break;
            }
        
        default:
            {
                ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_OPERATION_NOT_SUPPORTED, NULL);
                break;
            }

    }

    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret);
    return(rc);
}

