void quec_set_uestat_limit(BOOL set_limit)
{
    if(set_limit==TRUE)
    {
        quec_uestat=QUEC_UESTAT_PLMN_LIMIT;
    }
    else
    {
        CPUartLogPrintf("%s,%d,CFUN=%d",__FUNCTION__,__LINE__,GetCfunValue());
         if(GetCfunValue()==ATCI_CFUN_OP_FULL_FUNC)
        {
            quec_uestat=QUEC_UESTAT_NORMAL;
        }
        else
        {
            quec_uestat=QUEC_UESTAT_CFUN_LIMIT;
        }
    }
}
UINT8 quec_get_uestat(void)
{
   UINT8 quec_stat_temp=QUEC_UESTAT_NORMAL;
   if((quec_uestat!=QUEC_UESTAT_PLMN_LIMIT)&&(GetCfunValue()!=ATCI_CFUN_OP_FULL_FUNC))
   {
       quec_stat_temp=QUEC_UESTAT_CFUN_LIMIT;
   }
   else
   {
       quec_stat_temp=quec_uestat;
   }
   return quec_stat_temp;
}

