int quomark_enable=0;
//AT+QCFG="sms/quomark" to set if the msgtxt with "" when recieve UCS2 CODE msg
RETURNCODE_T quectel_exec_qcfg_sms_quomark_cmd
(
		const utlAtParameterOp_T	  op,
		const char					 *command_name_p,
		const utlAtParameterValue_P2c parameter_values_p,
		const size_t				  num_parameters,
		const char					 *info_text_p,
		unsigned int				 *xid_p,
		void						 *arg_p
)
{
	RETURNCODE_T rc= utlSUCCESS;
	CiReturnCode ret=CIRC_FAIL;
	UINT32 atHandle =	*xid_p;
	UINT32 index    =   (*(TelAtParserID *)arg_p);
	UINT8   param_num=0;
    INT16   resp_len=0;
    char    resp_buf[256]={0};
    param_num=quec_get_at_param_num(parameter_values_p,num_parameters);
    int value=0;
    char  cfg_cmd_param_str[20] = {0};
    INT16 cfg_cmd_param_str_len=0;

	switch(op){

    case TEL_EXT_TEST_CMD:
           resp_len = snprintf(resp_buf,sizeof(resp_buf)-1,"+QCFG: \"sms/quomark\",(0,1)\r\n");
           ret=quec_siolib_transmit_to_atp((TelAtParserID)index,(uint8 *)resp_buf,(uint32) resp_len, NULL);       
    break;

	case TEL_EXT_SET_CMD:
		if(param_num == 1)
		{
		    resp_len = snprintf(resp_buf,sizeof(resp_buf)-1,"+QCFG: \"sms/quomark\",%d\r\n",quomark_enable);
            ret=ATRESP(atHandle,ATCI_RESULT_CODE_OK, 0, resp_buf);
		}
		else if (param_num == 2)
		{
			if (getExtString(parameter_values_p, 1, cfg_cmd_param_str, 20, &cfg_cmd_param_str_len, NULL) == TRUE)
    		{
    			 if(str2int32(cfg_cmd_param_str,1,&value))  
    			 {
    				 atcmd_general_log(" value=%d",value);
    				if(value>1)
                    {
						ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
						break;
                    }
					else
                    {
                        quomark_enable=value;
                    }
        		    ret=ATRESP(atHandle,ATCI_RESULT_CODE_OK, 0, NULL);
    			 }
    			 else
    			 {
    				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
    				break;
    			 }
    		}
    		else
    		{
    			 ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
    			 break;
    		}
		}
		else
		{
			ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
		}
	break;
	default:
		ret=ATRESP(atHandle,ATCI_RESULT_CODE_ERROR, 0, NULL);
	break;
   }
	
	rc=HANDLE_RETURN_VALUE(ret);
	return rc;
}


