quec_autoapn_cfg g_quec_autoapn_cfg = {QUEC_AUTO_APN_CFG_OFF,QUEC_AUTOAPN_NULL,"0000000000000000",0};
extern BOOL quec_autoapn_table_link_init_by_mccmnc(INT16 mcc,INT16 mnc);

bool g_quec_autopan_urc = FALSE;
bool quec_get_autoapnurc_status(void)
{
	return g_quec_autopan_urc;
}

void quec_set_autoapnurc_status(bool status)
{
	g_quec_autopan_urc = status;
}

RETURNCODE_T quec_exec_qautoapnurc_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */  
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */   
    void                           *arg_p               /* AT cmd parser number */
)
{
  
    RETURNCODE_T    rc       = INITIAL_RETURN_CODE;
    CiReturnCode    ret      = CIRC_FAIL;
    UINT32           atHandle = MAKE_AT_HANDLE(*(TelAtParserID*)arg_p);

    *xid_p = atHandle;
    int quec_autoapnurc_status_temp = 0;
	char resp_buf[32] = {0};
	
    switch (op)
    {
    
        case TEL_EXT_GET_CMD:    
        {           
			sprintf(resp_buf, "+QAUTOAPNURC: %d", quec_get_autoapnurc_status());
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, resp_buf);
			break;
        }
		case TEL_EXT_SET_CMD:
		{
			if( getExtValue( parameter_values_p, 0, &quec_autoapnurc_status_temp, QUEC_AUTO_APN_URC_OFF, QUEC_AUTO_APN_URC_ON, QUEC_AUTO_APN_URC_OFF ) == TRUE )
			{
				if(quec_get_autoapnurc_status() != quec_autoapnurc_status_temp)
				{
					quec_set_autoapnurc_status(quec_autoapnurc_status_temp);
					ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				}
				else  
				{
					ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				}
			}				
			else 
			{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
			}															
			break;
		}
		case TEL_EXT_TEST_CMD:
		{          
			sprintf(resp_buf, "+QAUTOAPNURC: (0,1)");
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, resp_buf);
			break;
        }	
        case TEL_EXT_ACTION_CMD:    
        default:
            {
                ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
                break;
            }
 
    }
     
    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret); 
    return(rc);
}

