void quec_autoapn_table_link_init_by_current_imsi()
{
	char mcc[4] = {0};
	char mnc[4] = {0};
	INT16 mccnum=0;
	INT16 mncnum=0;
	char operApnNode_apn[128] = {0};
	char operApnNode_iptype[32] = {0};

	memcpy(mcc,g_quec_autoapn_cfg.current_IMSI,3);
	mcc[3] = '\0';
	str2int32(mcc,3,&mccnum);	
	
	memcpy(mnc,g_quec_autoapn_cfg.current_IMSI+3,getMncLen());
	mnc[getMncLen()] = '\0';
	str2int32(mnc,3,&mncnum);	
	
	quec_autoapn_table_link_init_by_mccmnc(mccnum,mncnum);
	quec_autoapn_table_node_move(0,operApnNode_apn,operApnNode_iptype);
}

void quec_autoapn_adjustconfig_init(void)
{
	quec_autoapn_cfg quec_autoapn_cfg_temp;

	if(QUEC_FAT_SUCCESS != quectel_nv_fat_read(QUEC_AUTO_APN_CONFIG, &quec_autoapn_cfg_temp, sizeof(quec_autoapn_cfg)))
	{
		CPUartLogPrintf("quec_autoapn%s, read failed!", __func__);
	}
	else
	{
		memcpy(&g_quec_autoapn_cfg, &quec_autoapn_cfg_temp,sizeof(quec_autoapn_cfg));
		CPUartLogPrintf("quec_autoapn %s, read %d", __func__,g_quec_autoapn_cfg.vaild);
	}

	if(quec_get_autoapn_cfg_vaild() == TRUE)
	{
		RTI_LOG("quec_autoapn quec_autoapn_table_link_init_by_current_imsi first init");
		quec_autoapn_table_link_init_by_current_imsi();
	}
}

void quec_autoapn_imsi_judge(char *simRspImsiBuf,INT32 len)
{
	static bool Is_Init = FALSE;
	bool Is_Imsi_Changed = FALSE;
	int autoapn_msg = QUEC_IMSI_UPDATE;

	Is_Imsi_Changed = strncmp(g_quec_autoapn_cfg.current_IMSI,simRspImsiBuf,len);

	if(Is_Imsi_Changed)
	{
		CPUartLogPrintf("quec_autoapn %s, mastercard imsi change %s to %s len %d", __func__,g_quec_autoapn_cfg.current_IMSI,simRspImsiBuf,len);
		memcpy(&g_quec_autoapn_cfg.current_IMSI, simRspImsiBuf, len);
		if(quec_get_autoapn_cfg_vaild() == TRUE)
		{
			quec_send_msg_to_handle_task(QUEC_AUTO_APN_EVENT_MSG, (char *)&autoapn_msg, sizeof(int));
		}
	}
}

void quec_autoapn_handle_by_event(int event)
{
	bool NeedUpdate = FALSE; 
	int ret = 0;
	QUEC_APN_INFO operApnNode;
	char operApnNode_apn[100] = {0};
	char operApnNode_iptype[100] = {0};
    char apn_at_str[256] = {0};
	char reportBuf[128] = {0};

	CPUartLogPrintf("quec_autoapn_handle_by_event: event %d status %d",event,quec_get_autoapn_adjust_status());
	switch (event)
    {
        case QUEC_IMSI_UPDATE:    
        {      
        	/*autoapn_table_link_init*/
			quec_autoapn_table_link_init_by_current_imsi();

			/*If already matched, default initialization*/
			if(g_quec_autoapn_cfg.adjust_status == QUEC_AUTOAPN_COMPLETED)
			{				
				memset(apn_at_str,0,sizeof(apn_at_str));
				sprintf(apn_at_str,"AT+CGDCONT=%d,\"IPV4V6\",\"\"\r\n",qcfg_ltedftcid);

				g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_SYNC;
				SendATCMDWaitResp(isMasterSim0()? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2,
		               apn_at_str, 10, NULL, 1, NULL, NULL, 0);
				g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_NULL;
				NeedUpdate = TRUE;

				if(quec_get_autoapnurc_status() == QUEC_AUTO_APN_URC_ON)
				{
					memset(reportBuf, 0, 128);
					sprintf(reportBuf, "+QAUTOAPNURC: IMSI update, Clear matching configurations\r\n");
					at_urc_send(NUM_OF_TEL_ATP, (UINT8 *)reportBuf, strlen(reportBuf), TRUE, URC_OUT_METHOD_UNICAST, NULL);
				}
			}

			if(g_quec_autoapn_cfg.adjust_status != QUEC_AUTOAPN_SUSPEND)
			{
				g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_NULL;
			}
		
			break;
        }
		case QUEC_PDP_REJECT_SPECIAL:
		{	
			if(g_quec_autoapn_cfg.adjust_status != QUEC_AUTOAPN_MATCHING)
			{
				CPUartLogPrintf("quec_autoapn %s, adjust status %d to 1", __func__,g_quec_autoapn_cfg.adjust_status);
				g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_MATCHING;
			}

			if (quec_autoapn_table_node_move(2,operApnNode_apn,operApnNode_iptype) == TRUE)
			{
				memset(apn_at_str,0,sizeof(apn_at_str));

				if(quec_get_autoapnurc_status() == QUEC_AUTO_APN_URC_ON)
				{
					memset(reportBuf, 0, 128);
					sprintf(reportBuf, "+QAUTOAPNURC: ApnNode %s %s\r\n",operApnNode_iptype,operApnNode_apn);
					at_urc_send(NUM_OF_TEL_ATP, (UINT8 *)reportBuf, strlen(reportBuf), TRUE, URC_OUT_METHOD_UNICAST, NULL);
				}
				
				CPUartLogPrintf("quec_autoapn node %s %s",operApnNode_iptype,operApnNode_apn);
				sprintf(apn_at_str,"AT*CGDFLT=0,\"%s\",\"%s\",,,,,,,,,,,,,,,,,,1\r\n",operApnNode_iptype,operApnNode_apn);
				SendATCMDWaitResp(isMasterSim0()? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2,
               	   "AT+CFUN=4\r\n", 20, NULL, 1, NULL, NULL, 0);

   				SendATCMDWaitResp(isMasterSim0()? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2,
	               apn_at_str, 20, NULL, 1, NULL, NULL, 0);
				
				SendATCMDWaitResp(isMasterSim0()? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2,
                   "AT+CFUN=1\r\n", 20, NULL, 1, NULL, NULL, 0);
			}
			else 
			{
				memset(apn_at_str,0,sizeof(apn_at_str));
				sprintf(apn_at_str,"AT+CGDCONT=%d,\"IPV4V6\",\"\"\r\n",qcfg_ltedftcid);

				g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_SYNC;
				SendATCMDWaitResp(isMasterSim0()? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2,
		               apn_at_str, 10, NULL, 1, NULL, NULL, 0);
				g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_FAIL;
				NeedUpdate = TRUE;
				
				CPUartLogPrintf("quec_autoapn %s, quec_autoapn_table_node_move fail", __func__);

				if(quec_get_autoapnurc_status() == QUEC_AUTO_APN_URC_ON)
				{
					memset(reportBuf, 0, 128);
					sprintf(reportBuf, "+QAUTOAPNURC: Matching failed\r\n");
					at_urc_send(NUM_OF_TEL_ATP, (UINT8 *)reportBuf, strlen(reportBuf), TRUE, URC_OUT_METHOD_UNICAST, NULL);
				}
				return;
			}
			break;
		} 
		case QUEC_PDP_ACTIVATE:
		{
			if(quec_get_autoapn_adjust_status() == QUEC_AUTOAPN_MATCHING)
			{
				if (quec_autoapn_table_node_move(1,operApnNode_apn,operApnNode_iptype) == TRUE)
				{
					memset(apn_at_str,0,sizeof(apn_at_str));
					sprintf(apn_at_str,"AT+CGDCONT=%d,\"%s\",\"%s\"\r\n",qcfg_ltedftcid,operApnNode_iptype,operApnNode_apn);

					g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_SYNC;
					SendATCMDWaitResp(isMasterSim0()? TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM1 : TEL_AT_CMD_ATP_QUEC_INTERNAL_SIM2,
			               apn_at_str, 20, NULL, 1, NULL, NULL, 0);
					g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_COMPLETED;
					NeedUpdate = TRUE;

					if(quec_get_autoapnurc_status() == QUEC_AUTO_APN_URC_ON)
					{
						memset(reportBuf, 0, 128);
						sprintf(reportBuf, "+QAUTOAPNURC: Matching completed\r\n",operApnNode_iptype,operApnNode_apn);
						at_urc_send(NUM_OF_TEL_ATP, (UINT8 *)reportBuf, strlen(reportBuf), TRUE, URC_OUT_METHOD_UNICAST, NULL);
					}
						
				}
			}
			
			break;
        }	  
        default:
        {
			CPUartLogPrintf("quec_autoapn_handle_by_event: invaild event %d",event);
			return;
        }
    }

	if(NeedUpdate)
	{
		quec_update_autoapn_config();
	}
}

RETURNCODE_T quec_exec_qautoapn_cmd
(
    const utlAtParameterOp_T        op,                 /* AT cmd type          */
    const char                     *command_name_p,     /* AT cmd name          */
    const utlAtParameterValue_P2c   parameter_values_p, /* AT cmd value         */  
    const size_t                    num_parameters,     /* AT cmd number        */
    const char                     *info_text_p,        /* AT cmd usage string  */
    unsigned int                   *xid_p,              /* AT cmd handle        */   
    void                           *arg_p               /* AT cmd parser number */
)
{
  
    RETURNCODE_T    rc       = INITIAL_RETURN_CODE;
    CiReturnCode    ret      = CIRC_FAIL;
    UINT32           atHandle = MAKE_AT_HANDLE(*(TelAtParserID*)arg_p);

    *xid_p = atHandle;
    int quec_autoapn_flag_temp = 0;
	char resp_buf[32] = {0};
	
    switch (op)
    {
    
        case TEL_EXT_GET_CMD:    
        {           
			sprintf(resp_buf, "+QAUTOAPN: %d,%d", g_quec_autoapn_cfg.vaild,quec_get_autoapn_adjust_status());
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, resp_buf);
			break;
        }
		case TEL_EXT_SET_CMD:
		{
			if( getExtValue( parameter_values_p, 0, &quec_autoapn_flag_temp, QUEC_AUTO_APN_CFG_OFF, QUEC_AUTO_APN_CFG_ON, QUEC_AUTO_APN_CFG_OFF ) == TRUE )
			{
				if(g_quec_autoapn_cfg.vaild != quec_autoapn_flag_temp)
				{
					g_quec_autoapn_cfg.vaild = quec_autoapn_flag_temp;
					if(quec_get_autoapn_cfg_vaild() == TRUE)
					{
						quec_autoapn_table_link_init_by_current_imsi();
						g_quec_autoapn_cfg.adjust_status = QUEC_AUTOAPN_NULL;
					}
					
					if (quectel_nv_fat_write(QUEC_AUTO_APN_CONFIG, &g_quec_autoapn_cfg, sizeof(g_quec_autoapn_cfg)) == QUEC_SUCCESS)
					{
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
					}
					else 
					{
						atcmd_general_log("quec_autoapn g_quec_autoapn_cfg write failed"); 
						ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
					}
				}
				else  
				{
					ret = ATRESP(atHandle, ATCI_RESULT_CODE_OK, 0, NULL);
				}
			}				
			else 
			{
				ret = ATRESP( atHandle, ATCI_RESULT_CODE_CME_ERROR, CME_INVALID_PARAM, NULL);
			}															
			break;
		}
		case TEL_EXT_TEST_CMD:
		{      
			sprintf(resp_buf, "+QAUTOAPN: (0,1)");
		    ret = ATRESP( atHandle, ATCI_RESULT_CODE_OK, 0, resp_buf);
			break;
        }	
        case TEL_EXT_ACTION_CMD:    
        default:
            {
                ret = ATRESP(atHandle, ATCI_RESULT_CODE_ERROR, 0, NULL);
                break;
            }
 
    }
     
    /* handle the return value */
    rc = HANDLE_RETURN_VALUE(ret); 
    return(rc);
}

bool quec_get_defaultcid_matching_status(UINT8 cid)
{
	if((quec_get_autoapn_cfg_vaild() == TRUE) && (quec_get_autoapn_adjust_status() == QUEC_AUTOAPN_MATCHING) && (cid == qcfg_ltedftcid))
	{
		return TRUE;
	}
	else 
	{
		return FALSE;
	}
}

