int quec_get_net_flag_by_cid(int cid)
{
    if ((cid > QUEC_NET_DUALCH_16) || (cid < QUEC_NET_DUALCH_1))
    {
        atcmd_general_log("qnetdualchcfg: cid %d is invaild",cid);
        return QUEC_NET_DEFAULT_FLAG;
    }
    if(QUEC_NET_DEFAULT_PASS_FLAG == g_quec_net_dualch_cfg[cid - 1].net_flag)
    {
        return QUEC_NET_DEFAULT_FLAG;
    }
    return g_quec_net_dualch_cfg[cid-1].net_flag;
}

int quec_isValidMacAddress(const char* mac)
{
    int i = 0;  /* 12锟斤拷16锟斤拷锟斤拷锟斤拷锟斤拷 */
    int s = 0;  /* number of ':' or '-' */

    while (*mac)
    {
       if (isxdigit(*mac))
       {
          i++;
       }
       else if ( (*mac == ':') || (*mac == '-') )
       {
          if ( (i == 0) || (i / 2 - 1 != s) )
          {
            break;
          }
          ++s;
       }
       else

       {
           s = -1;
       }
       ++mac;
    }
    return ( (i == 12) && (s == 5 || s == 0) );
}

